window.pregnancyArticleList = [{"id":"pregnancy-001","number":1,"week":1,"title":"Почему беременность считают с первого дня последней менструации","image":null,"blocks":[{"type":"paragraph","text":"Вы только увидели две полоски, а врач уже говорит о четырёх неделях беременности. Откуда взялись дополнительные недели? Дело в точке отсчёта: акушерский срок считают с первого дня последней менструации."},{"type":"heading","text":"Почему отсчёт начинается до зачатия"},{"type":"paragraph","text":"День зачатия при естественной беременности обычно неизвестен. Овуляция — выход яйцеклетки из яичника — может происходить в разные дни цикла. Даже регулярный цикл не означает, что она всегда наступает строго на 14-й день."},{"type":"paragraph","text":"Поэтому врачи используют общий ориентир — начало последней менструации. Это позволяет одинаково рассчитывать срок и предполагаемую дату родов. При стандартном расчёте к этой дате прибавляют 280 дней, или 40 недель. Такая схема предполагает цикл продолжительностью 28 дней и требует уточнения, если цикл отличается."},{"type":"heading","text":"Как это выглядит на примере"},{"type":"paragraph","text":"Представим, что менструация началась четыре недели назад, а овуляция и зачатие произошли примерно через две недели после её начала."},{"type":"paragraph","text":"Тогда:"},{"type":"list-item","text":"акушерский срок — около четырёх недель;"},{"type":"list-item","text":"время, прошедшее после зачатия, — около двух недель."},{"type":"paragraph","text":"Разница возникает из-за способа подсчёта. При более ранней или поздней овуляции она будет другой: автоматически вычитать две недели из срока можно только приблизительно. Обычно овуляция происходит примерно за 14 дней до следующей менструации, а не обязательно на 14-й день цикла."},{"type":"heading","text":"Если цикл нерегулярный или дата забыта"},{"type":"paragraph","text":"Сообщите об этом врачу. Не нужно выбирать примерную дату наугад: расчёт по менструации в такой ситуации может быть неточным."},{"type":"paragraph","text":"УЗИ в первом триместре помогает уточнить срок по размерам малыша. Врач сопоставляет результаты с датой менструации и определяет, какой срок использовать дальше. Предполагаемая дата родов при этом остаётся ориентиром: заранее установить точный день рождения нельзя."},{"type":"heading","text":"Что записать перед приёмом"},{"type":"paragraph","text":"Первый день последней менструации, обычную продолжительность цикла и то, насколько он регулярный. Если дата неизвестна, так и скажите. После уточнения срока используйте в календаре приложения срок, установленный врачом."}]},{"id":"pregnancy-002","number":2,"week":1,"title":"Фолаты при планировании беременности: зачем они нужны","image":null,"blocks":[{"type":"paragraph","text":"Фолиевую кислоту рекомендуют принимать ещё до положительного теста. Причина — в сроках развития малыша: некоторые важные структуры формируются раньше, чем женщина узнаёт о беременности."},{"type":"heading","text":"Что такое фолаты"},{"type":"paragraph","text":"Фолаты — общее название разных форм витамина B9. Организм использует их для образования новых клеток. Фолиевая кислота — одна из форм этого витамина, которую добавляют в препараты и обогащённые продукты."},{"type":"paragraph","text":"В начале беременности B9 особенно важен для развития нервной трубки — структуры, из которой формируются головной и спинной мозг. Приём фолиевой кислоты до зачатия и в ранние сроки снижает риск дефектов нервной трубки, включая расщепление позвоночника. Это подтверждено исследованиями; именно для фолиевой кислоты доказана такая профилактическая эффективность."},{"type":"heading","text":"Когда начинать и сколько принимать"},{"type":"paragraph","text":"Для большинства женщин без особых факторов риска практический ориентир — 400 мкг фолиевой кислоты ежедневно."},{"type":"paragraph","text":"Начать стоит минимум за месяц до предполагаемого зачатия. Если планируете заранее, можно начать за три месяца. Приём продолжают в течение первых 12 недель беременности. Дальнейшую схему витаминов обсуждают с врачом."},{"type":"paragraph","text":"Если две полоски уже появились, а вы ничего не принимали, начните сейчас. NHS рекомендует начинать приём сразу после обнаружения беременности, если он не был начат раньше. Само отсутствие предварительного приёма не позволяет сделать вывод о здоровье малыша."},{"type":"heading","text":"Можно ли получить всё из еды"},{"type":"paragraph","text":"Листовая зелень, фасоль, чечевица и другие бобовые содержат пищевые фолаты. Они полезны как часть разнообразного рациона, но обеспечить рекомендованную профилактику только едой сложно. Поэтому фолиевую кислоту принимают дополнительно."},{"type":"heading","text":"Когда дозу должен подобрать врач"},{"type":"paragraph","text":"Обсудите приём заранее, если у вас сахарный диабет, вы принимаете противоэпилептические препараты или в предыдущей беременности был дефект нервной трубки. Значение имеет и семейная история таких нарушений. В этих случаях могут понадобиться повышенные дозы; самостоятельно назначать их себе не следует."},{"type":"heading","text":"Что проверить сегодня"},{"type":"paragraph","text":"Посмотрите состав уже принимаемых витаминов. Если суточная порция содержит 400 мкг фолиевой кислоты, не добавляйте автоматически ещё одну таблетку. Обратите внимание на единицы: 400 мкг = 0,4 мг. Удобнее привязать ежедневный приём к привычному действию — например, к завтраку."}]},{"id":"pregnancy-003","number":3,"week":1,"title":"Как подготовить организм к беременности без десятков анализов и запретов","image":null,"blocks":[{"type":"paragraph","text":"Подготовку удобно начать с консультации и нескольких повседневных привычек. Объём обследований врач определяет с учётом вашего здоровья, прошлых беременностей, семейной истории и лекарств. Поэтому перед покупкой большого пакета анализов полезнее составить список вопросов и прийти с ним на приём."},{"type":"heading","text":"Сон: выделите ему постоянное время"},{"type":"paragraph","text":"Взрослым до 60 лет рекомендуется спать не менее семи часов в сутки. Попробуйте вставать примерно в одно время, убрать экран за полчаса до сна и перенести кофе на первую половину дня."},{"type":"paragraph","text":"Если регулярно трудно заснуть или усталость остаётся даже после достаточного сна, обсудите это с врачом. Эти рекомендации помогают поддерживать здоровье и самочувствие; они не гарантируют наступление беременности."},{"type":"heading","text":"Питание: соберите обычный разнообразный рацион"},{"type":"paragraph","text":"Ежедневно включайте овощи и фрукты, крупы или цельнозерновые продукты, источники белка — бобовые, яйца, рыбу или мясо, — а также молочные продукты либо подходящие обогащённые альтернативы."},{"type":"paragraph","text":"Например, гречка с индейкой и овощами — полноценный вариант обеда. Баланс оценивают за день или неделю: каждый приём пищи не обязан быть идеальным."},{"type":"paragraph","text":"Фолиевая кислота нужна дополнительно: большинству планирующих рекомендуют 400 мкг ежедневно, начиная до зачатия."},{"type":"heading","text":"Движение: начните с посильной нагрузки"},{"type":"paragraph","text":"Ориентир для взрослых — минимум 150 минут умеренной активности в неделю. Например, по 30 минут быстрой ходьбы пять дней в неделю. Если сейчас движения мало, начните с коротких прогулок и постепенно увеличивайте продолжительность. Даже небольшая активность полезнее её отсутствия."},{"type":"heading","text":"Привычки: откажитесь от алкоголя и курения"},{"type":"paragraph","text":"Когда начинаете попытки забеременеть, рекомендуется исключить алкоголь и прекратить курение. Если самостоятельно не получается, обратитесь за помощью: поддержку можно включить в план подготовки."},{"type":"heading","text":"Лекарства: проверьте всё, что принимаете"},{"type":"paragraph","text":"Составьте список препаратов с дозировками, включая безрецептурные средства, витамины, БАДы и травы. Покажите его врачу до зачатия: некоторые схемы лечения нужно изменить заранее."},{"type":"paragraph","text":"Не отменяйте назначенное лечение самостоятельно. Врач поможет подобрать наиболее безопасный вариант с учётом вашего заболевания."},{"type":"heading","text":"Что обсудить на приёме"},{"type":"paragraph","text":"Возьмите сведения о прививках и предыдущих обследованиях. Уточните, какие проверки нужны именно вам и какие профилактические обследования уже подошли по сроку. При хронических заболеваниях отдельно обсудите их контроль до беременности. Полезный вопрос о любом назначении: «Что покажет этот анализ и как результат изменит подготовку?»"}]},{"id":"pregnancy-004","number":4,"week":2,"title":"Овуляция простыми словами: что происходит в организме женщины","image":null,"blocks":[{"type":"paragraph","text":"Овуляция — это выход яйцеклетки из яичника. После этого она может встретиться со сперматозоидом и быть оплодотворена. Если вы планируете беременность, понимание этого процесса поможет выбирать подходящие дни для близости."},{"type":"heading","text":"Что происходит до овуляции"},{"type":"paragraph","text":"В первой части цикла в яичнике созревает яйцеклетка. Меняется уровень гормонов, а внутренний слой матки — эндометрий — постепенно утолщается, подготавливаясь к возможной беременности."},{"type":"paragraph","text":"Перед овуляцией резко повышается уровень лютеинизирующего гормона — ЛГ. Этот гормональный сигнал запускает выход яйцеклетки. Именно повышение ЛГ определяют домашние тесты на овуляцию."},{"type":"heading","text":"Что происходит после"},{"type":"paragraph","text":"Вышедшая яйцеклетка попадает в маточную трубу, где возможно оплодотворение. Она сохраняет способность к нему примерно 12–24 часа. Сперматозоиды могут оставаться жизнеспособными в половых путях женщины до пяти дней. Поэтому близость за несколько дней до овуляции тоже может привести к беременности."},{"type":"paragraph","text":"После овуляции гормон прогестерон помогает подготовить эндометрий к прикреплению эмбриона. Если беременность не наступает, уровни прогестерона и эстрогенов снижаются, эндометрий отторгается и начинается следующая менструация."},{"type":"heading","text":"Почему овуляция не всегда бывает на 14-й день"},{"type":"paragraph","text":"Четырнадцатый день — приблизительный ориентир для 28-дневного цикла. При другой продолжительности цикла овуляция может происходить раньше или позже. Даже у одной женщины её день способен меняться от месяца к месяцу."},{"type":"paragraph","text":"Поэтому отметка в приложении — прогноз. Она не подтверждает, что яйцеклетка уже вышла."},{"type":"heading","text":"Можно ли почувствовать овуляцию"},{"type":"paragraph","text":"Некоторые женщины замечают прозрачные тягучие выделения или небольшие тянущие ощущения с одной стороны внизу живота. Но выраженных ощущений может и не быть. По отсутствию таких признаков нельзя определить, произошла ли овуляция."},{"type":"paragraph","text":"Если менструации стали редкими, нерегулярными или исчезли, обсудите это с гинекологом. При необходимости врач проверит, происходит ли овуляция, и подберёт обследование. Самостоятельно принимать гормоны для её «улучшения» не нужно: стимуляцию назначают по показаниям."}]},{"id":"pregnancy-005","number":5,"week":2,"title":"Как определить свои фертильные дни","image":null,"blocks":[{"type":"paragraph","text":"Фертильные дни — период цикла, когда близость с наибольшей вероятностью может привести к беременности. Обычно выделяют пять дней перед овуляцией и сам день овуляции. Особенно благоприятны один-два дня до выхода яйцеклетки."},{"type":"paragraph","text":"Определить этот период помогают календарь, изменения выделений и тесты. Каждый способ даёт ориентир, но имеет ограничения."},{"type":"heading","text":"Календарь: начните с наблюдения за циклом"},{"type":"paragraph","text":"Отмечайте первый день каждой менструации. Продолжительность цикла — число дней от начала одной менструации до начала следующей."},{"type":"paragraph","text":"Для приблизительного расчёта из обычной продолжительности цикла вычитают 14. Например, при 30-дневном цикле предполагаемая овуляция приходится примерно на 16-й день, а фертильное окно — на 11–16-й дни."},{"type":"paragraph","text":"Этот пример не является точным расписанием. При нерегулярном цикле расчёт особенно ненадёжен; при регулярном тоже возможны сдвиги. Используйте календарь, чтобы видеть закономерности, а не ограничивать близость одной выбранной датой."},{"type":"heading","text":"Выделения: обратите внимание на изменения"},{"type":"paragraph","text":"Ближе к овуляции слизь шейки матки обычно становится более прозрачной, скользкой и тягучей — похожей на сырой яичный белок. Такие изменения помогают заметить приближение благоприятных дней."},{"type":"paragraph","text":"Если выраженных изменений нет, это не означает, что беременность невозможна. Наблюдение за выделениями не заменяет обследование при нарушениях цикла."},{"type":"heading","text":"Тесты: определяйте гормональный сигнал"},{"type":"paragraph","text":"Домашние тесты выявляют повышение ЛГ в моче. Положительный результат обычно означает, что овуляция приближается и может произойти в ближайшие один-два дня."},{"type":"paragraph","text":"Проводите тестирование по инструкции конкретного производителя: день начала, время и правила оценки результата могут различаться. Не переносите автоматически правила использования теста на беременность на тест для овуляции."},{"type":"paragraph","text":"При положительном результате подходящее время для близости — этот день и следующие один-два дня. При этом тест показывает повышение гормона, а не сам выход яйцеклетки: возможны ложноположительные результаты."},{"type":"heading","text":"Как использовать это без постоянных расчётов"},{"type":"paragraph","text":"Если отслеживаете фертильное окно, можно планировать близость каждые один-два дня в этот период. Если расчёты утомляют, простой вариант — близость каждые два-три дня на протяжении цикла."},{"type":"paragraph","text":"Если беременность не наступает в течение 12 месяцев регулярной половой жизни без контрацепции, обратитесь к врачу. С 35 лет обследование рекомендуют начинать уже через шесть месяцев. При редких или отсутствующих менструациях обращаться стоит раньше."}]},{"id":"pregnancy-006","number":6,"week":2,"title":"Спорт во время планирования: нужно ли снижать нагрузки","image":null,"blocks":[{"type":"paragraph","text":"Само по себе планирование беременности не требует прекращать тренировки. Если вы здоровы, хорошо переносите привычную активность и у вас нет индивидуальных ограничений, обычно можно продолжать заниматься. Значение имеют интенсивность нагрузки, питание и восстановление."},{"type":"heading","text":"Какая активность подходит"},{"type":"paragraph","text":"Ходьба, плавание, танцы и другие посильные занятия помогают поддерживать физическую форму. Общий ориентир для взрослых — не менее 150 минут умеренной активности в неделю. Например, по 30 минут быстрой ходьбы пять дней в неделю."},{"type":"paragraph","text":"Это ориентир для здоровья, а не обязательная норма для наступления беременности. Если сейчас вы мало двигаетесь, начните с коротких прогулок и увеличивайте нагрузку постепенно."},{"type":"paragraph","text":"При умеренной нагрузке дыхание учащается, но вы можете разговаривать. Если во время занятия трудно произнести фразу без остановки на вдох, интенсивность уже выше."},{"type":"heading","text":"Когда нагрузку действительно нужно пересмотреть"},{"type":"paragraph","text":"Проблемы могут возникнуть, когда организм регулярно тратит больше энергии, чем получает с питанием. Сочетание тяжёлых тренировок, ограничительного рациона и снижения веса способно нарушать гормональную регуляцию цикла и овуляцию."},{"type":"paragraph","text":"Обратите внимание, если после увеличения нагрузок менструации стали заметно реже, нерегулярными или исчезли. Такие изменения требуют обращения к врачу. Списывать их на «спортивную норму» не следует."},{"type":"paragraph","text":"При задержке и возможности беременности сначала сделайте тест. Если причина связана с энергетическим дефицитом, врач может рекомендовать увеличить питание, уменьшить нагрузки и восстановить массу тела. Но сначала нужно исключить другие причины нарушения цикла."},{"type":"heading","text":"Как организовать тренировки сейчас"},{"type":"paragraph","text":"Сохраняйте привычный комфортный режим. Увеличивайте объём постепенно, оставляйте время на восстановление и не сочетайте интенсивные занятия с жёстким ограничением еды."},{"type":"paragraph","text":"Если тренируетесь на уровне соревнований, готовитесь к марафону или уже замечаете нарушения цикла, обсудите план с врачом. Универсального безопасного числа километров или килограммов для всех женщин нет."},{"type":"heading","text":"Что делать после положительного теста"},{"type":"paragraph","text":"Прекращать всю физическую активность автоматически не требуется. При нормально протекающей беременности многие привычные занятия можно продолжать, адаптируя их к самочувствию. Сообщите врачу и тренеру о беременности: виды спорта с риском удара или падения требуют отдельного пересмотра."}]},{"id":"pregnancy-007","number":7,"week":3,"title":"Зачатие произошло: почему вы пока ничего не чувствуете","image":null,"blocks":[{"type":"paragraph","text":"Вы прислушиваетесь к себе, но всё как обычно: грудь не болит, запахи не раздражают, тошноты нет. На таком раннем сроке это вполне ожидаемо. Беременность может начаться без заметных ощущений."},{"type":"heading","text":"Почему организм пока «молчит»"},{"type":"paragraph","text":"Третья акушерская неделя — это не три недели после зачатия. При цикле около 28 дней оплодотворение обычно происходит примерно в этот период. Поэтому с момента встречи яйцеклетки и сперматозоида могли пройти всего несколько дней."},{"type":"paragraph","text":"Оплодотворённая яйцеклетка начинает делиться и перемещается по маточной трубе к матке. Затем происходит имплантация — прикрепление к её внутренней оболочке. Эти изменения микроскопические: почувствовать само деление клеток или их перемещение невозможно."},{"type":"heading","text":"Когда появляются первые признаки"},{"type":"paragraph","text":"После начала имплантации вырабатывается ХГЧ — гормон, на который реагируют тесты. Его количество увеличивается постепенно. Поэтому сразу после зачатия тест ещё не способен подтвердить беременность."},{"type":"paragraph","text":"Позже могут появиться чувствительность груди, усталость, изменение аппетита или тошнота. Но обязательного набора признаков нет. Даже на четвёртой неделе некоторые женщины не замечают никаких изменений. Отсутствие тошноты или боли в груди само по себе не означает, что что-то идёт неправильно."},{"type":"heading","text":"Можно ли отличить беременность от приближающихся месячных"},{"type":"paragraph","text":"По одним ощущениям — ненадёжно. Нагрубание груди, вздутие и изменения самочувствия могут встречаться в обоих случаях. Прогестерон вырабатывается после овуляции и в цикле, в котором беременность не наступила. Поэтому отдельный симптом не подтверждает зачатие."},{"type":"heading","text":"Что делать сейчас"},{"type":"paragraph","text":"Выберите дату тестирования: для большинства домашних тестов подходящий ориентир — первый день задержки. Если цикл нерегулярный и дата месячных неизвестна, проведите тест не раньше чем через 21 день после последнего незащищённого полового контакта."},{"type":"paragraph","text":"До этого момента не нужно искать у себя признаки из чужих историй. Хорошее самочувствие не требует дополнительного подтверждения симптомами."}]},{"id":"pregnancy-008","number":8,"week":3,"title":"Первые дни после зачатия: нужно ли уже менять привычный образ жизни","image":null,"blocks":[{"type":"paragraph","text":"Если беременность возможна, некоторые привычки стоит пересмотреть уже сейчас. При этом обычная повседневная активность чаще всего может сохраняться."},{"type":"heading","text":"Продолжайте двигаться"},{"type":"paragraph","text":"При хорошем самочувствии и отсутствии медицинских ограничений можно продолжать прогулки и привычную умеренную физическую активность. Постоянно отдыхать лёжа только из-за возможной беременности не требуется."},{"type":"paragraph","text":"Для нагрузки есть понятный ориентир: во время движения вы должны сохранять возможность разговаривать без выраженной одышки. Если раньше почти не занимались, начните с коротких прогулок, а не с интенсивной программы."},{"type":"paragraph","text":"Избегайте тренировок до изнеможения, занятий в сильную жару, контактных видов спорта и нагрузок с высоким риском падения. Пейте воду и делайте перерывы."},{"type":"heading","text":"Начните принимать фолиевую кислоту"},{"type":"paragraph","text":"Если вы ещё не принимаете её, не нужно ждать положительного теста. Для большинства женщин стандартная профилактическая доза — 400 мкг в сутки до конца первых 12 недель беременности."},{"type":"paragraph","text":"Фолиевая кислота снижает риск нарушений формирования нервной трубки — структуры, из которой развиваются головной и спинной мозг. Получить необходимое профилактическое количество только из продуктов трудно."},{"type":"paragraph","text":"Если она уже входит в ваш витаминный комплекс, проверьте дозировку перед добавлением отдельного препарата. Повышенные дозы назначает врач по конкретным показаниям."},{"type":"heading","text":"Исключите алкоголь и курение"},{"type":"paragraph","text":"Отказаться от них рекомендуют уже при планировании беременности. Не нужно дожидаться задержки или первых симптомов. Если самостоятельно отказаться трудно, обратитесь за помощью к врачу."},{"type":"heading","text":"Проверьте лекарства"},{"type":"paragraph","text":"Составьте список всего, что принимаете: постоянные препараты, обезболивающие, БАДы и растительные средства. Обсудите их с врачом, сообщив, что беременность возможна."},{"type":"paragraph","text":"Самостоятельно отменять назначенное лечение нельзя: резкая отмена некоторых лекарств может навредить. Новые препараты тоже стоит проверять на совместимость с беременностью. Пометка «натуральный» не гарантирует безопасность."},{"type":"paragraph","text":"Практичный первый шаг: поставить напоминание о фолиевой кислоте и подготовить список лекарств. Эти действия полезнее, чем пытаться за один день полностью перестроить свою жизнь."}]},{"id":"pregnancy-009","number":9,"week":3,"title":"Кофе, питание и привычные продукты: что можно оставить в рационе","image":null,"blocks":[{"type":"paragraph","text":"Беременность не требует отдельного «идеального» меню. Большинство привычных продуктов можно оставить: важны разнообразие, количество и безопасное приготовление."},{"type":"heading","text":"Можно ли продолжать пить кофе"},{"type":"paragraph","text":"Можно, если общее поступление кофеина — не больше 200 мг в день. Учитывайте кофе, чёрный и зелёный чай, колу, шоколад и другие продукты с кофеином."},{"type":"paragraph","text":"По ориентировочным данным NHS, чашка растворимого кофе содержит около 100 мг кофеина, чашка чая — около 75 мг. Вместе это уже примерно 175 мг. Но содержание зависит от объёма, крепости и способа приготовления: большой кофе из кофейни может содержать значительно больше."},{"type":"paragraph","text":"Поэтому правило «одна-две чашки разрешены» слишком неточное. Узнавайте содержание кофеина в порции или выбирайте кофе без кофеина."},{"type":"heading","text":"Что оставить в ежедневном меню"},{"type":"list-item","text":"Крупы, хлеб, картофель и макароны: источники энергии; чаще выбирайте цельнозерновые варианты."},{"type":"list-item","text":"Овощи и фрукты: подходят свежие и замороженные. Свежие тщательно мойте."},{"type":"list-item","text":"Мясо, птицу, яйца, бобовые: чередуйте источники белка."},{"type":"list-item","text":"Молочные продукты: выбирайте пастеризованные."},{"type":"list-item","text":"Рыбу: ориентир — две порции в неделю, например запечённые лосось и треска."},{"type":"paragraph","text":"Если вы используете растительные напитки вместо молока, выбирайте варианты без добавленного сахара, обогащённые кальцием. В начале беременности увеличивать порции «за двоих» не требуется."},{"type":"heading","text":"Где важен способ приготовления"},{"type":"paragraph","text":"Сырые мясо и рыбу замените полностью приготовленными. Яйца готовьте до плотного белка и желтка. Роллы можно выбрать с приготовленной рыбой или овощами."},{"type":"paragraph","text":"Мягкие сыры с плесенью, например бри и камамбер, употребляйте только после тщательного прогревания. Слабосолёная и холодного копчения рыба также требует термической обработки. Печень и блюда из неё исключите из-за высокого содержания витамина А."},{"type":"heading","text":"Как это выглядит на практике"},{"type":"paragraph","text":"Овсянка, йогурт и фрукт на завтрак; гречка с индейкой и овощами на обед; запечённая рыба с картофелем на ужин — пример обычного разнообразного рациона. Специальные «продукты для беременных» для такого питания не нужны."}]},{"id":"pregnancy-010","number":10,"week":4,"title":"Когда тест на беременность становится информативным","image":null,"blocks":[{"type":"paragraph","text":"Тест определяет в моче ХГЧ — гормон, количество которого увеличивается после прикрепления эмбриона к оболочке матки. Между зачатием и моментом, когда тест сможет показать беременность, должно пройти время."},{"type":"heading","text":"Когда лучше проверять"},{"type":"paragraph","text":"Для большинства домашних тестов ориентир — первый день задержки менструации. Некоторые высокочувствительные тесты можно использовать раньше, но отрицательный результат до задержки ещё не исключает беременность."},{"type":"paragraph","text":"Если вы не знаете, когда ждать месячные, например из-за нерегулярного цикла, проведите тест не раньше чем через 21 день после последнего незащищённого полового контакта."},{"type":"heading","text":"Почему даже в день задержки бывает одна полоска"},{"type":"paragraph","text":"Овуляция могла произойти позже, чем вы предполагали. Тогда фактический срок после зачатия меньше, а концентрация ХГЧ ещё недостаточна для теста."},{"type":"paragraph","text":"По данным FDA, в первый день задержки 10–20 из 100 беременных женщин могут ещё не получить положительный результат. На это влияют различия в цикле и неточность расчёта ожидаемой менструации. Поэтому раннюю одну полоску лучше воспринимать как предварительный результат."},{"type":"heading","text":"Как провести тест правильно"},{"type":"paragraph","text":"1. Прочитайте инструкцию именно к вашему тесту: способы использования различаются."},{"type":"paragraph","text":"2. Соблюдайте указанное время контакта с мочой."},{"type":"paragraph","text":"3. Засеките время и оцените результат в предусмотренный инструкцией интервал."},{"type":"paragraph","text":"4. При очень раннем тестировании предпочтительна первая утренняя моча: она обычно содержит более высокую концентрацию ХГЧ."},{"type":"paragraph","text":"После задержки многие тесты можно использовать в любое время суток — ориентируйтесь на инструкцию производителя."},{"type":"heading","text":"Что делать с результатом"},{"type":"paragraph","text":"Положительный: при правильном использовании он почти всегда верен. Можно записываться к акушеру-гинекологу."},{"type":"paragraph","text":"Отрицательный, но месячные не начались: повторите тест через несколько дней. Если повторный результат отрицательный, а задержка сохраняется, обратитесь к врачу."},{"type":"paragraph","text":"Домашний тест отвечает на вопрос о наличии ХГЧ. Он не предназначен для оценки того, насколько хорошо развивается беременность: яркость полоски не заменяет медицинское наблюдение."}]},{"id":"pregnancy-011","number":11,"week":4,"title":"Две полоски: что делать дальше — простой план без паники","image":null,"blocks":[{"type":"paragraph","text":"После положительного теста вопросов может стать больше, чем ответов. Для начала достаточно организовать наблюдение и проверить несколько вещей, которые важны уже сейчас."},{"type":"heading","text":"1. Запишитесь к акушеру-гинекологу"},{"type":"paragraph","text":"Свяжитесь с женской консультацией или выбранной клиникой и сообщите о положительном тесте. При записи назовите первый день последней менструации, расскажите о жалобах, хронических заболеваниях и постоянных лекарствах — это поможет определить срок первого визита."},{"type":"paragraph","text":"Не откладывайте обращение до появления живота или тошноты: наблюдение начинают на раннем сроке."},{"type":"heading","text":"2. Подготовьте информацию для приёма"},{"type":"paragraph","text":"Сохраните в заметках:"},{"type":"list-item","text":"первый день последней менструации;"},{"type":"list-item","text":"обычную продолжительность и регулярность цикла;"},{"type":"list-item","text":"дату положительного теста;"},{"type":"list-item","text":"сведения о предыдущих беременностях и заболеваниях;"},{"type":"list-item","text":"названия и дозировки всех лекарств и добавок."},{"type":"paragraph","text":"Добавьте свои вопросы. Например: когда проходить обследования, какие нагрузки можно сохранить и как связаться с врачом между приёмами. Эти сведения помогают составить индивидуальный план наблюдения."},{"type":"heading","text":"3. Проверьте фолиевую кислоту"},{"type":"paragraph","text":"Если ещё не принимаете, стандартная профилактическая доза для большинства женщин — 400 мкг ежедневно до конца первых 12 недель. Если она уже есть в вашем комплексе, проверьте суммарное количество. Повышенную дозу назначают по показаниям."},{"type":"heading","text":"4. Обсудите постоянное лечение"},{"type":"paragraph","text":"При хронических заболеваниях сообщите о беременности лечащему врачу как можно скорее. Не отменяйте препараты самостоятельно и не заменяйте их БАДами. Подготовленный список поможет быстро проверить, требуется ли коррекция лечения."},{"type":"heading","text":"5. Согласуйте обследования"},{"type":"paragraph","text":"На первом контакте уточните, что нужно сделать до приёма и когда проводить УЗИ. Плановые анализы и исследования назначают с учётом срока и вашей истории здоровья. Сохраните назначения и даты в одном месте, чтобы не пропускать обследования и не дублировать их."},{"type":"heading","text":"Когда не нужно ждать планового визита"},{"type":"paragraph","text":"При сильной или нарастающей боли в животе, особенно вместе с кровянистыми выделениями, нужна срочная медицинская оценка. При сильной боли или обильном кровотечении вызывайте скорую помощь."}]},{"id":"pregnancy-012","number":12,"week":4,"title":"Как рассчитать предполагаемую дату родов самостоятельно","image":null,"blocks":[{"type":"paragraph","text":"Предполагаемая дата родов, или ПДР, — это ориентир, который помогает планировать беременность и обследования. Рассчитать её дома можно, если вы знаете дату начала последней менструации."},{"type":"heading","text":"От какой даты считать"},{"type":"paragraph","text":"Используйте первый день последней менструации, а не день её окончания, положительного теста или полового контакта."},{"type":"paragraph","text":"Так рассчитывают акушерский срок. Он обычно примерно на две недели больше времени, прошедшего после зачатия. Именно поэтому на момент задержки срок часто составляет около четырёх недель, хотя оплодотворение произошло примерно две недели назад."},{"type":"heading","text":"Основная формула"},{"type":"paragraph","text":"Для регулярного 28-дневного цикла:"},{"type":"paragraph","text":"ПДР = первый день последней менструации + 280 дней."},{"type":"paragraph","text":"Это 40 акушерских недель. Удобнее прибавить дни в календаре или калькуляторе: так не придётся учитывать разную длину месяцев вручную."},{"type":"heading","text":"А если цикл длиннее или короче"},{"type":"paragraph","text":"Для предварительного расчёта учитывают разницу с 28 днями:"},{"type":"list-item","text":"при регулярном цикле 30 дней к полученной дате прибавляют ещё 2 дня;"},{"type":"list-item","text":"при цикле 26 дней — вычитают 2 дня."},{"type":"paragraph","text":"Такую поправку учитывает и калькулятор NHS. Но это приближение: продолжительность цикла не позволяет определить день овуляции с абсолютной точностью."},{"type":"heading","text":"Когда календарь менее точен"},{"type":"paragraph","text":"Если месячные нерегулярные, дата их начала неизвестна или последнее кровотечение было необычным, расчёт по менструации может оказаться неточным. Не нужно выбирать случайную дату, чтобы заполнить поле приложения: сохраните пометку, что срок требует уточнения."},{"type":"paragraph","text":"На УЗИ первого триместра врач сможет точнее оценить срок по размерам эмбриона или плода. Поэтому первоначальная ПДР иногда меняется."},{"type":"heading","text":"Нужно ли ждать рождения именно в этот день"},{"type":"paragraph","text":"Нет. Слово «предполагаемая» означает, что дата расчётная. Роды могут начаться раньше или позже неё. ПДР помогает врачу оценивать срок и планировать наблюдение, но не предсказывает точный день встречи с малышом."}]},{"id":"pregnancy-013","number":13,"week":5,"title":"Когда лучше впервые записаться к акушеру-гинекологу","image":null,"blocks":[{"type":"paragraph","text":"Записываться можно сразу после положительного теста. На пятой неделе уже стоит связаться с женской консультацией или выбранной клиникой. Ждать тошноты, заметного живота или какого-то особенного самочувствия не нужно."},{"type":"heading","text":"Зачем обращаться так рано"},{"type":"paragraph","text":"Первый приём нужен не только для подтверждения беременности. Врач уточняет срок, оценивает ваше здоровье и составляет план наблюдения."},{"type":"paragraph","text":"Некоторые вопросы важно решить уже в первые недели: проверить постоянные лекарства, подобрать профилактические добавки, учесть хронические заболевания. Поэтому откладывать знакомство с врачом до первого скрининга не стоит."},{"type":"paragraph","text":"Если жалоб нет, визит обычно проходит планово. Конкретную дату согласуйте при записи: единственной «правильной недели» для всех женщин нет."},{"type":"heading","text":"Что сообщить при записи"},{"type":"paragraph","text":"Назовите первый день последней менструации и дату положительного теста. Сразу расскажите, если:"},{"type":"list-item","text":"принимаете постоянные лекарства;"},{"type":"list-item","text":"есть заболевания щитовидной железы, диабет, эпилепсия или другие хронические состояния;"},{"type":"list-item","text":"беременность наступила после лечения бесплодия;"},{"type":"list-item","text":"появились боль, кровянистые выделения или рвота, мешающая пить и есть."},{"type":"paragraph","text":"Эта информация помогает определить, насколько быстро нужен приём и требуется ли дополнительная консультация."},{"type":"heading","text":"Что будет на первом визите"},{"type":"paragraph","text":"Врач спросит о цикле, предыдущих беременностях, заболеваниях, операциях и лекарствах. Оценит давление, вес и другие показатели, назначит необходимые анализы и определит сроки УЗИ."},{"type":"paragraph","text":"Вы тоже можете задавать вопросы. Например: можно ли продолжать тренировки, как скорректировать работу, какие обследования предстоят и куда обращаться между приёмами."},{"type":"heading","text":"Как подготовиться"},{"type":"paragraph","text":"Возьмите имеющиеся медицинские выписки и результаты недавних обследований. Сфотографируйте упаковки лекарств и добавок — так проще проверить названия и дозировки."},{"type":"paragraph","text":"Не нужно заранее покупать большой пакет анализов: часть исследований может оказаться лишней или потребоваться в другой срок. При записи уточните, нужна ли специальная подготовка. Голодать перед обычной консультацией без отдельного указания не требуется."},{"type":"paragraph","text":"Если появилась сильная боль или обильное кровотечение, не ждите записи — обращайтесь за неотложной помощью."}]},{"id":"pregnancy-014","number":14,"week":5,"title":"Когда делать первое УЗИ и почему не нужно торопиться","image":null,"blocks":[{"type":"paragraph","text":"После двух полосок хочется скорее увидеть малыша. Но на очень раннем сроке УЗИ может дать меньше информации, чем вы ожидаете. Срок исследования лучше выбирать вместе с врачом — исходя из того, на какой вопрос нужно ответить."},{"type":"heading","text":"Что можно увидеть в первые недели"},{"type":"paragraph","text":"На раннем УЗИ врач прежде всего оценивает расположение беременности. По мере увеличения срока становятся видны плодное яйцо, желточный мешок, затем эмбрион и его сердечная деятельность."},{"type":"paragraph","text":"Если цель — увидеть эмбрион и оценить сердечную деятельность, исследование примерно в 6–7 акушерских недель обычно информативнее, чем сразу после задержки. Однако это ориентир, а не гарантия одинаковой картины у всех."},{"type":"paragraph","text":"При поздней овуляции фактический срок может быть меньше календарного. Имеют значение также способ исследования и качество изображения."},{"type":"heading","text":"Почему слишком раннее УЗИ иногда добавляет тревоги"},{"type":"paragraph","text":"Представьте: по месячным вы насчитали пять недель, но овуляция произошла позже обычного. На УЗИ врач видит меньше, чем вы ожидали, и рекомендует повторное исследование."},{"type":"paragraph","text":"Это не повод самостоятельно делать выводы по фразе «пока не видно». Врач сопоставляет размеры структур, предполагаемый срок, симптомы и при необходимости результаты анализов. Иногда ответ можно получить только при наблюдении в динамике."},{"type":"paragraph","text":"Если повторное УЗИ назначено через определённый интервал, исследование уже на следующий день обычно не решает вопрос."},{"type":"heading","text":"Почему могут предложить вагинальный датчик"},{"type":"paragraph","text":"На раннем сроке он позволяет рассмотреть структуры лучше, чем датчик через живот. Его вводят во влагалище, в полость матки он не проникает. Такой способ исследования применяется при беременности по медицинским показаниям."},{"type":"paragraph","text":"УЗИ использует звуковые волны, а не рентгеновское излучение. Причина выбирать подходящий срок — прежде всего информативность обследования."},{"type":"heading","text":"Раннее УЗИ и первый скрининг — разные исследования"},{"type":"paragraph","text":"Раннее УЗИ не заменяет скрининг первого триместра. В российской практике его проводят в 11 недель — 13 недель 6 дней: в этот период можно оценить показатели, которые ещё недоступны на пятой или шестой неделе."},{"type":"paragraph","text":"При боли, кровянистых выделениях или других показаниях врач может назначить УЗИ раньше. В такой ситуации ждать «более информативного срока» самостоятельно не нужно."}]},{"id":"pregnancy-015","number":15,"week":5,"title":"Какие витамины действительно нужны беременной, а какие не стоит назначать себе самостоятельно","image":null,"blocks":[{"type":"paragraph","text":"На упаковке может быть написано «для будущих мам», но это ещё не означает, что вам нужны все компоненты комплекса. Добавки подбирают с учётом срока, питания, заболеваний и уже принимаемых препаратов."},{"type":"heading","text":"Фолиевая кислота: важна уже сейчас"},{"type":"paragraph","text":"Для большинства женщин стандартная профилактическая доза — 400 мкг в сутки в первые 12 недель беременности. Если вы не начали приём заранее, начните сейчас."},{"type":"paragraph","text":"Фолиевая кислота снижает риск нарушений формирования нервной трубки, из которой развиваются головной и спинной мозг. Получить необходимое профилактическое количество только из пищи трудно."},{"type":"paragraph","text":"Повышенные дозы назначают по отдельным показаниям. Самостоятельно увеличивать дозировку «для надёжности» не нужно."},{"type":"heading","text":"Йод: обсудите на первом приёме"},{"type":"paragraph","text":"Он необходим для образования гормонов щитовидной железы, участвующих в развитии нервной системы ребёнка. В российской практике профилактика йодного дефицита входит в ведение беременности."},{"type":"paragraph","text":"Если у вас есть заболевание щитовидной железы, схему обязательно согласуйте с врачом. Добавки из водорослей не подходят для точного дозирования: содержание йода в них может сильно различаться."},{"type":"heading","text":"Витамин D: профилактика и лечение — разные задачи"},{"type":"paragraph","text":"Он участвует в обмене кальция и поддержании здоровья костей. Профилактические рекомендации зависят от страны, питания и факторов риска дефицита."},{"type":"paragraph","text":"Большие лечебные дозы нельзя переносить из чужих назначений в свою схему. Если витамин D уже есть в комплексе, учитывайте его при добавлении отдельного препарата."},{"type":"heading","text":"Железо: не назначайте по одной усталости"},{"type":"paragraph","text":"Сонливость на раннем сроке сама по себе не доказывает дефицит железа. Врач оценивает общий анализ крови, а при необходимости — ферритин и другие показатели."},{"type":"paragraph","text":"Профилактическая и лечебная дозировки различаются. Избыточный приём может вызывать тошноту, запор и боль в животе."},{"type":"heading","text":"Что ещё может понадобиться"},{"type":"paragraph","text":"При веганском питании особенно важно обеспечить витамин B12. Если в рационе мало источников кальция, врач поможет оценить его поступление и необходимость добавки. Магний и высокие дозы витаминов C или E не являются обязательным набором для каждой беременной."},{"type":"heading","text":"Проверьте домашние упаковки"},{"type":"paragraph","text":"Не сочетайте несколько комплексов без проверки состава. Не добавляйте самостоятельно витамин А в форме ретинола и масло печени трески: избыток ретинола опасен при беременности."},{"type":"paragraph","text":"Сфотографируйте всё, что принимаете, и покажите врачу. Это поможет составить понятную схему без дублирования."}]},{"id":"pregnancy-016","number":16,"week":6,"title":"Тошнота по утрам: как сделать первые недели комфортнее","image":null,"blocks":[{"type":"paragraph","text":"Тошнота часто появляется примерно на 4–7-й неделе. Несмотря на название «утренняя», она может беспокоить днём, вечером или в течение всего дня. У большинства женщин состояние постепенно улучшается к 16–20 неделям."},{"type":"heading","text":"Не начинайте утро с большого завтрака"},{"type":"paragraph","text":"Попробуйте небольшой кусочек сухого тоста или простой крекер до того, как встанете с постели. Затем поднимайтесь спокойно и завтракайте той порцией, которую можете съесть без усиления тошноты."},{"type":"paragraph","text":"Это не обязательный ритуал: если сухая еда вам неприятна, подберите другой переносимый вариант."},{"type":"heading","text":"Ешьте понемногу и чаще"},{"type":"paragraph","text":"Большая порция может усиливать дискомфорт. Попробуйте разделить привычный объём еды на несколько небольших приёмов. Если замечаете, что на пустой желудок становится хуже, держите под рукой подходящий перекус."},{"type":"paragraph","text":"Нередко легче переносятся рис, картофель, макароны, хлеб и простые крекеры. Жирную пищу стоит ограничить, если именно после неё тошнит сильнее."},{"type":"heading","text":"Уменьшите воздействие запахов"},{"type":"paragraph","text":"Горячая еда пахнет интенсивнее. Попробуйте прохладные блюда, приготовленные и хранившиеся безопасно. Проветривайте кухню, пользуйтесь вытяжкой, по возможности попросите близких временно взять готовку на себя."},{"type":"paragraph","text":"Не заставляйте себя есть продукт, от одного запаха которого становится плохо."},{"type":"heading","text":"Пейте маленькими глотками"},{"type":"paragraph","text":"Большой стакан за один раз иногда провоцирует рвоту. Попробуйте пить понемногу в течение дня и подберите комфортную температуру воды."},{"type":"paragraph","text":"Если жидкость не удерживается, не пытайтесь решить проблему только сменой напитка — нужна медицинская помощь."},{"type":"heading","text":"Что ещё можно попробовать"},{"type":"paragraph","text":"Отдыхайте: усталость способна усиливать тошноту. Некоторым помогают продукты или напитки с небольшим количеством имбиря. Концентрированные добавки с имбирём самостоятельно принимать не стоит."},{"type":"heading","text":"Когда домашних мер недостаточно"},{"type":"paragraph","text":"Если тошнота мешает работать, спать, нормально есть или пить, обсудите лечение с врачом. Существуют противорвотные препараты, применяемые при беременности. Терпеть до полного истощения не нужно."},{"type":"paragraph","text":"Обратитесь за помощью в тот же день, если мочи стало заметно меньше, она очень тёмная, появилась выраженная слабость, головокружение или снижается вес. Если не получается удерживать даже небольшие глотки жидкости, обращайтесь раньше, не ожидая ухудшения."}]},{"id":"pregnancy-017","number":17,"week":6,"title":"Изменился аппетит: что есть, если привычная еда вдруг перестала нравиться","image":null,"blocks":[{"type":"paragraph","text":"Вчера вы спокойно ели курицу и творог, а сегодня не можете даже смотреть на них. На раннем сроке пищевые предпочтения действительно могут меняться. Особенно трудно выбирать еду, когда одновременно усиливается чувствительность к запахам и появляется тошнота."},{"type":"heading","text":"Не заставляйте себя есть конкретный продукт"},{"type":"paragraph","text":"Полезные вещества можно получать из разных источников. Если один продукт вызывает отвращение, попробуйте замену из той же пищевой группы."},{"type":"paragraph","text":"Варианты замены продуктов:"},{"type":"list-item","text":"Мясо или курицу — хорошо приготовленные яйца, рыбу, чечевицу, фасоль, тофу."},{"type":"list-item","text":"Творог — пастеризованный йогурт, кефир, сыр."},{"type":"list-item","text":"Молоко — несладкий растительный напиток, обогащённый кальцием; содержание белка проверяйте на упаковке."},{"type":"list-item","text":"Рыбу — временно другие источники белка; если отказ затягивается — обсудить поступление омега-3 с врачом."},{"type":"list-item","text":"Сырые овощи — запечённые, тушёные овощи или овощной суп."},{"type":"list-item","text":"Горячий завтрак — прохладный йогурт, тост, фрукт — по переносимости."},{"type":"paragraph","text":"Замены не всегда полностью равноценны. Например, орехи не заменяют мясо по содержанию доступного железа, а многие растительные напитки содержат мало белка."},{"type":"heading","text":"Собирайте небольшую порцию из двух компонентов"},{"type":"paragraph","text":"Когда полноценный обед кажется невозможным, начните с простого сочетания:"},{"type":"list-item","text":"тост и сыр;"},{"type":"list-item","text":"картофель и яйцо;"},{"type":"list-item","text":"рис и несколько кусочков индейки;"},{"type":"list-item","text":"йогурт и банан."},{"type":"paragraph","text":"Сначала выберите то, что переносится, затем постепенно добавляйте разнообразие. Необязательно съедать большую тарелку за один раз."},{"type":"heading","text":"Если хочется только хлеба и макарон"},{"type":"paragraph","text":"На короткое время простая углеводная пища может стать основой рациона при тошноте. Не нужно ругать себя за это. По возможности добавляйте небольшие порции белковых продуктов, овощей или фруктов."},{"type":"paragraph","text":"Но если питание остаётся очень ограниченным, уменьшается вес или почти не удаётся есть, сообщите врачу. Здесь важно помочь справиться с симптомами, а не просто составить «более правильное меню»."},{"type":"heading","text":"Нужно ли доверять любой тяге к еде"},{"type":"paragraph","text":"Желание солёного или сладкого не позволяет определить дефицит витаминов. Назначать себе добавки по пищевым желаниям нельзя."},{"type":"paragraph","text":"Если тянет есть мел, землю или другие несъедобные вещества, расскажите врачу: такое желание требует отдельной оценки, в том числе возможного дефицита железа."}]},{"id":"pregnancy-018","number":18,"week":6,"title":"Что действительно нельзя есть беременным, а что запрещают зря","image":null,"blocks":[{"type":"paragraph","text":"Советы «уберите всё красное», «никаких специй» и «забудьте о рыбе» могут сделать питание неоправданно однообразным. Реальные ограничения связаны прежде всего с пищевыми инфекциями, загрязняющими веществами и избытком отдельных компонентов."},{"type":"heading","text":"Что действительно стоит исключить или заменить"},{"type":"paragraph","text":"Сырые и недостаточно приготовленные мясо, рыбу и морепродукты. Тартар, суши с сырой рыбой и сырые устрицы замените полностью приготовленными блюдами. Замораживание не устраняет все микробиологические риски."},{"type":"paragraph","text":"Сырые яйца и блюда с ними. Для обычных яиц выбирайте приготовление до плотного белка и желтка. Для соусов и десертов без нагревания подходят пастеризованные яичные продукты."},{"type":"paragraph","text":"Непастеризованное молоко и продукты из него, которые не проходят достаточную обработку. Проверяйте упаковку. Мягкие сыры с плесенью, например бри и камамбер, употребляйте только после тщательного прогревания."},{"type":"paragraph","text":"Слабосолёную и холодного копчения рыбу без последующего нагревания. Безопаснее использовать её в блюде, которое полностью прогревается."},{"type":"paragraph","text":"Печень и блюда из неё. В них много готового витамина А — ретинола, избытка которого при беременности следует избегать."},{"type":"paragraph","text":"Рыбу с высоким содержанием ртути, например акулу и рыбу-меч. Сырые проростки также лучше исключить или тщательно приготовить."},{"type":"heading","text":"Что часто запрещают без оснований"},{"type":"list-item","text":"Красные ягоды, помидоры и цитрусовые. Цвет продукта не делает его опасным. Ограничения нужны при вашей аллергии или индивидуальной непереносимости."},{"type":"list-item","text":"Орехи. Если у вас нет аллергии, беременность сама по себе не повод их исключать."},{"type":"list-item","text":"Острую пищу. Она может усиливать изжогу или тошноту, но общего запрета нет."},{"type":"list-item","text":"Рыбу и морепродукты целиком. Подходящие виды после полного приготовления могут оставаться в рационе."},{"type":"list-item","text":"Все сыры. Пастеризованные творог, моцарелла и многие другие варианты допустимы при соблюдении условий хранения."},{"type":"heading","text":"Что ограничивают по количеству"},{"type":"paragraph","text":"Кофеин — не более 200 мг в сутки из всех источников. Сладости можно оставлять небольшими порциями, если нет индивидуальных ограничений. Алкоголь исключают."},{"type":"heading","text":"Безопасность зависит и от хранения"},{"type":"paragraph","text":"Мойте овощи и фрукты, отделяйте сырые продукты от готовых, своевременно убирайте еду в холодильник. Даже разрешённое блюдо может стать небезопасным, если долго стоит в тепле."}]},{"id":"pregnancy-019","number":19,"week":7,"title":"Постоянно хочется спать: как пережить период сильной усталости","image":null,"blocks":[{"type":"paragraph","text":"Вы проспали всю ночь, но уже после завтрака хочется снова лечь. Обычная прогулка утомляет, а вечером не остаётся сил даже на привычные дела. В первом триместре такое состояние встречается часто. Усталость может быть выраженной ещё до появления заметного живота."},{"type":"paragraph","text":"Это не означает, что вы стали менее организованной или недостаточно стараетесь. Организм уже адаптируется к беременности, хотя внешне изменения пока почти незаметны."},{"type":"heading","text":"Почему энергии стало меньше"},{"type":"paragraph","text":"В первые недели меняется гормональный фон, в том числе повышается уровень прогестерона. Он может усиливать сонливость. Одновременно перестраивается кровообращение, увеличивается объём крови, развивается плацента."},{"type":"paragraph","text":"Дополнительные силы забирают тошнота, рвота, недостаточное питание и ночные пробуждения. Если из-за запахов вы едите меньше обычного, а вечером долго не можете уснуть, усталость становится ещё заметнее."},{"type":"paragraph","text":"У многих женщин во втором триместре энергии прибавляется. Но точной недели, когда сонливость обязательно должна исчезнуть, нет."},{"type":"heading","text":"Дайте сну больше места в расписании"},{"type":"paragraph","text":"Попробуйте несколько дней ложиться раньше и оценить, меняется ли самочувствие. Сохраните примерно одинаковое время подъёма, проветривайте спальню и уменьшайте вечернюю нагрузку."},{"type":"paragraph","text":"Если есть возможность, попробуйте короткий дневной отдых. Например, выделите 20–30 минут после обеда. Это практический вариант, а не обязательная норма: кому-то помогает сон, кому-то — просто полежать в тишине."},{"type":"paragraph","text":"Если после дневного сна трудно заснуть вечером, перенесите отдых на более раннее время или сократите его."},{"type":"heading","text":"Ешьте регулярно, даже если порции небольшие"},{"type":"paragraph","text":"Необязательно готовить сложные блюда. Подойдут простые сочетания: каша и йогурт, тост с яйцом, гречка с индейкой, фрукт и немного орехов."},{"type":"paragraph","text":"Держите воду рядом и пейте в течение дня. При тошноте часто легче переносить небольшие порции еды и жидкости. Если не получается нормально есть или пить, стоит обсудить именно эту проблему с врачом — одним дополнительным сном её не решить."},{"type":"heading","text":"Сохраняйте посильное движение"},{"type":"paragraph","text":"При хорошем самочувствии короткая прогулка может помочь почувствовать себя бодрее. Начните с комфортного маршрута без цели пройти определённое количество шагов."},{"type":"paragraph","text":"Движение не должно превращаться в проверку выносливости. Если после нагрузки приходится долго восстанавливаться, уменьшите её продолжительность или интенсивность."},{"type":"heading","text":"Что не стоит делать"},{"type":"paragraph","text":"Не пытайтесь постоянно перекрывать сонливость кофе и энергетиками. Не назначайте себе железо, витамин B12 или другие добавки только потому, что устали: по одному симптому дефицит не определить."},{"type":"paragraph","text":"Также не нужно сохранять весь прежний объём домашних дел. Выберите, что действительно необходимо сегодня, а что можно перенести или поручить близким."},{"type":"heading","text":"Когда рассказать врачу"},{"type":"paragraph","text":"Обсудите усталость, если она мешает повседневной жизни, заметно усиливается или почти не уменьшается после отдыха. Особенно если появились сердцебиение, выраженное головокружение, одышка при небольшой нагрузке, снижение веса или длительное подавленное настроение."},{"type":"paragraph","text":"Врач оценит питание, сон, лекарства и результаты обследований. При обмороке, боли в груди или одышке в покое нужна срочная помощь."}]},{"id":"pregnancy-020","number":20,"week":7,"title":"Вздутие и запоры в начале беременности: почему это так часто бывает","image":null,"blocks":[{"type":"paragraph","text":"К вечеру живот становится больше, одежда давит, а походы в туалет требуют усилий. На раннем сроке такие изменения нередко связаны с работой кишечника. Вздутие может быть заметным, даже когда матка ещё не настолько увеличилась, чтобы заметно менять форму живота."},{"type":"heading","text":"Почему пищеварение замедляется"},{"type":"paragraph","text":"Прогестерон расслабляет гладкую мускулатуру, в том числе в стенке кишечника. Его содержимое продвигается медленнее, из него успевает всосаться больше воды — стул становится плотнее."},{"type":"paragraph","text":"Одновременно могут меняться привычки: из-за тошноты вы едите меньше овощей, пьёте небольшими порциями, реже гуляете. Некоторые препараты, особенно железо, тоже способны усиливать запор."},{"type":"paragraph","text":"На этом сроке основная причина обычно связана с гормональными изменениями и образом жизни. Давление увеличенной матки становится более значимым позже."},{"type":"heading","text":"Запор — это не только редкий стул"},{"type":"paragraph","text":"Обратите внимание не только на частоту, но и на ощущения. О запоре могут говорить:"},{"type":"list-item","text":"твёрдый, сухой или комковатый стул;"},{"type":"list-item","text":"необходимость сильно тужиться;"},{"type":"list-item","text":"болезненное опорожнение;"},{"type":"list-item","text":"ощущение, что кишечник опорожнился не полностью."},{"type":"paragraph","text":"Ежедневный стул не является обязательной нормой для всех. Важно, чтобы опорожнение было комфортным и не сопровождалось перечисленными трудностями."},{"type":"heading","text":"Добавляйте клетчатку постепенно"},{"type":"paragraph","text":"Её источники — овсянка, цельнозерновой хлеб, овощи, фрукты и бобовые. Но резкое увеличение клетчатки способно усилить газообразование."},{"type":"paragraph","text":"Начните с небольших изменений: добавьте овощи к обеду, замените часть белого хлеба цельнозерновым, попробуйте фрукт на перекус. Если сырые овощи вызывают дискомфорт, используйте запечённые или тушёные."},{"type":"paragraph","text":"Не нужно одновременно съедать много отрубей, чернослива и бобовых. Подбирайте количество по переносимости."},{"type":"heading","text":"Пейте и двигайтесь"},{"type":"paragraph","text":"Клетчатка лучше работает при достаточном поступлении жидкости. Если врач не ограничивал питьё, регулярно предлагайте себе воду, особенно при увеличении количества пищевых волокон."},{"type":"paragraph","text":"Небольшая прогулка после еды и перерывы в длительном сидении тоже могут помочь. При этом не требуется специальная интенсивная тренировка «для кишечника»."},{"type":"heading","text":"Создайте удобные условия для туалета"},{"type":"paragraph","text":"Не откладывайте позыв. Попробуйте выделять спокойное время после завтрака, когда кишечник естественным образом активнее."},{"type":"paragraph","text":"Невысокая подставка под ноги может сделать положение удобнее: колени окажутся немного выше бёдер. Не задерживайте дыхание и не пытайтесь добиться результата длительным сильным натуживанием."},{"type":"paragraph","text":"При вздутии также бывает полезно есть медленнее, уменьшить объём одной порции и проверить, не усиливают ли симптомы газированные напитки."},{"type":"heading","text":"Если изменения не помогают"},{"type":"paragraph","text":"Во время беременности можно подобрать слабительное. Врач может рекомендовать средства на основе пищевых волокон, лактулозы или макрогола — выбор зависит от симптомов и переносимости."},{"type":"paragraph","text":"Не отменяйте назначенное железо самостоятельно: иногда достаточно изменить препарат или схему. «Очищающие» чаи, касторовое масло и регулярные клизмы без назначения не подходят."},{"type":"paragraph","text":"При сильной или нарастающей боли, рвоте, выраженном вздутии с отсутствием отхождения газов нужна срочная оценка врача. Кровь в стуле также требует обсуждения."}]},{"id":"pregnancy-021","number":21,"week":7,"title":"Как организовать рабочий день, если сил стало заметно меньше","image":null,"blocks":[{"type":"paragraph","text":"В начале беременности привычный рабочий день иногда ощущается как несколько смен подряд. Особенно если к усталости добавляются тошнота, дорога в транспорте и необходимость выглядеть бодрой на встречах."},{"type":"paragraph","text":"При нормально протекающей беременности многие женщины продолжают работать. Но прежний график может потребовать изменений. Полезнее заранее распределить нагрузку, чем ежедневно дожидаться полного истощения."},{"type":"heading","text":"Найдите часы, когда вам легче"},{"type":"paragraph","text":"В течение нескольких дней отмечайте, когда лучше концентрация, когда усиливается тошнота и после каких задач особенно хочется отдыхать."},{"type":"paragraph","text":"Не обязательно считать утро самым продуктивным временем. Если именно утром вас тошнит, сложную работу можно по возможности перенести ближе к обеду."},{"type":"paragraph","text":"Задачи, требующие внимания и решений, ставьте на часы лучшего самочувствия. Переписку, проверку документов и другие привычные действия оставляйте на менее энергичную часть дня."},{"type":"heading","text":"Сократите количество переключений"},{"type":"paragraph","text":"Когда сил меньше, особенно утомляют одновременные сообщения, звонки и несколько незавершённых задач."},{"type":"paragraph","text":"Попробуйте выбрать одно главное дело на ближайший рабочий отрезок. Например, сначала закончить документ, затем проверить почту, после этого провести созвон."},{"type":"paragraph","text":"На день можно выделить одну основную задачу и несколько небольших. Это способ планирования, а не требование снизить профессиональные ожидания: реальный объём зависит от вашей работы и состояния."},{"type":"heading","text":"Поставьте перерывы в календарь"},{"type":"paragraph","text":"Если ждать свободной минуты, отдых часто не наступает. Попробуйте каждые 45–60 минут делать короткую паузу: встать, пройтись, сменить положение, выпить воды."},{"type":"paragraph","text":"Такой интервал — удобный пример, а не медицинская норма. При необходимости отдыхайте чаще."},{"type":"paragraph","text":"Если работа преимущественно стоя, ищите возможность периодически присесть. При работе за компьютером обеспечьте опору спине и стопам. Удобство рабочего места снижает дополнительное мышечное напряжение."},{"type":"heading","text":"Продумайте питание и запахи"},{"type":"paragraph","text":"Возьмите переносимый перекус: крекеры, фрукт, йогурт при наличии холодильника, небольшой бутерброд. Не откладывайте еду до вечера только потому, что обед сейчас кажется слишком большим."},{"type":"paragraph","text":"Если тошнит от запахов общей кухни, обсудите другое место для перерыва. Бутылку воды лучше держать на виду, чтобы не вспоминать о питье только после работы."},{"type":"heading","text":"Просите конкретные изменения"},{"type":"paragraph","text":"Вместо общего «мне тяжело» бывает проще обозначить решение: перенести ранний созвон, временно уменьшить число поездок, чередовать работу сидя и стоя, предусмотреть короткие перерывы."},{"type":"paragraph","text":"При работе с тяжестями, химическими веществами, ионизирующим излучением, выраженной жарой или ночными сменами нужна отдельная оценка условий труда. Одной перестановки задач в календаре здесь может быть недостаточно."},{"type":"heading","text":"Оставьте силы на дорогу и вечер"},{"type":"paragraph","text":"Рабочая нагрузка включает не только время за столом. Если возможно, выбирайте менее утомительный маршрут и не планируйте все бытовые дела сразу после возвращения."},{"type":"paragraph","text":"Если сонливость мешает безопасно вести автомобиль, не садитесь за руль. А если даже после изменений графика вы с трудом справляетесь с обычными действиями, обсудите состояние с врачом. Выраженную слабость и рвоту важно лечить, а не только учитывать при планировании."}]},{"id":"pregnancy-022","number":22,"week":8,"title":"Первый большой список анализов: зачем беременной столько обследований","image":null,"blocks":[{"type":"paragraph","text":"После первого приёма у вас может оказаться сразу несколько направлений: кровь, моча, мазки, обследования у специалистов. Большой список не означает, что врач подозревает множество заболеваний. Значительная часть исследований нужна, чтобы узнать исходное состояние здоровья и вовремя заметить то, что пока не вызывает симптомов."},{"type":"paragraph","text":"У разных женщин назначения могут отличаться. На список влияют медицинская история, уже выполненные исследования и принятые в стране рекомендации."},{"type":"heading","text":"Общий анализ крови: оценить клетки крови"},{"type":"paragraph","text":"Врач смотрит гемоглобин, эритроциты, тромбоциты и другие показатели. Это помогает выявить анемию и определить, нужны ли дополнительные исследования."},{"type":"paragraph","text":"Если гемоглобин снижен, одного этого показателя недостаточно, чтобы выбрать лечение. Врач учитывает характеристики эритроцитов, питание и при необходимости назначает ферритин или другие анализы."},{"type":"paragraph","text":"Цифры на бланке также оценивают с учётом беременности: обычные лабораторные отметки «выше» или «ниже» не всегда означают болезнь."},{"type":"heading","text":"Группа крови, резус-фактор и антитела: спланировать наблюдение"},{"type":"paragraph","text":"Эти данные важны для ведения беременности и возможной медицинской помощи в дальнейшем."},{"type":"paragraph","text":"При отрицательном резус-факторе врач определяет необходимость контроля антител и профилактических мероприятий. Сам по себе отрицательный резус — особенность крови, а не диагноз и не признак проблемы у малыша."},{"type":"heading","text":"Обследование на инфекции: обнаружить то, что может протекать незаметно"},{"type":"paragraph","text":"В начале наблюдения обычно предлагают анализы на ВИЧ, сифилис, гепатиты B и C. Их назначают не из-за предположений об образе жизни женщины."},{"type":"paragraph","text":"Некоторые инфекции долго не вызывают жалоб. Если их обнаружить, можно своевременно подобрать лечение, наблюдение и меры защиты ребёнка. Реактивный результат скринингового теста при необходимости проверяют подтверждающими исследованиями."},{"type":"heading","text":"Общий анализ мочи и посев: разные задачи"},{"type":"paragraph","text":"Общий анализ оценивает ряд показателей, включая белок и клетки. Посев помогает выявить бактерии, в том числе когда нет боли или жжения при мочеиспускании."},{"type":"paragraph","text":"Эти исследования не полностью заменяют друг друга. Чтобы уменьшить вероятность загрязнения образца, используйте стерильный контейнер и соблюдайте инструкцию по сбору средней порции мочи."},{"type":"heading","text":"Глюкоза и ТТГ: проверить обмен веществ"},{"type":"paragraph","text":"Глюкоза помогает выявить нарушения углеводного обмена. Раннее нормальное значение не отменяет обследование на гестационный диабет в предусмотренный позже срок."},{"type":"paragraph","text":"ТТГ используют для оценки работы щитовидной железы. Результат интерпретируют с учётом срока беременности и при необходимости дополняют другими показателями."},{"type":"paragraph","text":"Мазки и обследование шейки матки решают отдельные задачи; их объём зависит от жалоб, истории и предыдущих результатов."},{"type":"heading","text":"Как пройти обследования без лишней суеты"},{"type":"paragraph","text":"Уточните, какие анализы можно сдать одновременно и для каких нужен голодный промежуток. Не все исследования требуют сдачи натощак. Лекарства самостоятельно не отменяйте — спросите, как поступить в день анализа."},{"type":"paragraph","text":"Заранее выясните, когда и с кем обсудить результаты. При склонности к обморокам предупредите сотрудника процедурного кабинета."},{"type":"paragraph","text":"Не добавляйте самостоятельно коммерческие панели «на все инфекции» или «все гормоны». Для каждого дополнительного анализа полезно понимать: какое решение изменится в зависимости от результата?"}]},{"id":"pregnancy-023","number":23,"week":8,"title":"Можно ли лечить зубы во время беременности","image":null,"blocks":[{"type":"paragraph","text":"Да. Беременность сама по себе не запрещает лечение зубов, местное обезболивание и необходимые стоматологические снимки. Терпеть боль до родов или ждать, пока небольшой кариес превратится в серьёзную проблему, не нужно."},{"type":"paragraph","text":"Главное — сообщить стоматологу о беременности и подобрать лечение с учётом вашего состояния."},{"type":"heading","text":"Почему зубы и дёсны требуют внимания"},{"type":"paragraph","text":"Гормональные изменения могут усиливать реакцию дёсен на зубной налёт. Они становятся более чувствительными, отекают и кровоточат при чистке. Это повод улучшить уход и обратиться к стоматологу, а не перестать пользоваться щёткой."},{"type":"paragraph","text":"На зубы также влияют частые перекусы, трудности с гигиеной из-за тошноты и контакт эмали с желудочной кислотой при рвоте."},{"type":"paragraph","text":"Изменения в полости рта не стоит автоматически объяснять тем, что «малыш забирает кальций из зубов». При боли и разрушении зуба нужно искать конкретную стоматологическую причину."},{"type":"heading","text":"Что можно делать"},{"type":"paragraph","text":"Во время беременности по показаниям проводят осмотр, профессиональную гигиену, лечение кариеса, лечение каналов и удаление зуба, если сохранить его невозможно или есть другая необходимость."},{"type":"paragraph","text":"Срочную помощь оказывают на любом сроке. Отсрочка при боли, воспалении или инфекции может привести к более сложному лечению."},{"type":"paragraph","text":"Плановые длительные процедуры иногда удобнее проводить во втором триместре: тошнота часто уменьшается, а сидеть в кресле ещё относительно комфортно. Но это вопрос удобства и индивидуальной ситуации, а не запрет лечиться в первом триместре."},{"type":"heading","text":"Можно ли делать обезболивающий укол"},{"type":"paragraph","text":"Местная анестезия применяется при беременности. Стоматолог выбирает препарат и дозу, учитывая заболевания, аллергию и особенности лечения."},{"type":"paragraph","text":"Небольшое количество адреналина в составе местного анестетика не является автоматическим противопоказанием. Просить лечить зуб «совсем без обезболивания» только из-за беременности обычно не требуется."},{"type":"paragraph","text":"Седация и общий наркоз — другие методы. Их необходимость и безопасность оценивают отдельно."},{"type":"heading","text":"Что со снимками"},{"type":"paragraph","text":"Если снимок нужен для диагностики или правильного лечения, его можно выполнить во время беременности. Стоматолог выбирает подходящий метод и минимально необходимый объём исследования."},{"type":"paragraph","text":"Не каждый визит требует рентгена, но отказ от действительно нужного снимка способен затруднить лечение. Сообщите о беременности до исследования и выполняйте инструкции персонала."},{"type":"heading","text":"Как подготовиться к приёму"},{"type":"paragraph","text":"Назовите срок, перечислите лекарства и расскажите об особенностях беременности. Если вас тошнит по утрам, попросите запись на более комфортное время. При необходимости договоритесь о коротких перерывах."},{"type":"paragraph","text":"При отёке лица, температуре, нарастающей боли, затруднении глотания или открывания рта обращайтесь без промедления."},{"type":"heading","text":"Что делать дома"},{"type":"paragraph","text":"Чистите зубы дважды в день фторсодержащей пастой и ежедневно очищайте промежутки между зубами. Если обычная щётка вызывает рвотный рефлекс, попробуйте вариант с небольшой головкой."},{"type":"paragraph","text":"После рвоты прополощите рот водой. Не чистите зубы сразу: кислота временно делает поверхность эмали более уязвимой. Отбеливание и другие необязательные косметические процедуры разумно отложить."}]},{"id":"pregnancy-024","number":24,"week":8,"title":"Уход за кожей во время беременности: какие средства можно продолжать использовать","image":null,"blocks":[{"type":"paragraph","text":"После положительного теста не обязательно полностью менять косметичку. Мягкое очищение, увлажнение и защита от солнца остаются основой ухода. Проверить прежде всего стоит средства с активными лечебными компонентами, особенно препараты от акне и пигментации."},{"type":"paragraph","text":"Кожа при беременности может стать суше, чувствительнее или, наоборот, более склонной к высыпаниям. Поэтому даже привычное средство иногда начинает щипать или раздражать."},{"type":"heading","text":"Что обычно можно оставить"},{"type":"paragraph","text":"Мягкое средство для умывания, обычный увлажняющий крем и бальзам для губ чаще всего подходят и дальше. Увлажняющие компоненты вроде глицерина и гиалуроновой кислоты не требуют автоматической отмены."},{"type":"paragraph","text":"Не нужно добавлять много новых этапов. Если кожа чувствительная, предпочтительнее простые средства без выраженной отдушки. Умывание «до скрипа», жёсткие скрабы и несколько кислотных продуктов одновременно могут усилить раздражение."},{"type":"heading","text":"Защита от солнца особенно полезна"},{"type":"paragraph","text":"Во время беременности может усиливаться пигментация. Используйте солнцезащитное средство широкого спектра с SPF не ниже 30, дополняя его тенью и головным убором."},{"type":"paragraph","text":"Минеральные фильтры — оксид цинка и диоксид титана — удобный вариант, в том числе для чувствительной кожи. Но наличие других разрешённых фильтров само по себе не означает, что средство опасно."},{"type":"paragraph","text":"Выбирайте продукт, который комфортно наносить в достаточном количестве. Надпись «для беременных» не заменяет проверку состава и переносимости."},{"type":"heading","text":"Что следует убрать"},{"type":"paragraph","text":"Во время беременности рекомендуют избегать ретиноидов. Они встречаются в препаратах от акне и антивозрастном уходе: ищите названия retinol, retinal, tretinoin, adapalene, tazarotene и другие производные витамина А."},{"type":"paragraph","text":"Средства с гидрохиноном для осветления кожи также лучше исключить."},{"type":"paragraph","text":"Если до новости о беременности вы пользовались кремом с ретинолом, прекратите применение и покажите состав врачу. Использование наружного средства не равнозначно приёму ретиноидов внутрь; делать самостоятельные выводы о последствиях не нужно. При приёме изотретиноина внутрь необходимо срочно связаться с назначившим его врачом."},{"type":"heading","text":"А кислоты и средства от прыщей?"},{"type":"paragraph","text":"Общего запрета на все кислоты нет. Азелаиновую кислоту, некоторые средства с гликолевой кислотой и бензоилпероксидом можно использовать по показаниям после согласования ухода."},{"type":"paragraph","text":"Салициловая кислота в невысокой концентрации на небольшом участке кожи отличается от концентрированного пилинга или нанесения на большую площадь. Самостоятельные сильные пилинги стоит отложить."},{"type":"paragraph","text":"Значение имеют концентрация, частота применения, площадь нанесения и состояние кожи. Через повреждённую кожу вещества могут всасываться активнее."},{"type":"heading","text":"Как проверить косметичку без лишних покупок"},{"type":"paragraph","text":"Сфотографируйте составы средств, особенно сывороток, пилингов и препаратов от акне. Отдельно отметьте продукты, которые вызывают жжение или зуд."},{"type":"paragraph","text":"До консультации можно оставить простую схему: очищение, увлажнение, SPF. Назначенное лечение кожного заболевания не заменяйте самостоятельно маслами или «натуральными» смесями: растительное происхождение не гарантирует безопасность и отсутствие аллергии."}]},{"id":"pregnancy-025","number":25,"week":9,"title":"Кофе во время беременности: сколько допустимо","image":null,"blocks":[{"type":"paragraph","text":"Если утро начинается с любимого кофе, беременность не обязательно требует отказаться от него полностью. Основной ориентир — не более 200 мг кофеина в сутки из всех продуктов и напитков вместе."},{"type":"paragraph","text":"Это верхний рекомендуемый предел, а не количество, которое стоит употреблять ежедневно. Если кофе вызывает сердцебиение, усиливает тревожность или мешает спать, ваша комфортная доза может быть значительно меньше."},{"type":"heading","text":"Почему считают кофеин, а не чашки"},{"type":"paragraph","text":"Одинаковые на вид чашки могут содержать разное количество кофеина. Оно зависит от зёрен, способа приготовления, крепости, объёма и числа порций эспрессо."},{"type":"paragraph","text":"Большой латте не обязательно слабее маленького чёрного кофе. Если в нём два шота эспрессо, молоко увеличивает объём напитка, но не убирает кофеин."},{"type":"paragraph","text":"Поэтому совет «две чашки можно» слишком неточный. В кофейне уточняйте состав порции и, если доступно, количество кофеина."},{"type":"heading","text":"Учитывайте чай и другие источники"},{"type":"paragraph","text":"Кофеин есть не только в кофе, но и в чёрном и зелёном чае, матча, коле, шоколаде, энергетиках и некоторых лекарствах."},{"type":"paragraph","text":"Ориентировочно чашка растворимого кофе может содержать около 100 мг, а чашка чая — около 75 мг. Значения меняются в зависимости от порции и приготовления."},{"type":"paragraph","text":"Например, кофе с 100 мг кофеина и два чая по 75 мг дают уже 250 мг за день. Это расчётный пример, а не точное содержание любых напитков с такими названиями."},{"type":"paragraph","text":"Если на банке указано содержание на 100 мл, пересчитайте его на весь объём: 32 мг на 100 мл в 250 мл напитка превращаются в 80 мг."},{"type":"heading","text":"Почему при беременности рекомендуют ограничение"},{"type":"paragraph","text":"Кофеин проходит через плаценту, а организм плода перерабатывает его значительно хуже взрослого. Поэтому привычный для небеременного взрослого предел нельзя переносить на беременность."},{"type":"paragraph","text":"Исследования не позволяют установить абсолютно безрисковую дозу для каждой женщины. Рекомендация ограничиваться 200 мг помогает уменьшить воздействие и используется в клинической практике."},{"type":"heading","text":"Чем заменить часть привычных порций"},{"type":"paragraph","text":"Кофе без кофеина позволяет сохранить вкус и ритуал. В нём обычно остаётся небольшое количество кофеина, поэтому «декаф» не всегда означает полный ноль."},{"type":"paragraph","text":"Можно уменьшить порцию или часть обычного кофе заменить декафом. Если вы привыкли пить много кофе, постепенное сокращение часто переносится легче резкого: реже беспокоят головная боль и выраженная сонливость."},{"type":"paragraph","text":"Не все травяные сборы подходят для ежедневной замены. Проверяйте состав, особенно если напиток позиционируется как лечебный."},{"type":"heading","text":"Когда стоит изменить время приёма"},{"type":"paragraph","text":"Если трудно уснуть, перенесите кофе на первую половину дня. При изжоге или тошноте попробуйте уменьшить порцию и оценить переносимость."},{"type":"paragraph","text":"Если принимаете железо, не запивайте его кофе или чаем: они могут уменьшать всасывание. Для препаратов сульфата железа обычно рекомендуют двухчасовой интервал; уточните инструкцию к своему средству."},{"type":"paragraph","text":"Разовое превышение не позволяет сделать вывод о вреде ребёнку. Пересчитайте привычные порции и скорректируйте дальнейшее употребление."}]},{"id":"pregnancy-026","number":26,"week":9,"title":"Можно ли заниматься сексом во время нормально протекающей беременности","image":null,"blocks":[{"type":"paragraph","text":"При нормально протекающей беременности секс обычно допустим, если вам комфортно и врач не обозначил индивидуальных ограничений. Сам по себе первый триместр не требует воздержания."},{"type":"paragraph","text":"Но возможность заниматься сексом не означает обязанность. Желание может меняться, и в этом вопросе важны ваше самочувствие, согласие и комфорт."},{"type":"heading","text":"Можно ли случайно навредить малышу"},{"type":"paragraph","text":"При вагинальном проникновении пенис или секс-игрушка остаются во влагалище и не достигают ребёнка. Беременность развивается в матке, отделённой шейкой матки."},{"type":"paragraph","text":"Обычная сексуальная активность при неосложнённой беременности не считается опасной для малыша. Не нужно подбирать «особенно безопасную глубину» по чужим советам — ориентируйтесь на отсутствие боли и индивидуальные рекомендации врача."},{"type":"paragraph","text":"При этом болезненность не стоит терпеть. Если какое-то движение неприятно, остановитесь, измените положение или выберите другой способ близости."},{"type":"heading","text":"Что происходит при оргазме"},{"type":"paragraph","text":"Во время оргазма возможны кратковременные сокращения мышц матки. При нормальной беременности они обычно не требуют лечения или отказа от сексуальной жизни."},{"type":"paragraph","text":"Если после близости ощущения быстро проходят и нет других симптомов, это отличается от нарастающей или сохраняющейся боли. При выраженной боли или кровянистых выделениях прекратите сексуальную активность и свяжитесь с врачом."},{"type":"paragraph","text":"Даже небольшие выделения после секса не стоит самостоятельно объяснять только чувствительностью шейки матки — причину лучше уточнить."},{"type":"heading","text":"Почему желания может стать меньше или больше"},{"type":"paragraph","text":"Тошнота, усталость, чувствительность груди и тревога часто снижают интерес к сексу. У некоторых женщин, наоборот, усиливается чувствительность и влечение."},{"type":"paragraph","text":"Оба варианта возможны. Частота секса до беременности не устанавливает обязательную норму на ближайшие месяцы."},{"type":"paragraph","text":"Говорите партнёру конкретно, что сейчас приятно, а что нет. Например, прикосновения к груди могут стать неприятными, хотя раньше нравились. Объятия, массаж, поцелуи и другие формы близости тоже помогают сохранять контакт."},{"type":"heading","text":"Как сделать близость комфортнее"},{"type":"paragraph","text":"Выбирайте время, когда меньше тошнит и достаточно сил. Не обязательно оставлять секс на поздний вечер."},{"type":"paragraph","text":"Если есть сухость, может помочь лубрикант на водной основе без раздражающих добавок. Положение на боку или другое положение, в котором удобно контролировать движения, иногда комфортнее привычного."},{"type":"paragraph","text":"Не используйте обезболивающие средства, чтобы «перетерпеть» болезненность."},{"type":"heading","text":"Когда ограничения действительно нужны"},{"type":"paragraph","text":"Врач может рекомендовать временно отказаться от проникновения или другой сексуальной активности при определённых осложнениях. Позже в беременности к таким ситуациям могут относиться, например, предлежание плаценты с риском кровотечения или излитие вод."},{"type":"paragraph","text":"Если вам назначили «половой покой», уточните, что именно имеется в виду: проникновение, оргазм, использование игрушек или все перечисленное. Срок и объём ограничений должны быть понятны."},{"type":"heading","text":"Защита от инфекций остаётся важной"},{"type":"paragraph","text":"Беременность не защищает от инфекций, передаваемых половым путём. При риске заражения используйте презервативы и обсудите обследование. При герпетических высыпаниях на губах у партнёра следует избегать орально-генитального контакта."},{"type":"paragraph","text":"При обильном кровотечении или сильной боли обращайтесь за срочной медицинской помощью."}]},{"id":"pregnancy-027","number":27,"week":9,"title":"Баня, сауна и горячая ванна: что меняется после наступления беременности","image":null,"blocks":[{"type":"paragraph","text":"Тёплая вода может помочь расслабиться, но приятное согревание и перегрев организма — разные состояния. Во время беременности важен не только показатель на термометре в помещении или ванне, но и то, насколько повышается внутренняя температура тела."},{"type":"paragraph","text":"Особенно осторожно к перегреву относятся в первом триместре, когда формируются основные органы ребёнка."},{"type":"heading","text":"Почему привычная жара может переноситься иначе"},{"type":"paragraph","text":"Во время беременности меняется кровообращение. В жаре сосуды дополнительно расширяются, усиливается потоотделение, организм теряет жидкость."},{"type":"paragraph","text":"В результате могут появиться слабость, головокружение и ощущение, что сейчас станет плохо. Если вы уже мало пьёте из-за тошноты или рвоты, переносимость жары может быть ещё хуже."},{"type":"paragraph","text":"То, что до беременности вы легко проводили в парной много времени, не гарантирует такого же самочувствия сейчас."},{"type":"heading","text":"Баня, сухая сауна и хаммам: есть ли принципиальная разница"},{"type":"paragraph","text":"Условия в них различаются, но каждая из этих процедур может затруднять отдачу тепла и повышать температуру тела. Влажный воздух хаммама не делает его автоматически безопасным: при высокой влажности пот хуже испаряется."},{"type":"paragraph","text":"Исследований недостаточно, чтобы предложить универсальную безопасную комбинацию температуры и продолжительности для всех беременных."},{"type":"paragraph","text":"Поэтому особенно в первом триместре разумно отказаться от горячих парных и процедур, при которых легко перегреться. Если вы хотите сохранить посещение бани в дальнейшем, обсудите это с врачом, учитывая течение беременности и конкретные условия."},{"type":"heading","text":"Чем горячая купель отличается от домашней ванны"},{"type":"paragraph","text":"В джакузи или горячей купели температура воды поддерживается постоянно, а большая часть тела погружена. Организму труднее охлаждаться."},{"type":"paragraph","text":"Обычная домашняя ванна постепенно остывает, но это не делает безопасной воду любой температуры. Ванна должна быть комфортно тёплой, без ощущения необходимости «привыкнуть к жару»."},{"type":"paragraph","text":"Не нужно поддерживать воду горячей постоянным подливанием кипятка или сидеть до выраженного потоотделения."},{"type":"heading","text":"Как оставить водные процедуры комфортными"},{"type":"paragraph","text":"Выбирайте тёплый душ или недолгую комфортную ванну. Если есть сомнения, проверьте температуру воды термометром: ощущение температуры рукой бывает неточным."},{"type":"paragraph","text":"Не запирайте дверь так, чтобы при необходимости вам не могли помочь. Используйте нескользящий коврик и вставайте медленно, особенно если склонны к головокружению."},{"type":"paragraph","text":"Не превращайте водные процедуры в тренировку на выносливость. Резкое охлаждение после сильного нагревания не отменяет уже произошедший перегрев."},{"type":"heading","text":"Какие ощущения требуют остановиться"},{"type":"paragraph","text":"Сразу выходите из жары, если появились слабость, тошнота, головная боль, сильное сердцебиение или головокружение. Перейдите в прохладное место, сядьте или лягте и, если можете, пейте небольшими глотками."},{"type":"paragraph","text":"При обмороке, спутанности сознания или сохраняющемся плохом самочувствии нужна срочная помощь."},{"type":"heading","text":"Если уже сходили в баню, не зная о беременности"},{"type":"paragraph","text":"Сам факт посещения не означает, что ребёнку причинён вред. Значение имеют реальное повышение температуры тела, длительность воздействия и ваше состояние."},{"type":"paragraph","text":"Расскажите врачу об обстоятельствах, особенно если было плохо. Назначать себе дополнительные анализы или делать выводы по чужим историям не нужно."}]},{"id":"pregnancy-028","number":28,"week":10,"title":"Прибавка веса во время беременности: сколько действительно нужно набрать","image":null,"blocks":[{"type":"paragraph","text":"На десятой неделе вес может почти не измениться, немного увеличиться или уменьшиться из-за тошноты. Сравнивать себя с подругой или пытаться соответствовать единственной цифре из приложения не стоит. Ориентир зависит прежде всего от веса до беременности, роста и количества малышей."},{"type":"paragraph","text":"Прибавка нужна для поддержки беременности. Но её оценивают в динамике, вместе с питанием, самочувствием и развитием ребёнка."},{"type":"heading","text":"Почему прибавка — это не только жировая ткань"},{"type":"paragraph","text":"К концу беременности вес складывается из нескольких составляющих: ребёнка, плаценты, околоплодных вод, увеличившейся матки и молочных желёз, дополнительного объёма крови и жидкости."},{"type":"paragraph","text":"Часть прибавки приходится на энергетические запасы. Поэтому желание сохранить прежний вес любой ценой не соответствует физиологическим изменениям беременности."},{"type":"paragraph","text":"При этом выражение «есть за двоих» тоже не означает, что порции нужно удваивать."},{"type":"heading","text":"Как определить свой ориентир"},{"type":"paragraph","text":"Для одноплодной беременности широко используются следующие диапазоны общей прибавки:"},{"type":"list-item","text":"при ИМТ до беременности ниже 18,5 — примерно 12,5–18 кг;"},{"type":"list-item","text":"при ИМТ 18,5–24,9 — 11,5–16 кг;"},{"type":"list-item","text":"при ИМТ 25–29,9 — 7–11,5 кг;"},{"type":"list-item","text":"при ИМТ 30 и выше — 5–9 кг."},{"type":"paragraph","text":"ИМТ рассчитывают так: вес до беременности в килограммах делят на квадрат роста в метрах. Например, при весе 60 кг и росте 1,65 м ИМТ составляет около 22."},{"type":"paragraph","text":"Это ориентиры для всей беременности, а не обязательный план набора. При двойне, выраженном дефиците веса, хронических заболеваниях и других особенностях цели обсуждают индивидуально."},{"type":"heading","text":"Сколько прибавляют в первом триместре"},{"type":"paragraph","text":"Часто ориентируются примерно на 0,5–2 кг за весь первый триместр, но прибавка бывает неравномерной. На десятой неделе отсутствие заметного увеличения веса само по себе ещё не означает недостаточное питание ребёнка."},{"type":"paragraph","text":"Другое дело — продолжающееся снижение веса, особенно вместе с рвотой, невозможностью нормально есть или пить. В такой ситуации нужна помощь с симптомами и оценка питания."},{"type":"paragraph","text":"Не пытайтесь быстро «догнать норму» сладостями или большими порциями через силу."},{"type":"heading","text":"Как взвешиваться без лишней тревоги"},{"type":"paragraph","text":"Если врач не рекомендовал иначе, обычно достаточно отслеживать вес примерно раз в неделю, на одних весах и в похожих условиях."},{"type":"paragraph","text":"Например, утром после туалета, до завтрака, в лёгкой одежде. Суточные колебания могут отражать количество жидкости, пищи и содержимого кишечника."},{"type":"paragraph","text":"Одна цифра не показывает, как растёт малыш. Для этого врач использует совокупность данных наблюдения."},{"type":"heading","text":"Что помогает удерживаться в своём диапазоне"},{"type":"paragraph","text":"Регулярное питание, посильная активность и разнообразие рациона полезнее строгого подсчёта каждого грамма. В первом триместре обычно не требуется специально увеличивать калорийность только из-за беременности."},{"type":"paragraph","text":"Самостоятельное похудение, голодание и препараты для снижения веса не подходят. Если прибавка выходит за ориентиры, врач поможет оценить причины и скорректировать питание."},{"type":"paragraph","text":"О резком увеличении веса за короткое время, особенно вместе с выраженными отёками или ухудшением самочувствия, также стоит сообщить врачу."}]},{"id":"pregnancy-029","number":29,"week":10,"title":"Можно ли продолжать тренироваться, если вы занимались спортом до беременности","image":null,"blocks":[{"type":"paragraph","text":"При неосложнённой беременности привычную физическую активность чаще всего можно продолжать. Беременность не требует автоматически отменять бег, плавание или силовые упражнения. Но программа должна учитывать самочувствие, особенности нагрузки и медицинские ограничения."},{"type":"paragraph","text":"Задача на ближайшие месяцы — поддерживать здоровье и форму в подходящем режиме. Прежние рабочие веса, темп и продолжительность занятия не обязаны сохраняться."},{"type":"heading","text":"Начните с обсуждения своей реальной программы"},{"type":"paragraph","text":"На приёме недостаточно сказать «я занимаюсь спортом». Расскажите, чем именно: бегаете ли длинные дистанции, работаете с тяжёлыми весами, тренируетесь в жарком помещении, участвуете в соревнованиях."},{"type":"paragraph","text":"Врачу важны частота, интенсивность, травмы, хронические заболевания и симптомы во время занятий. Особенно полезна индивидуальная оценка, если нагрузки были высокоинтенсивными."},{"type":"paragraph","text":"Если беременность протекает нормально и противопоказаний нет, обычно можно продолжать знакомые занятия с необходимыми изменениями."},{"type":"heading","text":"Как выбрать интенсивность"},{"type":"paragraph","text":"Для большинства беременных ориентир — не менее 150 минут умеренной активности в неделю, распределённых на несколько дней. Это общая цель, а не требование выполнить план любой ценой."},{"type":"paragraph","text":"Умеренную нагрузку удобно оценивать разговорным тестом: вы можете говорить фразами без выраженной одышки. Универсального запрета повышать пульс выше 140 ударов в минуту для всех беременных нет."},{"type":"paragraph","text":"Женщины, которые до беременности регулярно тренировались интенсивно, иногда могут сохранять более высокую нагрузку. Но такое решение лучше принимать индивидуально, а не по общей статье."},{"type":"heading","text":"Что можно изменить уже сейчас"},{"type":"paragraph","text":"Сократите занятие, если быстро устаёте. Увеличьте время отдыха между подходами. В дни тошноты замените тренировку прогулкой или перенесите её."},{"type":"paragraph","text":"Перед занятием разомнитесь, после — постепенно снижайте нагрузку. Пейте воду и не тренируйтесь в условиях перегрева."},{"type":"paragraph","text":"Оценивайте не только ощущения во время упражнения, но и восстановление: выраженная слабость на оставшуюся часть дня — повод уменьшить объём."},{"type":"heading","text":"Нужны ли особые запреты на силовые упражнения"},{"type":"paragraph","text":"Приседания, тяговые движения и работа с гантелями не запрещены всем беременным. Значение имеют техника, нагрузка, дыхание и симптомы."},{"type":"paragraph","text":"Не стремитесь к максимальным весам и повторениям через предельное усилие. Избегайте длительной задержки дыхания. При боли, ощущении давления в тазу или подтекании мочи упражнение нужно изменить и обсудить симптомы со специалистом."},{"type":"paragraph","text":"Нет необходимости заранее исключать все упражнения на мышцы живота: программу корректируют по сроку и переносимости."},{"type":"heading","text":"Какие занятия требуют отказа или замены"},{"type":"paragraph","text":"Не подходят контактные виды спорта с риском удара в живот, дайвинг, горячая йога. Занятия с высокой вероятностью падения — например, горные лыжи или верховая езда — лучше заменить."},{"type":"paragraph","text":"По мере роста живота меняются равновесие и удобство движений. Поэтому безопасная программа на десятой неделе может потребовать дальнейшей адаптации."},{"type":"heading","text":"Когда сразу остановиться"},{"type":"paragraph","text":"Прекратите тренировку при кровянистых выделениях, боли в груди, выраженном головокружении, необычной одышке, сильной боли в животе или подтекании жидкости из влагалища."},{"type":"paragraph","text":"Не продолжайте занятие, чтобы проверить, «пройдёт ли само». Свяжитесь с врачом, а при тяжёлых симптомах обращайтесь за срочной помощью."}]},{"id":"pregnancy-030","number":30,"week":10,"title":"НИПТ: что это за исследование и чем оно отличается от обычного скрининга","image":null,"blocks":[{"type":"paragraph","text":"НИПТ — неинвазивный пренатальный тест. Для него берут кровь из вены беременной женщины и исследуют находящиеся в ней фрагменты ДНК. Часть этих фрагментов происходит из плаценты и позволяет оценить вероятность некоторых хромосомных особенностей у ребёнка."},{"type":"paragraph","text":"Это высокоточный скрининг, но не диагностический тест. Он оценивает риск и не заменяет все обследования беременности."},{"type":"heading","text":"С какого срока его делают"},{"type":"paragraph","text":"Большинство стандартных вариантов НИПТ выполняют начиная с 10 акушерских недель. До этого количества ДНК плацентарного происхождения в образце может быть недостаточно для надёжного анализа."},{"type":"paragraph","text":"Перед исследованием важно уточнить срок и количество плодов. При двойне, донорской яйцеклетке и некоторых других обстоятельствах возможности тестов различаются — лаборатории и врачу нужно сообщить эти особенности заранее."},{"type":"paragraph","text":"Для самого НИПТ обычно не требуется голодание, но подготовку уточняют в выбранной лаборатории."},{"type":"heading","text":"Что проверяет основной вариант"},{"type":"paragraph","text":"Наиболее изучен НИПТ для оценки риска трёх состояний:"},{"type":"list-item","text":"трисомии 21 — синдрома Дауна;"},{"type":"list-item","text":"трисомии 18 — синдрома Эдвардса;"},{"type":"list-item","text":"трисомии 13 — синдрома Патау."},{"type":"paragraph","text":"Для этих состояний он точнее традиционного биохимического скрининга и реже даёт ложноположительный результат."},{"type":"paragraph","text":"Расширенные панели могут включать половые хромосомы и редкие изменения. Но больше пунктов не обязательно означает больше пользы. Для редких состояний точность и клиническая ценность могут быть ниже; рутинно выбирать самую широкую панель не требуется."},{"type":"heading","text":"Чем отличается обычный скрининг"},{"type":"paragraph","text":"Комбинированный скрининг первого триместра учитывает данные УЗИ, возраст и другие характеристики женщины, а также биохимические показатели крови — обычно PAPP-A и свободную β-субъединицу ХГЧ."},{"type":"paragraph","text":"НИПТ использует другой материал для расчёта риска — фрагменты ДНК. При этом УЗИ оценивает анатомию и развитие ребёнка, которые анализ крови увидеть не может."},{"type":"paragraph","text":"Даже при хорошем результате НИПТ плановые УЗИ остаются необходимыми. Как включить тест в общий маршрут скрининга и какие анализы не нужно дублировать, обсудите с врачом."},{"type":"heading","text":"Как понимать результат"},{"type":"paragraph","text":"Низкий риск означает, что вероятность проверенных состояний существенно снизилась. Это не гарантия отсутствия всех генетических заболеваний и пороков развития."},{"type":"paragraph","text":"Высокий риск требует консультации генетика и обсуждения подтверждающей диагностики — исследования материала, полученного при биопсии хориона или амниоцентезе. Делать окончательные выводы только по НИПТ нельзя."},{"type":"paragraph","text":"Результат не получен — отдельная ситуация. Причиной может быть недостаточное количество плацентарной ДНК, но такой ответ нельзя считать равным низкому риску. Врач предложит дальнейший план: дополнительное УЗИ, консультацию, повторный анализ или диагностическое исследование."},{"type":"heading","text":"Почему возможна ошибка"},{"type":"paragraph","text":"Тест анализирует смесь ДНК, преимущественно материнской, а связанная с беременностью часть поступает главным образом из плаценты. Иногда особенности плаценты или организма женщины приводят к результату, который не отражает хромосомы ребёнка."},{"type":"paragraph","text":"Поэтому перед оплатой важно выяснить, что именно проверяется, подходит ли метод для вашей беременности и кто поможет разобраться с неоднозначным ответом."},{"type":"paragraph","text":"НИПТ можно обсуждать независимо от возраста женщины. Решение пройти исследование принимают после объяснения его возможностей и ограничений."}]},{"id":"pregnancy-031","number":31,"week":11,"title":"Первый скрининг: что будет происходить и как к нему подготовиться","image":null,"blocks":[{"type":"paragraph","text":"Первый скрининг помогает оценить развитие малыша и вероятность некоторых хромосомных нарушений. Это плановое обследование, которое предлагают и при хорошем самочувствии, и при отсутствии заболеваний в семье."},{"type":"paragraph","text":"В России его обычно проводят с 11 недель 0 дней до 13 недель 6 дней. Записаться лучше заранее: для определённых измерений важен не только срок, но и размер плода."},{"type":"heading","text":"Из чего состоит обследование"},{"type":"paragraph","text":"Комбинированный скрининг включает УЗИ, анализ крови и расчёт индивидуальных рисков."},{"type":"paragraph","text":"На УЗИ врач уточняет срок беременности, оценивает сердцебиение, количество плодов и доступные для осмотра анатомические структуры. Измеряет копчико-теменной размер — расстояние от темени до копчика — и толщину воротникового пространства, то есть участка с жидкостью под кожей в области шеи."},{"type":"paragraph","text":"В крови определяют два показателя: свободную β-субъединицу ХГЧ и PAPP-A — белок, связанный с беременностью. Их значения программа сопоставляет с данными УЗИ и сведениями о женщине."},{"type":"paragraph","text":"Так рассчитывают вероятность трисомий 21, 18 и 13 — состояний, при которых присутствует дополнительная хромосома. В некоторых программах также оценивают риск преэклампсии и других осложнений беременности."},{"type":"heading","text":"Как проходит УЗИ"},{"type":"paragraph","text":"Чаще исследование выполняют через переднюю брюшную стенку: на кожу наносят гель и перемещают датчик. Иногда для уточнения деталей нужен вагинальный датчик. Такое исследование по показаниям допустимо во время беременности."},{"type":"paragraph","text":"Если малыш находится в неудобном для измерений положении, специалист может попросить повернуться, немного пройтись или подождать. Более продолжительное обследование само по себе не означает, что обнаружена проблема."},{"type":"heading","text":"Как подготовиться"},{"type":"paragraph","text":"Специальная диета для «хорошего результата» не нужна. Исключение сладкого, цитрусовых или других продуктов накануне не исправляет и не улучшает показатели скрининга."},{"type":"paragraph","text":"Практический список подготовки:"},{"type":"list-item","text":"Уточните в клинике, нужно ли приходить натощак для забора крови."},{"type":"list-item","text":"Спросите, требуется ли наполненный мочевой пузырь для УЗИ."},{"type":"list-item","text":"Возьмите предыдущие заключения, направление и результаты НИПТ, если он уже выполнен."},{"type":"list-item","text":"Сообщите об ЭКО, многоплодной беременности, принимаемых лекарствах и хронических заболеваниях."},{"type":"list-item","text":"Проверьте, правильно ли записаны ваш вес, срок и другие данные для расчёта."},{"type":"paragraph","text":"Лекарства перед обследованием самостоятельно не отменяйте. Если назначено исследование натощак, а пропуск еды вызывает выраженную тошноту, заранее обсудите время записи."},{"type":"heading","text":"Что важно узнать после обследования"},{"type":"paragraph","text":"Уточните, когда будет готов общий результат и кто его объяснит. Заключение УЗИ и итоговый расчёт рисков могут выдать в разные дни."},{"type":"paragraph","text":"Скрининг не ставит окончательный диагноз и не проверяет все возможные заболевания. Низкий риск — благоприятный результат, но не абсолютная гарантия. Повышенный риск означает, что необходимо обсудить дополнительные исследования."},{"type":"paragraph","text":"Перед уходом полезно задать один конкретный вопрос: «Какой следующий шаг нужен именно по моему результату и в какой срок?»"}]},{"id":"pregnancy-032","number":32,"week":11,"title":"Можно ли путешествовать и летать на самолёте во время беременности","image":null,"blocks":[{"type":"paragraph","text":"При нормально протекающей беременности поездки и редкие авиаперелёты обычно допустимы. Нет данных, что обычный перелёт сам по себе вызывает выкидыш или нарушает развитие малыша."},{"type":"paragraph","text":"Решение о путешествии зависит прежде всего от самочувствия, особенностей беременности, длительности дороги и доступности медицинской помощи в месте назначения."},{"type":"heading","text":"Когда путешествовать удобнее"},{"type":"paragraph","text":"Многим становится комфортнее во втором триместре: тошнота ослабевает, энергии прибавляется, а живот ещё не слишком ограничивает движения. Но это вопрос удобства, а не запрет на поездки в первом триместре."},{"type":"paragraph","text":"Если сейчас вас часто тошнит, трудно пить или вы быстро устаёте, насыщенная экскурсионная программа и несколько пересадок могут оказаться тяжёлыми. Полезнее выбрать короткий маршрут, предусмотреть отдых и оставить возможность менять планы."},{"type":"paragraph","text":"Перед покупкой билетов обсудите поездку с врачом, если были кровянистые выделения, выраженная анемия, тромбозы, серьёзные заболевания сердца или лёгких либо другие осложнения."},{"type":"heading","text":"Что проверить до поездки"},{"type":"paragraph","text":"Оцените не только дорогу, но и условия на месте:"},{"type":"list-item","text":"Есть ли рядом клиника, которая оказывает помощь беременным?"},{"type":"list-item","text":"Покрывает ли страховка осложнения беременности на вашем сроке?"},{"type":"list-item","text":"Нет ли в регионе инфекционных рисков, особенно малярии или вируса Зика?"},{"type":"list-item","text":"Какие прививки или профилактические препараты требуются для поездки?"},{"type":"list-item","text":"Не совпадает ли путешествие со сроками скрининга или другого важного обследования?"},{"type":"paragraph","text":"Правила авиакомпаний различаются. Уточняйте ограничения и требования к справке с учётом срока на обратном рейсе, а не только при вылете."},{"type":"paragraph","text":"Сохраните на телефоне медицинские документы, список лекарств и контакт врача. Препараты, которые принимаете постоянно, лучше положить в ручную кладь."},{"type":"heading","text":"Как облегчить дорогу"},{"type":"paragraph","text":"При длительном неподвижном сидении повышается риск образования тромбов. Это касается самолёта, автомобиля, автобуса и поезда, особенно если поездка длится больше четырёх часов."},{"type":"paragraph","text":"В дороге:"},{"type":"list-item","text":"регулярно двигайте стопами и напрягайте икроножные мышцы;"},{"type":"list-item","text":"вставайте и немного ходите, когда это безопасно;"},{"type":"list-item","text":"в автомобиле планируйте остановки;"},{"type":"list-item","text":"выбирайте свободную одежду и удобную обувь;"},{"type":"list-item","text":"держите воду под рукой."},{"type":"paragraph","text":"Для длительного перелёта стоит обсудить компрессионные чулки: важны подходящие размер и степень компрессии. Аспирин или антикоагулянты «на всякий случай» самостоятельно не принимают."},{"type":"paragraph","text":"В самолёте ремень располагают низко, на костях таза, под животом, и сохраняют застёгнутым, пока сидят."},{"type":"heading","text":"Когда планы нужно изменить"},{"type":"paragraph","text":"Кровотечение, сильная боль, выраженная слабость или обезвоживание — повод сначала получить медицинскую помощь."},{"type":"paragraph","text":"Если в дороге появились односторонние боль и отёк ноги, нужна срочная оценка врача. При внезапной одышке, боли в груди или обмороке вызывайте экстренную помощь."},{"type":"paragraph","text":"Хорошо организованное путешествие оставляет достаточно времени на сон, еду, движение и отдых. Беременность не требует отказываться от впечатлений, но делает гибкий маршрут особенно полезным."}]},{"id":"pregnancy-033","number":33,"week":11,"title":"Беременность и работа за компьютером: как сделать рабочее место удобнее","image":null,"blocks":[{"type":"paragraph","text":"Работать за компьютером во время беременности можно. Исследования не показывают связи обычной работы с монитором с выкидышами или врождёнными нарушениями у ребёнка."},{"type":"paragraph","text":"Основные неудобства связаны с длительным сидением, напряжением мышц, утомлением глаз и недостатком перерывов. По мере изменения тела рабочее место стоит подстраивать заново."},{"type":"heading","text":"Начните со стула и положения ног"},{"type":"paragraph","text":"Сядьте так, чтобы спина опиралась на спинку, а стопы полностью стояли на полу. Если после настройки высоты стула ноги не достают до пола, используйте устойчивую подставку."},{"type":"paragraph","text":"Под поясницу можно положить небольшую подушку или свёрнутое полотенце. Опора должна помогать сидеть свободно, без необходимости всё время удерживать спину усилием."},{"type":"paragraph","text":"Между краем сиденья и подколенной областью оставьте небольшой промежуток. Если сиденье давит под коленями, попробуйте уменьшить его глубину или изменить положение спинки."},{"type":"paragraph","text":"Не нужно весь день сохранять одну «идеальную» позу. Даже удобное положение становится утомительным, если долго не двигаться."},{"type":"heading","text":"Настройте экран, клавиатуру и мышь"},{"type":"paragraph","text":"Расположите монитор прямо перед собой, приблизительно на расстоянии вытянутой руки. Верхняя часть экрана обычно находится на уровне глаз или немного ниже."},{"type":"paragraph","text":"Если приходится тянуть голову вперёд, сначала увеличьте шрифт. Если экран стоит сбоку, переставьте его: постоянный поворот шеи создаёт лишнюю нагрузку."},{"type":"paragraph","text":"Клавиатура и мышь должны быть достаточно близко, чтобы локти оставались около тела, а плечи — расслабленными. Запястья не нужно сильно сгибать или упирать в острый край стола."},{"type":"paragraph","text":"Для длительной работы с ноутбуком удобны подставка, отдельная клавиатура и мышь. Это позволяет поднять экран, сохранив комфортное положение рук."},{"type":"heading","text":"Планируйте короткие перерывы"},{"type":"paragraph","text":"Практический вариант — каждые 30–60 минут ненадолго менять положение: встать, пройтись, потянуться без усилия. Это ориентир для организации дня, а не строгий медицинский норматив."},{"type":"paragraph","text":"Можно привязать движение к привычным действиям: после звонка пройти за водой, между задачами размять плечи, часть разговора провести стоя."},{"type":"paragraph","text":"Стол с регулировкой высоты помогает чередовать сидение и стояние. Однако стоять неподвижно весь рабочий день тоже неудобно — смена положения важнее самой конструкции стола."},{"type":"heading","text":"Позаботьтесь о глазах и освещении"},{"type":"paragraph","text":"Уберите блики, настройте комфортную яркость и периодически переводите взгляд на дальние предметы. Во время сосредоточенной работы люди реже моргают, поэтому сухость глаз может усиливаться."},{"type":"paragraph","text":"Если привычные линзы стали вызывать дискомфорт, попробуйте временно перейти на очки и обсудите симптомы с офтальмологом."},{"type":"heading","text":"Когда нужна дополнительная помощь"},{"type":"paragraph","text":"Стойкая боль в спине, онемение кистей или выраженное ухудшение зрения требуют оценки специалиста. Не стоит объяснять их только неудобным креслом."},{"type":"paragraph","text":"По мере роста живота повторно проверяйте расстояние до стола, высоту сиденья и положение рук. Настройка, которая подходила в начале беременности, через несколько недель может потребовать небольших изменений."}]},{"id":"pregnancy-034","number":34,"week":12,"title":"Первый триместр позади: что обычно меняется в самочувствии","image":null,"blocks":[{"type":"paragraph","text":"На 12-й неделе первый триместр ещё подходит к завершению. В распространённом акушерском делении он продолжается до 13 недель 6 дней, а второй начинается с 14 недель 0 дней."},{"type":"paragraph","text":"Но самочувствие не меняется по календарной границе. Одним становится легче уже сейчас, другим — несколькими неделями позже. У некоторых выраженной тошноты и усталости не было с самого начала."},{"type":"heading","text":"Тошнота может постепенно ослабевать"},{"type":"paragraph","text":"Запахи нередко становятся менее раздражающими, возвращается интерес к еде, уменьшается потребность постоянно держать рядом сухарики."},{"type":"paragraph","text":"У многих тошнота проходит к 16–20 неделям. Поэтому её сохранение после 12-й недели само по себе не означает осложнение. При этом тяжёлую рвоту не нужно терпеть до «правильного срока»: если не удаётся пить, уменьшается количество мочи или снижается вес, требуется медицинская помощь."},{"type":"paragraph","text":"Когда аппетит возвращается, расширяйте рацион постепенно. Например, добавьте к привычному завтраку йогурт, к обеду — овощи, к ужину — переносимый источник белка. Не обязательно сразу возвращать все продукты, которые раньше вызывали отвращение."},{"type":"heading","text":"Сил часто становится больше"},{"type":"paragraph","text":"Потребность в дневном сне может уменьшиться, привычная прогулка — даваться легче, а рабочие задачи — требовать меньше усилий."},{"type":"paragraph","text":"Однако хорошее утро ещё не означает, что организм готов к прежнему темпу на весь день. Возвращайте нагрузку постепенно: сначала обычные бытовые дела и короткие прогулки, затем более продолжительную активность."},{"type":"paragraph","text":"Если сильная усталость сохраняется несмотря на сон и отдых, расскажите об этом врачу. Особенно если одновременно появились сердцебиение, одышка при небольшой нагрузке, головокружение или выраженная слабость. Иногда стоит проверить, нет ли анемии или другой причины."},{"type":"heading","text":"Грудь и живот могут ощущаться иначе"},{"type":"paragraph","text":"Болезненность груди иногда уменьшается, хотя сама грудь продолжает меняться. Живот может становиться заметнее, но его размер на этом сроке зависит не только от матки: влияют вздутие, телосложение, особенности мышц живота и предыдущие беременности."},{"type":"paragraph","text":"По внешнему виду живота нельзя оценить, достаточно ли хорошо растёт малыш."},{"type":"paragraph","text":"Запоры, изжога и чувствительность к отдельным запахам могут сохраняться. Улучшение одних симптомов не обязывает все остальные исчезнуть одновременно."},{"type":"heading","text":"Если симптомы стали слабее — это нормально?"},{"type":"paragraph","text":"Постепенное уменьшение тошноты или болезненности груди часто бывает обычным изменением. Выраженность ощущений не служит надёжным показателем развития беременности."},{"type":"paragraph","text":"Домашние тесты тоже не подходят для такого контроля: насыщенность полоски зависит от множества факторов и не показывает состояние малыша."},{"type":"paragraph","text":"Если уменьшение симптомов сопровождается кровотечением, сильной или нарастающей болью, нужно обратиться за помощью."},{"type":"paragraph","text":"На ближайшие недели полезно сохранить простой режим: регулярная еда, достаточный сон, посильное движение и запланированные обследования. Чувствовать себя лучше можно без необходимости немедленно наверстывать всё, что не удалось сделать в начале беременности."}]},{"id":"pregnancy-035","number":35,"week":12,"title":"Как понимать результаты первого скрининга и почему не стоит расшифровывать их самостоятельно","image":null,"blocks":[{"type":"paragraph","text":"В заключении первого скрининга обычно много сокращений, чисел и граф. Самое важное — понимать, какую информацию они дают: скрининг оценивает вероятность определённых состояний, а не устанавливает диагноз."},{"type":"paragraph","text":"Разобраться в принципе расчёта полезно. Но делать вывод по одной строке без остальных результатов нельзя."},{"type":"heading","text":"Что означает запись «1:1000»"},{"type":"paragraph","text":"Она обозначает расчётную вероятность: примерно один случай на тысячу беременностей с подобным сочетанием показателей. Это соответствует 0,1%."},{"type":"paragraph","text":"Для сравнения, 1:100 — это 1%, то есть вероятность выше, чем при 1:1000. Чем меньше число после двоеточия, тем выше расчётный риск."},{"type":"paragraph","text":"Такая запись не предсказывает индивидуальную судьбу ребёнка. Она помогает определить, кому стоит предложить дополнительное обследование."},{"type":"paragraph","text":"Граница между «низким» и «повышенным» риском зависит от программы скрининга. Поэтому порог, найденный на форуме или в заключении знакомой, может не совпадать с используемым в вашей клинике."},{"type":"heading","text":"Почему нельзя оценивать отдельный показатель"},{"type":"paragraph","text":"В расчёте учитывают данные УЗИ, биохимические маркеры и характеристики беременности. Возраст женщины влияет на исходную вероятность, но не заменяет итоговую оценку."},{"type":"paragraph","text":"Показатели крови могут быть представлены в MoM — единицах, которые позволяют сопоставить результат с типичным значением для соответствующего срока. MoM около 1 означает близость к медиане, но отклонение от 1 само по себе не является диагнозом."},{"type":"paragraph","text":"На интерпретацию влияют срок беременности, вес, многоплодие, способ зачатия и другие сведения. Если в бланке ошибочно указан вес или не отмечено ЭКО, сообщите врачу: иногда требуется уточнение расчёта."},{"type":"heading","text":"Что делать при низком риске"},{"type":"paragraph","text":"Обычно продолжают плановое наблюдение. Дополнительные исследования могут понадобиться, если есть отдельные находки на УЗИ, семейные особенности или другие показания."},{"type":"paragraph","text":"Низкий риск по трисомиям не исключает все генетические заболевания и пороки развития. Поэтому следующее плановое УЗИ сохраняет значение."},{"type":"heading","text":"Что происходит при повышенном риске"},{"type":"paragraph","text":"Следующий шаг — консультация специалиста, который сопоставит все данные и объяснит варианты."},{"type":"paragraph","text":"В зависимости от результата могут предложить НИПТ или диагностическое исследование — биопсию хориона либо амниоцентез. НИПТ точнее оценивает вероятность ряда хромосомных нарушений, но тоже остаётся скринингом."},{"type":"paragraph","text":"При некоторых изменениях на УЗИ диагностическое исследование может быть информативнее, чем ещё один скрининговый тест. Выбор зависит от конкретной ситуации и ваших предпочтений после объяснения преимуществ и ограничений."},{"type":"heading","text":"Какие вопросы задать врачу"},{"type":"list-item","text":"Какой именно риск повышен?"},{"type":"list-item","text":"Есть ли изменения на УЗИ или речь только о расчёте?"},{"type":"list-item","text":"Что покажет предлагаемое дополнительное исследование?"},{"type":"list-item","text":"Когда нужно принять решение?"},{"type":"list-item","text":"Потребуется ли консультация генетика?"},{"type":"paragraph","text":"Если в заключении отдельно указан риск преэклампсии, это другой показатель, не связанный напрямую с хромосомным набором малыша. Его тоже нужно обсудить: профилактические решения могут зависеть от срока беременности."}]},{"id":"pregnancy-036","number":36,"week":12,"title":"Резус-фактор и группа крови: зачем их определяют во время беременности","image":null,"blocks":[{"type":"paragraph","text":"Группу крови и резус-фактор проверяют в начале беременности, даже если вы помните их по предыдущим анализам. Эти сведения нужны для безопасной медицинской помощи и оценки риска образования антител к эритроцитам ребёнка."},{"type":"paragraph","text":"Отрицательный резус-фактор — обычная наследственная особенность. Он не мешает зачатию и сам по себе не делает беременность осложнённой."},{"type":"heading","text":"Что именно определяет анализ"},{"type":"paragraph","text":"Группа крови по системе ABO — это O, A, B или AB, привычные обозначения I, II, III и IV."},{"type":"paragraph","text":"Когда говорят о положительном или отрицательном резус-факторе, обычно имеют в виду наличие или отсутствие антигена D на поверхности эритроцитов. При его наличии результат обозначают RhD+, при отсутствии — RhD−."},{"type":"paragraph","text":"Кроме этого, во время беременности исследуют антитела к эритроцитарным антигенам. Это отдельная задача: знать только группу и резус-фактор недостаточно."},{"type":"heading","text":"Когда возникает риск"},{"type":"paragraph","text":"Если у женщины RhD−, а у малыша RhD+, при попадании его эритроцитов в её кровоток иммунная система может выработать антитела против антигена D."},{"type":"paragraph","text":"Такие антитела способны проходить через плаценту и повреждать эритроциты ребёнка. Но различие резус-факторов ещё не означает, что антитела обязательно появились."},{"type":"paragraph","text":"Контакт крови возможен при родах, некоторых кровотечениях, травмах живота и инвазивных процедурах. Важны также предыдущие беременности и переливания крови."},{"type":"paragraph","text":"Правило «первая беременность всегда безопасна» неверно: ситуацию оценивают по истории и анализам."},{"type":"heading","text":"Как помогает профилактика"},{"type":"paragraph","text":"Если женщина RhD-отрицательная и у неё нет собственных иммунных анти-D-антител, врач может назначить антирезусный иммуноглобулин. Он помогает предотвратить их образование."},{"type":"paragraph","text":"Плановую профилактику часто проводят примерно в 28–30 недель. После рождения RhD-положительного ребёнка препарат обычно вводят в течение 72 часов. Конкретная схема зависит от протокола и результатов обследований."},{"type":"paragraph","text":"Дополнительное введение может понадобиться после событий, при которых вероятно смешение крови. Если появились кровянистые выделения, произошла травма живота или предстоит инвазивная процедура, сообщите врачу о своём RhD− сразу."},{"type":"paragraph","text":"Если RhD-отрицательный статус плода достоверно установлен подходящим исследованием, план профилактики может отличаться."},{"type":"heading","text":"Если антитела уже обнаружены"},{"type":"paragraph","text":"Положительный результат требует уточнения: какие это антитела, в каком количестве и вводился ли недавно иммуноглобулин. После профилактического введения в анализе некоторое время могут определяться пассивные антитела."},{"type":"paragraph","text":"При наличии собственных иммунных анти-D-антител профилактический препарат их не устраняет. Тогда врач составляет специальный план наблюдения."},{"type":"heading","text":"Что полезно сохранить в документах"},{"type":"paragraph","text":"Записывайте даты введения иммуноглобулина и храните результаты анализов. Сообщайте о предыдущих беременностях, переливаниях и известных антителах."},{"type":"paragraph","text":"Положительный резус-фактор не отменяет значение исследования антител: помимо антигена D существуют другие эритроцитарные антигены. Поэтому ориентироваться нужно на весь результат обследования, а не только на знак «плюс» или «минус»."}]},{"id":"pregnancy-037","number":37,"week":13,"title":"Второй триместр: почему его часто называют самым комфортным периодом беременности","image":null,"blocks":[{"type":"paragraph","text":"Второй триместр уже близко: в распространённом акушерском делении он начинается с 14 недель 0 дней. Его часто называют самым комфортным периодом, потому что ранние симптомы у многих ослабевают, а нагрузка от большого живота ещё впереди."},{"type":"paragraph","text":"Это частая тенденция, но не обязательный сценарий. Если вы пока не чувствуете прилива сил, это не означает, что беременность протекает неправильно."},{"type":"heading","text":"Почему может стать легче"},{"type":"paragraph","text":"Организм продолжает приспосабливаться к беременности, меняется гормональный фон. У многих постепенно уменьшаются тошнота, чувствительность к запахам и выраженная сонливость."},{"type":"paragraph","text":"Когда легче есть и пить, проще поддерживать привычный режим. Возвращаются прогулки, интерес к работе, желание встречаться с друзьями. Иногда улучшается сон, особенно если раньше его нарушали тошнота или болезненность груди."},{"type":"paragraph","text":"Но объяснять всё тем, что «плацента включилась и теперь делает всю работу», слишком упрощённо. Организм женщины продолжает активно меняться, а потребность в отдыхе сохраняется."},{"type":"heading","text":"Какие ощущения могут появиться"},{"type":"paragraph","text":"По мере роста матки иногда возникают кратковременные тянущие ощущения по бокам нижней части живота, например при резком вставании или повороте. Среди возможных причин — натяжение поддерживающих матку связок."},{"type":"paragraph","text":"Меняйте положение плавно. Если движение вызывает дискомфорт, остановитесь и найдите более удобную позу. Сильную, нарастающую или длительную боль, особенно с кровотечением, температурой или болезненным мочеиспусканием, нельзя автоматически списывать на рост матки."},{"type":"paragraph","text":"Вздутие, запоры и изжога тоже могут продолжаться. Второй триместр не отменяет необходимость регулярной еды, достаточного питья и посильного движения."},{"type":"heading","text":"Как пользоваться вернувшейся энергией"},{"type":"paragraph","text":"Выбирайте устойчивый темп. Например, вместо насыщенного выходного с уборкой, покупками и долгой прогулкой распределите дела на несколько дней."},{"type":"paragraph","text":"Если хочется вернуться к тренировкам, начните с привычной умеренной нагрузки и оцените восстановление. После занятия должны оставаться силы на обычную жизнь, а не только на то, чтобы лечь и больше не вставать."},{"type":"paragraph","text":"Сейчас удобно заняться делами, которые требуют внимания: обсудить рабочий график, запланировать стоматолога, подобрать одежду, записаться на ближайшие обследования. Но превращать улучшение самочувствия в список обязательных достижений не нужно."},{"type":"heading","text":"Эмоциональное состояние тоже бывает разным"},{"type":"paragraph","text":"После первого скрининга некоторым становится спокойнее. Другие продолжают тревожиться или впервые чувствуют, насколько сильно меняется жизнь."},{"type":"paragraph","text":"Если тревога мешает спать, работать или выходить из дома, либо подавленность держится большую часть дней около двух недель, расскажите об этом врачу. Помощь нужна не только при физических симптомах."},{"type":"paragraph","text":"Комфортный второй триместр может выглядеть очень скромно: легче завтракать, меньше уставать после душа, снова получать удовольствие от прогулки. Эти изменения тоже имеют значение — без сравнения с чужой беременностью."}]},{"id":"pregnancy-038","number":38,"week":13,"title":"Питание во втором триместре: нужно ли теперь есть больше","image":null,"blocks":[{"type":"paragraph","text":"Во втором триместре потребность в энергии и питательных веществах постепенно растёт. Однако удваивать порции не нужно: выражение «есть за двоих» плохо отражает реальные потребности организма."},{"type":"paragraph","text":"Гораздо полезнее оценить, хватает ли в рационе белка, овощей, источников кальция, железа и других необходимых веществ."},{"type":"heading","text":"Сколько дополнительной еды требуется"},{"type":"paragraph","text":"Рекомендации по калорийности немного различаются. Например, американские ориентиры предусматривают во втором триместре около 340 дополнительных килокалорий в день для женщины с нормальной массой тела до беременности."},{"type":"paragraph","text":"Это приблизительная величина, а не обязательная ежедневная добавка для каждой. Потребность зависит от исходного веса, активности, количества плодов, динамики прибавки и того, как вы питались раньше."},{"type":"paragraph","text":"По объёму такая добавка скорее похожа на небольшой перекус, чем на ещё один полноценный обед. Например, йогурт без сахара, банан и небольшая порция орехов могут дать сопоставимое количество энергии — в зависимости от размера порций."},{"type":"paragraph","text":"Ежедневно считать калории обычно не требуется, если для этого нет отдельной медицинской причины."},{"type":"heading","text":"На что сделать акцент"},{"type":"paragraph","text":"Белок. Старайтесь включать его источники в основные приёмы пищи: хорошо приготовленные мясо, птицу, рыбу, яйца, бобовые, тофу, молочные продукты. Если мясо по-прежнему не нравится, подойдут другие варианты."},{"type":"paragraph","text":"Овощи, фрукты и цельнозерновые продукты. Они помогают получать пищевые волокна и поддерживать регулярный стул. Увеличивать количество клетчатки лучше постепенно, чтобы не усиливать вздутие."},{"type":"paragraph","text":"Источники кальция. Это молоко, йогурт, творог, подходящие сыры, а также обогащённые кальцием альтернативы. У растительных напитков проверяйте состав: не каждый содержит достаточно кальция и белка."},{"type":"paragraph","text":"Источники железа. Мясо, бобовые и обогащённые крупы могут быть частью рациона. Растительные источники удобно сочетать с продуктами, содержащими витамин C: например, чечевицу — со сладким перцем."},{"type":"heading","text":"Как собрать обычный день"},{"type":"paragraph","text":"Не нужно составлять сложное меню. Возможный вариант:"},{"type":"list-item","text":"завтрак — каша, йогурт и фрукт;"},{"type":"list-item","text":"обед — крупа или картофель, мясо либо бобовые, овощи;"},{"type":"list-item","text":"ужин — рыба или омлет с гарниром;"},{"type":"list-item","text":"перекус по голоду — фрукт, творог, орехи или бутерброд с подходящей начинкой."},{"type":"paragraph","text":"Продукты можно менять с учётом бюджета, переносимости и привычек. Разнообразие оценивают за несколько дней, а не по каждому отдельному приёму пищи."},{"type":"heading","text":"Если аппетит очень сильный или всё ещё слабый"},{"type":"paragraph","text":"При постоянном голоде проверьте, не пропускаете ли вы еду и достаточно ли в ней белка, клетчатки и жиров."},{"type":"paragraph","text":"Если большие порции вызывают тошноту или изжогу, ешьте чаще и понемногу. При продолжающемся снижении веса или выраженном ограничении рациона обсудите питание с врачом."},{"type":"paragraph","text":"Витаминные комплексы не заменяют еду, а хорошее питание не всегда заменяет назначенные препараты. Менять схему добавок лучше после обсуждения ваших потребностей и результатов обследований."}]},{"id":"pregnancy-039","number":39,"week":13,"title":"Как выбрать удобную одежду и бельё для растущего живота","image":null,"blocks":[{"type":"paragraph","text":"Менять гардероб стоит тогда, когда привычная одежда становится неудобной. Универсальной недели для перехода на вещи для беременных нет: у кого-то брюки тесны уже из-за вздутия, у кого-то обычные модели хорошо сидят ещё долго."},{"type":"paragraph","text":"Главные критерии — свобода движения, отсутствие болезненного давления и возможность подстроить посадку под меняющееся тело."},{"type":"heading","text":"Проверяйте вещь в движении"},{"type":"paragraph","text":"На примерке недостаточно посмотреть на себя стоя. Сядьте, пройдитесь, поднимите руки, немного наклонитесь."},{"type":"paragraph","text":"Обратите внимание:"},{"type":"list-item","text":"не врезается ли пояс, когда вы сидите;"},{"type":"list-item","text":"не тянет ли ткань в паху и по бёдрам;"},{"type":"list-item","text":"не сползает ли вещь при ходьбе;"},{"type":"list-item","text":"не натирают ли швы;"},{"type":"list-item","text":"можете ли вы свободно дышать и двигаться."},{"type":"paragraph","text":"Если одежду приходится постоянно поправлять или хочется снять через десять минут, посадка вам не подходит. Покупать её в расчёте «потом привыкну» обычно невыгодно."},{"type":"heading","text":"Какой пояс удобнее"},{"type":"paragraph","text":"Брюки и легинсы для беременных бывают с поясом под животом и с высокой эластичной вставкой. Медицински обязательного варианта нет."},{"type":"paragraph","text":"Низкий пояс удобен, если не хочется дополнительного слоя ткани на животе. Высокая вставка может лучше удерживать одежду и создавать ощущение мягкой поддержки."},{"type":"paragraph","text":"Важно, чтобы резинка не скручивалась и не давила. Обычная эластичная одежда тоже подходит, если сохраняет комфортную посадку. Само наличие слова «для беременных» на этикетке не делает вещь лучше."},{"type":"heading","text":"Бюстгальтер: ориентируйтесь на текущий размер"},{"type":"paragraph","text":"Грудь может увеличиться раньше живота, поэтому старое бельё иногда становится неудобным уже в первом триместре."},{"type":"paragraph","text":"Подходящая модель:"},{"type":"list-item","text":"вмещает грудь без сдавливания и выпирания по краям;"},{"type":"list-item","text":"поддерживает её без болезненного давления;"},{"type":"list-item","text":"не врезается бретелями в плечи;"},{"type":"list-item","text":"не поднимается на спине;"},{"type":"list-item","text":"имеет запас регулировки."},{"type":"paragraph","text":"Мягкие модели без жёстких элементов часто проще приспособить к изменениям размера. Если каркас давит на ткань груди, бельё нужно заменить."},{"type":"paragraph","text":"Спать в бюстгальтере необязательно. Если без поддержки неприятно, можно выбрать мягкую модель для сна. Покупать заранее много белья для кормления тоже не нужно: размер груди ещё может измениться."},{"type":"heading","text":"Ткани и нижнее бельё"},{"type":"paragraph","text":"Выбирайте материалы, в которых вам не жарко и которые не раздражают кожу. Нижнее бельё должно удобно сидеть под животом или закрывать его — оба варианта возможны."},{"type":"paragraph","text":"Если стали обильнее обычные выделения, полезнее менять влажное бельё, чем выбирать особенно плотную ткань. Ароматизированные средства для белья могут раздражать чувствительную кожу."},{"type":"heading","text":"Как избежать лишних покупок"},{"type":"paragraph","text":"Начните с небольшого набора: удобные брюки, несколько верхов, бельё по размеру и вещь для прогулок. Часть обычного гардероба — рубашки, свободные платья, кардиганы — может служить всю беременность."},{"type":"paragraph","text":"Поддерживающий пояс или бандаж решает другую задачу. При боли в спине или тазу его выбирают индивидуально; он не обязателен только потому, что живот начал расти."}]},{"id":"pregnancy-040","number":40,"week":14,"title":"Можно ли беременным спать на животе","image":null,"blocks":[{"type":"paragraph","text":"На ранних сроках спать на животе обычно можно, если вам удобно. Нет необходимости отказываться от привычной позы сразу после положительного теста или специально контролировать каждое движение во сне."},{"type":"paragraph","text":"По мере роста живота эта поза чаще становится неудобной сама по себе. Тогда разумно подобрать другое положение, не дожидаясь боли."},{"type":"heading","text":"Можно ли так «придавить» малыша"},{"type":"paragraph","text":"Обычное положение во сне на раннем сроке не равнозначно травме живота. Ребёнок находится внутри матки и окружён околоплодными водами."},{"type":"paragraph","text":"На 14-й неделе не существует универсального правила «с сегодняшнего дня лежать на животе нельзя». У одной женщины живот уже заметен и такая поза неприятна, у другой дискомфорта пока нет."},{"type":"paragraph","text":"При этом специально терпеть давление, болезненность груди или напряжение поясницы не нужно. Комфорт помогает выбрать подходящее положение, но цель — хороший сон, а не сохранение старой привычки любой ценой."},{"type":"heading","text":"Как постепенно перейти на бок"},{"type":"paragraph","text":"Начните с простой опоры:"},{"type":"list-item","text":"положите обычную подушку между коленями;"},{"type":"list-item","text":"при необходимости добавьте небольшую подушку под живот;"},{"type":"list-item","text":"обнимите ещё одну подушку, чтобы удобнее расположить плечо и руку."},{"type":"paragraph","text":"Большая подушка для беременных может быть удобной, но обязательной покупки здесь нет. Иногда две небольшие подушки лучше подходят по высоте и занимают меньше места."},{"type":"paragraph","text":"Можно пробовать оба бока. Если болит бедро или затекает плечо, смените сторону и проверьте высоту подушки под головой. Шея не должна сильно сгибаться вверх или проваливаться вниз."},{"type":"heading","text":"Когда положение во сне приобретает особое значение"},{"type":"paragraph","text":"Начиная с 28 недель рекомендуется засыпать на боку — левом или правом. Это относится и к ночному сну, и к дневному отдыху."},{"type":"paragraph","text":"На поздних сроках положение на спине может приводить к сдавлению крупных сосудов увеличенной маткой. Поэтому привычка засыпать на боку полезна, но формировать её можно постепенно."},{"type":"paragraph","text":"Если вы проснулись на спине или животе, не нужно пугаться и пытаться выяснить, сколько времени так пролежали. Просто повернитесь на бок. Контролировать положение тела всю ночь невозможно."},{"type":"heading","text":"Что ещё помогает спать лучше"},{"type":"paragraph","text":"Иногда проблема связана не с позой, а с изжогой, заложенным носом, тревогой или неудобным матрасом. Тогда дополнительные подушки не всегда решают её."},{"type":"paragraph","text":"Попробуйте сохранять регулярное время сна, не планировать большой ужин непосредственно перед отдыхом и сделать спальню комфортной по температуре. Если изжога или боль регулярно будят вас, обсудите лечение с врачом."},{"type":"paragraph","text":"Постоянная бессонница, сильная дневная сонливость, громкий храп с замеченными остановками дыхания тоже заслуживают внимания."},{"type":"paragraph","text":"Удобное положение может меняться несколько раз за беременность. Это обычная причина пересмотреть привычки сна, а не повод искать единственную «правильную» позу на все девять месяцев."}]},{"id":"pregnancy-041","number":41,"week":14,"title":"Пигментация и изменения кожи: нужен ли особенный уход","image":null,"blocks":[{"type":"paragraph","text":"Во время беременности могут темнеть ареолы, появляться тёмная линия на животе и пятна на лице. Эти изменения часто связаны с гормональным влиянием на выработку меланина — пигмента, который определяет цвет кожи."},{"type":"paragraph","text":"Такая пигментация сама по себе обычно не опасна. Она не означает, что вы неправильно питаетесь или обязательно испытываете дефицит витаминов."},{"type":"heading","text":"Почему появляются пятна на лице"},{"type":"paragraph","text":"Пигментацию на щеках, лбу или над верхней губой называют мелазмой. Её выраженность зависит от индивидуальной предрасположенности, гормональных изменений и воздействия света."},{"type":"paragraph","text":"После родов пятна могут постепенно светлеть, но это происходит не у всех и не сразу. Поэтому основная задача во время беременности — защищать кожу и не раздражать её попытками быстрого отбеливания."},{"type":"heading","text":"Самое полезное средство — защита от солнца"},{"type":"paragraph","text":"Выбирайте солнцезащитное средство широкого спектра с SPF не ниже 30. Наносите его на открытые участки кожи, а при длительном пребывании на улице обновляйте примерно каждые два часа, а также после купания или сильного потоотделения."},{"type":"paragraph","text":"Дополняйте крем тенью, головным убором и одеждой. При мелазме могут быть полезны тонированные солнцезащитные средства с оксидами железа: они дополнительно защищают от части видимого света, способного усиливать пигментацию."},{"type":"paragraph","text":"Не обязательно искать продукт только с надписью «для беременных». Важнее подходящая защита, переносимость и возможность пользоваться средством регулярно."},{"type":"heading","text":"Нужен ли полностью новый уход"},{"type":"paragraph","text":"Чаще достаточно простой схемы: мягкое очищение, увлажнение и защита от солнца."},{"type":"paragraph","text":"Если кожа стала чувствительнее, уменьшите количество новых средств. Вводите их по одному, чтобы понимать, что вызывает жжение или покраснение."},{"type":"paragraph","text":"Скрабы, домашние пилинги высокой концентрации, лимонный сок и сода могут раздражать кожу. После раздражения пигментация иногда становится заметнее."},{"type":"paragraph","text":"Ретиноиды, включая косметические средства с ретинолом, во время беременности не используют. Средства с гидрохиноном также лучше отложить. Если пятна сильно беспокоят, дерматолог подберёт допустимый уход; одним из возможных компонентов бывает азелаиновая кислота."},{"type":"heading","text":"Что делать с растяжками"},{"type":"paragraph","text":"Увлажняющие средства помогают уменьшить сухость и ощущение стянутости, но не гарантируют профилактику растяжек. Их появление зависит в том числе от наследственности и особенностей кожи."},{"type":"paragraph","text":"Дорогой крем или масло не обеспечивают защиту только благодаря специальной маркировке. Выбирайте средство по комфорту, а не по обещанию полностью предотвратить изменения."},{"type":"heading","text":"Какие симптомы стоит показать врачу"},{"type":"paragraph","text":"Не любое изменение кожи связано с беременностью. Нужна оценка, если родинка быстро меняет форму или цвет, кровоточит либо заметно отличается от остальных."},{"type":"paragraph","text":"Выраженный зуд, особенно ладоней и стоп и без очевидной сыпи, тоже требует обращения к врачу. Его не стоит просто маскировать кремом."},{"type":"paragraph","text":"Для обычной пигментации спокойный регулярный уход полезнее интенсивных процедур: он помогает сохранить кожный барьер и не добавлять раздражение к естественным изменениям."}]},{"id":"pregnancy-042","number":42,"week":14,"title":"Как сохранить привычную активность во втором триместре","image":null,"blocks":[{"type":"paragraph","text":"Если беременность протекает без осложнений, двигаться во втором триместре полезно. Регулярная активность помогает поддерживать выносливость, настроение и сон, а также снижает вероятность некоторых осложнений, включая гестационный диабет."},{"type":"paragraph","text":"При этом движение не обязано выглядеть как полноценная тренировка. Прогулки, плавание, занятия дома и часть повседневных дел тоже могут быть вкладом в активность."},{"type":"heading","text":"Какой объём считать ориентиром"},{"type":"paragraph","text":"Для большинства беременных без противопоказаний рекомендуют не менее 150 минут умеренной аэробной активности в неделю."},{"type":"paragraph","text":"Можно распределить их по 30 минут на пять дней или разбить занятия на более короткие отрезки. Например, три прогулки по 10 минут иногда вписываются в день легче, чем один длинный выход."},{"type":"paragraph","text":"Если раньше вы почти не двигались или несколько недель пропустили из-за тошноты, начните с небольшого объёма и увеличивайте его постепенно. Не нужно сразу достигать недельной цели."},{"type":"heading","text":"Как понять, что нагрузка умеренная"},{"type":"paragraph","text":"Подойдёт разговорный тест: во время движения вы можете говорить предложениями, хотя дышите чаще, чем в покое."},{"type":"paragraph","text":"Если можете произнести только несколько слов, снизьте темп. Ориентир «пульс не выше 140» не является универсальным правилом для всех беременных: реакция на нагрузку зависит от возраста, тренированности и других факторов."},{"type":"paragraph","text":"Оценивайте не только занятие, но и восстановление. Если после обычной прогулки приходится долго лежать из-за истощения, объём стоит уменьшить и при необходимости обсудить самочувствие с врачом."},{"type":"heading","text":"Что обычно подходит"},{"type":"paragraph","text":"Удобные варианты — ходьба, плавание, велотренажёр, адаптированные силовые упражнения и занятия для беременных у квалифицированного инструктора."},{"type":"paragraph","text":"По мере роста живота меняется равновесие. Поэтому устойчивое положение и контролируемые движения становятся важнее. Упражнение можно упростить: уменьшить вес, сократить амплитуду, добавить опору или сделать больше пауз."},{"type":"paragraph","text":"Избегайте контактных видов спорта, занятий с высоким риском падения, подводного плавания с аквалангом и тренировок в сильной жаре. «Горячая» йога тоже не подходит."},{"type":"heading","text":"Как встроить движение в обычный день"},{"type":"paragraph","text":"Попробуйте выбрать несколько постоянных точек:"},{"type":"list-item","text":"короткая прогулка после завтрака;"},{"type":"list-item","text":"перерывы на движение во время работы;"},{"type":"list-item","text":"спокойное занятие или прогулка вечером."},{"type":"paragraph","text":"В загруженный день достаточно сохранить хотя бы часть привычного объёма. Пропуск тренировки не нужно компенсировать двойной нагрузкой."},{"type":"paragraph","text":"Пейте по потребности, выбирайте удобную одежду и постепенно завершайте занятие, снижая темп."},{"type":"heading","text":"Когда нужно остановиться"},{"type":"paragraph","text":"Прекратите нагрузку и обратитесь за медицинской оценкой при кровянистых выделениях, подтекании жидкости, боли в груди, обмороке, выраженном головокружении, болезненных регулярных сокращениях или необычной одышке."},{"type":"paragraph","text":"Боль в тазу, недержание мочи и ощущение тяжести во влагалище — повод адаптировать упражнения и обсудить симптомы со специалистом."},{"type":"paragraph","text":"Если врач ограничил активность, уточните конкретно: какие движения допустимы, что временно исключить и когда можно пересмотреть рекомендации."}]},{"id":"pregnancy-043","number":43,"week":15,"title":"Какие выделения считаются обычными во время беременности","image":null,"blocks":[{"type":"paragraph","text":"Во время беременности выделений из влагалища часто становится больше. Это связано с гормональными изменениями и усилением кровоснабжения тканей."},{"type":"paragraph","text":"Само увеличение количества выделений не означает инфекцию. Важнее их характер, сопутствующие ощущения и то, насколько резко они изменились."},{"type":"heading","text":"Как обычно выглядят физиологические выделения"},{"type":"paragraph","text":"Чаще они:"},{"type":"list-item","text":"прозрачные или молочно-белые;"},{"type":"list-item","text":"жидкие либо немного слизистые;"},{"type":"list-item","text":"без резкого неприятного запаха;"},{"type":"list-item","text":"не сопровождаются зудом, жжением и болью."},{"type":"paragraph","text":"Количество может различаться в разные дни. После высыхания на белье оттенок иногда немного меняется, поэтому оценивать ситуацию только по цвету сухого следа ненадёжно."},{"type":"paragraph","text":"Если выделения привычные, а неприятных ощущений нет, специальное лечение для их «устранения» обычно не требуется."},{"type":"heading","text":"Какие изменения нужно обсудить с врачом"},{"type":"paragraph","text":"Запишитесь на осмотр, если появились:"},{"type":"list-item","text":"выраженный зуд или жжение;"},{"type":"list-item","text":"неприятный, особенно рыбный запах;"},{"type":"list-item","text":"зелёные, серые или необычно жёлтые выделения;"},{"type":"list-item","text":"творожистая консистенция вместе с раздражением;"},{"type":"list-item","text":"боль при мочеиспускании или половом контакте."},{"type":"paragraph","text":"По внешнему виду нельзя надёжно отличить кандидоз от бактериального вагиноза и других состояний. Иногда нужен осмотр и анализ."},{"type":"paragraph","text":"Не стоит использовать оставшиеся свечи или таблетки от предыдущего эпизода. Во время беременности выбор препарата и способа применения имеет значение, а похожие симптомы могут иметь разные причины."},{"type":"heading","text":"Если появилась кровь"},{"type":"paragraph","text":"Розовые, коричневые или красные выделения требуют связи с медицинским специалистом. Небольшое количество крови иногда связано с чувствительностью шейки матки, например после контакта, но установить причину по переписке или фотографии нельзя."},{"type":"paragraph","text":"При обильном кровотечении, сильной боли, головокружении или обмороке нужна экстренная помощь."},{"type":"paragraph","text":"Даже если выделения быстро прекратились, сообщите о них врачу. При отрицательном резус-факторе напомните об этом: может понадобиться решение о дополнительной профилактике."},{"type":"heading","text":"Если бельё постоянно намокает"},{"type":"paragraph","text":"Водянистая жидкость может оказаться выделениями или мочой, однако исключать подтекание околоплодных вод самостоятельно нельзя."},{"type":"paragraph","text":"Если жидкость вытекает струёй, повторно подтекает или бельё остаётся необычно мокрым, нужна срочная очная оценка. Не ждите очередного планового приёма."},{"type":"paragraph","text":"До осмотра можно использовать обычную прокладку, чтобы заметить количество и цвет жидкости. Не вводите тампон и не полагайтесь только на домашний тест."},{"type":"heading","text":"Как ухаживать за интимной областью"},{"type":"paragraph","text":"Достаточно мягкого наружного подмывания и комфортного белья. Влагалище не нужно промывать изнутри: спринцевания нарушают естественную среду."},{"type":"paragraph","text":"Ароматизированные прокладки, дезодоранты и агрессивные средства могут вызывать раздражение. Ежедневная прокладка необязательна; если используете её, выбирайте вариант без отдушек и меняйте по мере увлажнения."},{"type":"paragraph","text":"Полезнее замечать устойчивые изменения и сопутствующие симптомы, чем проверять выделения много раз в день и пытаться самостоятельно поставить диагноз по оттенку."}]},{"id":"pregnancy-044","number":44,"week":15,"title":"Уход за зубами и дёснами: почему во время беременности они требуют больше внимания","image":null,"blocks":[{"type":"paragraph","text":"Во время беременности дёсны могут стать чувствительнее, отекать и кровоточить при чистке. Гормональные изменения усиливают их реакцию на зубной налёт — так может проявляться гингивит беременных."},{"type":"paragraph","text":"Это распространённая ситуация, но считать кровоточивость неизбежной и просто ждать родов не нужно. Обычно помогают правильная гигиена и стоматологическая помощь."},{"type":"heading","text":"Почему риск проблем увеличивается"},{"type":"paragraph","text":"На состояние полости рта влияет сразу несколько факторов."},{"type":"paragraph","text":"Частые перекусы, особенно сладкие, увеличивают время контакта зубов с веществами, из которых бактерии образуют кислоты. При рвоте эмаль контактирует с желудочной кислотой. А тошнота, усталость и чувствительность к вкусу пасты иногда мешают регулярно чистить зубы."},{"type":"paragraph","text":"Именно эти обстоятельства требуют внимания. Представление, что ребёнок «забирает кальций из зубов», неверно: зубы не служат обычным источником кальция для плода."},{"type":"heading","text":"Базовый уход остаётся простым"},{"type":"paragraph","text":"Чистите зубы дважды в день примерно по две минуты мягкой щёткой и фторсодержащей пастой. Для большинства взрослых подходит паста с содержанием фтора 1350–1500 ppm."},{"type":"paragraph","text":"После чистки сплюньте пасту, не выполаскивая её сразу большим количеством воды. Ежедневно очищайте промежутки между зубами нитью или подходящими межзубными ёршиками."},{"type":"paragraph","text":"Если дёсны кровоточат, не прекращайте гигиену полностью. Чистите бережно и запишитесь к стоматологу: накопление налёта может усиливать воспаление."},{"type":"heading","text":"Если чистка вызывает тошноту"},{"type":"paragraph","text":"Попробуйте щётку с небольшой головкой и пасту с менее выраженным вкусом. Выберите время, когда тошнота обычно слабее, и не торопитесь."},{"type":"paragraph","text":"Иногда легче чистить зубы короткими подходами. Если справиться совсем не удаётся, обсудите временную схему ухода со стоматологом — ополаскиватель не является полноценной заменой щётке."},{"type":"heading","text":"Что делать после рвоты"},{"type":"paragraph","text":"Прополощите рот обычной водой. Не начинайте энергично чистить зубы сразу: кислота временно размягчает поверхность эмали."},{"type":"paragraph","text":"Лучше подождать около часа, затем вернуться к обычной чистке. Если рвота повторяется часто, сообщите и акушеру-гинекологу, и стоматологу: важно одновременно лечить причину и защищать зубы."},{"type":"heading","text":"Нужна ли профессиональная чистка"},{"type":"paragraph","text":"Осмотр и профессиональная гигиена допустимы во время беременности. Необходимое лечение, местная анестезия и диагностические снимки по показаниям тоже возможны — откладывать боль и инфекцию до родов не нужно."},{"type":"paragraph","text":"Сообщите стоматологу срок беременности, особенности её течения и список лекарств. На более поздних сроках можно попросить изменить положение кресла или сделать паузу, если лежать неудобно."},{"type":"heading","text":"Когда обращаться быстрее"},{"type":"paragraph","text":"Не откладывайте визит при зубной боли, припухлости, гнойных выделениях, неприятном вкусе, заметном образовании на десне или стойкой кровоточивости."},{"type":"paragraph","text":"Если отекает лицо, повышается температура, трудно глотать или дышать, нужна срочная помощь."},{"type":"paragraph","text":"Уход за полостью рта во время беременности строится на регулярности: мягкая тщательная чистка и своевременный осмотр полезнее агрессивных процедур и попыток терпеть симптомы."}]},{"id":"pregnancy-045","number":45,"week":15,"title":"Как правильно пользоваться ремнём безопасности в машине","image":null,"blocks":[{"type":"paragraph","text":"Во время беременности ремень безопасности нужен в каждой поездке — за рулём, на переднем пассажирском сиденье и сзади. Это относится и к короткой дороге до магазина или поездке в такси."},{"type":"paragraph","text":"Растущий живот не является причиной ездить непристёгнутой. Важно правильно расположить ремень, чтобы при резком торможении нагрузка приходилась на прочные костные структуры."},{"type":"heading","text":"Как должны проходить лямки"},{"type":"paragraph","text":"Используйте трёхточечный ремень — с поясной и диагональной частями."},{"type":"paragraph","text":"Нижняя лямка проходит низко, под животом, по костям таза и верхней части бёдер. Она не должна лежать поперёк живота."},{"type":"paragraph","text":"Диагональная лямка идёт через середину плеча, между грудями и сбоку от живота. Не убирайте её под руку или за спину: так ремень перестаёт удерживать тело правильно."},{"type":"paragraph","text":"Лента должна лежать ровно, без перекручивания, и достаточно плотно прилегать. После застёгивания мягко уберите лишнюю слабину."},{"type":"paragraph","text":"Если диагональная часть касается шеи, попробуйте изменить высоту верхнего крепления или положение сиденья."},{"type":"heading","text":"Как сесть удобнее"},{"type":"paragraph","text":"Спинка должна оставаться близкой к вертикальному положению. Сильно откидываться и сползать вперёд не стоит: при столкновении тело может сместиться под поясную лямку."},{"type":"paragraph","text":"Толстую верхнюю одежду лучше расстегнуть или снять, чтобы ремень прилегал к телу. Не подкладывайте под него объёмные подушки и не меняйте самостоятельно штатную схему крепления."},{"type":"paragraph","text":"Если ремень регулярно поднимается на живот, проверьте положение таза, наклон спинки и отсутствие лишней слабины. Просто ослаблять его ради удобства — плохое решение."},{"type":"heading","text":"Если вы за рулём"},{"type":"paragraph","text":"Сохраняйте максимально возможное расстояние до руля при условии, что уверенно достаёте до педалей и полностью контролируете автомобиль."},{"type":"paragraph","text":"Ориентир — около 25 сантиметров между грудиной и центром рулевого колеса. При этом живот не должен упираться в руль. Если регулировка позволяет, направьте рулевую колонку в сторону груди."},{"type":"paragraph","text":"Когда удобную и безопасную посадку обеспечить уже трудно, лучше пересесть на пассажирское место."},{"type":"heading","text":"Нужно ли отключать подушку безопасности"},{"type":"paragraph","text":"Беременность сама по себе не является основанием отключать подушку. Ремень и подушка рассчитаны на совместную работу."},{"type":"paragraph","text":"На переднем пассажирском сиденье можно отодвинуть кресло назад, сохраняя нормальное положение тела и правильное прилегание ремня."},{"type":"heading","text":"Что делать после столкновения"},{"type":"paragraph","text":"После ДТП нужна медицинская оценка, даже если внешних повреждений нет и удар кажется небольшим. Некоторые последствия не проявляются сразу."},{"type":"paragraph","text":"Сообщите срок беременности, обстоятельства столкновения и свой резус-фактор, если он отрицательный. При боли, кровянистых выделениях, подтекании жидкости, слабости или обмороке вызывайте экстренную помощь."},{"type":"paragraph","text":"Перед каждой поездкой достаточно короткой проверки: нижняя лямка под животом, диагональная — между грудями, ремень без перекручивания, посадка устойчивая. По мере роста живота привычную настройку стоит пересматривать."}]},{"id":"pregnancy-046","number":46,"week":16,"title":"Когда ждать первые шевеления малыша и почему сроки у всех разные","image":null,"blocks":[{"type":"paragraph","text":"Малыш начинает двигаться задолго до того, как вы сможете это почувствовать. На раннем УЗИ движения уже видны, но ребёнок ещё слишком мал, чтобы каждое из них передавалось как заметный толчок."},{"type":"paragraph","text":"Первые ощущения обычно появляются между 16-й и 24-й неделями. Поэтому на 16-й неделе совершенно нормально пока ничего не чувствовать."},{"type":"heading","text":"Как выглядят первые шевеления"},{"type":"paragraph","text":"Вначале это редко похоже на уверенный пинок. Женщины описывают ощущения как лёгкое трепетание, пузырьки, перекатывание или мягкое прикосновение изнутри."},{"type":"paragraph","text":"Сначала трудно понять, что именно происходит: шевелится ребёнок или работает кишечник. Постепенно ощущения повторяются и становятся узнаваемыми."},{"type":"paragraph","text":"Можно заметить их вечером в покое, а затем несколько дней не быть уверенной, что почувствовали снова. На раннем этапе устойчивого ежедневного рисунка ещё может не быть."},{"type":"heading","text":"Почему сроки различаются"},{"type":"paragraph","text":"При первой беременности движения нередко распознают после 20 недель. При последующих — раньше, потому что ощущение уже знакомо."},{"type":"paragraph","text":"Имеет значение и расположение плаценты. Если она находится по передней стенке матки, часть движений может ощущаться слабее."},{"type":"paragraph","text":"На восприятие влияют положение ребёнка и ваша занятость. Во время активного дня лёгкие движения заметить труднее, чем лёжа или сидя спокойно."},{"type":"paragraph","text":"По сроку первого ощутимого толчка нельзя определить темперамент малыша, его будущую активность или качество вашего контакта с ним."},{"type":"heading","text":"Нужно ли сейчас считать движения"},{"type":"paragraph","text":"На 16-й неделе ежедневный подсчёт обычно не нужен. Для этого срока нет универсальной нормы вроде «десять толчков за вечер»."},{"type":"paragraph","text":"Можно просто замечать новые ощущения без попытки вызвать их специально. Не нужно надавливать на живот, пить очень холодную воду или есть сладкое ради проверки."},{"type":"paragraph","text":"Постепенно вы начнёте узнавать обычную активность именно своего малыша. Позже изменение этого привычного рисунка станет важнее сравнения с чужими подсчётами."},{"type":"heading","text":"Когда обратиться к врачу"},{"type":"paragraph","text":"Если к 24 неделям вы ни разу не почувствовали движений, сообщите специалисту, который ведёт беременность. Он оценит ситуацию и при необходимости назначит обследование."},{"type":"paragraph","text":"Если вы уже регулярно чувствовали малыша, а движения заметно уменьшились, исчезли или изменились непривычным образом, свяжитесь с медицинским учреждением сразу. Не ждите следующего дня или планового приёма."},{"type":"paragraph","text":"Особенно важно не объяснять уменьшение движений тем, что ребёнку «стало тесно»: на более поздних сроках характер движений меняется, но они должны сохраняться."},{"type":"heading","text":"Почему домашний допплер не заменяет осмотр"},{"type":"paragraph","text":"Даже если удалось услышать сердцебиение, это не доказывает, что всё благополучно. Кроме того, без подготовки можно принять за него другой звук."},{"type":"paragraph","text":"На 16-й неделе отсутствие ощутимых шевелений обычно укладывается в нормальные сроки. Ориентируйтесь на план наблюдения и собственную историю ощущений, а не на сообщения о том, что кто-то почувствовал малыша значительно раньше."}]},{"id":"pregnancy-047","number":47,"week":16,"title":"Что происходит на обычном приёме у гинеколога во втором триместре","image":null,"blocks":[{"type":"paragraph","text":"Во втором триместре приём часто выглядит спокойнее, чем первый большой визит: часть обследований уже выполнена, основные сведения собраны. Но регулярные встречи сохраняют важную задачу — замечать изменения в состоянии женщины и развитии беременности."},{"type":"paragraph","text":"Содержание визита зависит от срока, предыдущих результатов и индивидуальных рисков. Одинаковый набор процедур на каждом приёме нужен не всем."},{"type":"heading","text":"Сначала — разговор о самочувствии"},{"type":"paragraph","text":"Врач уточняет, сохраняются ли тошнота и рвота, нет ли боли, кровянистых выделений, неприятных ощущений при мочеиспускании и других жалоб."},{"type":"paragraph","text":"Стоит рассказать и о симптомах, которые кажутся «обычными»: запорах, бессоннице, головной боли, выраженной усталости или тревоге. Многие из них можно облегчить, а иногда требуется дополнительная проверка."},{"type":"paragraph","text":"Сообщите, если начали принимать новый препарат или добавку. Даже средства, купленные без рецепта, лучше включить в общий список."},{"type":"heading","text":"Что измеряют и проверяют"},{"type":"paragraph","text":"На плановых приёмах контролируют артериальное давление. Повышение может не ощущаться, поэтому измерение важно даже при хорошем самочувствии."},{"type":"paragraph","text":"Также оценивают массу тела и её динамику — в соответствии с местным порядком наблюдения и вашей ситуацией. Значение имеет общая тенденция, а не отдельная цифра после плотного завтрака."},{"type":"paragraph","text":"Анализ мочи помогает выявлять изменения, которые требуют внимания, включая белок или признаки инфекции. Когда именно его сдавать, уточняйте по своему плану: назначение исследований может различаться."},{"type":"paragraph","text":"По мере увеличения срока врач оценивает рост матки. Измерение высоты её дна становится более информативным позже, поэтому не стоит ожидать, что на 16-й неделе его обязательно проведут так же, как в конце беременности."},{"type":"heading","text":"Обязательно ли УЗИ и осмотр на кресле"},{"type":"paragraph","text":"УЗИ при каждом посещении обычно не требуется. При отсутствии показаний его проводят в установленные сроки."},{"type":"paragraph","text":"Осмотр на гинекологическом кресле тоже не является обязательной частью каждого визита. Его назначают, когда нужно ответить на конкретный клинический вопрос, например разобраться с болью или необычными выделениями."},{"type":"paragraph","text":"Если процедура непонятна, можно спросить, зачем она нужна и что покажет. Любое обследование должно сопровождаться объяснением и вашим согласием."},{"type":"heading","text":"Какие планы обсуждают сейчас"},{"type":"paragraph","text":"Врач проверяет, получен ли итог первого скрининга и нужны ли дополнительные консультации. Уточняет сроки следующего УЗИ, на котором подробно оценивают анатомию малыша, и других исследований второго триместра."},{"type":"paragraph","text":"Если вы ещё не чувствуете шевелений, это стоит упомянуть, но на 16-й неделе такое отсутствие обычно ожидаемо."},{"type":"heading","text":"Как подготовиться к визиту"},{"type":"paragraph","text":"Запишите три-четыре главных вопроса, возьмите новые результаты и дневник давления, если его ведёте."},{"type":"paragraph","text":"В конце уточните:"},{"type":"list-item","text":"когда следующий приём;"},{"type":"list-item","text":"что нужно сделать до него;"},{"type":"list-item","text":"какие симптомы требуют обращения раньше;"},{"type":"list-item","text":"куда звонить при срочной ситуации."},{"type":"paragraph","text":"Полезный результат визита — не количество назначенных анализов, а понятный план наблюдения и ответы на вопросы, которые влияют на вашу повседневную жизнь."}]},{"id":"pregnancy-048","number":48,"week":16,"title":"Как правильно измерять давление дома и нужно ли вести записи","image":null,"blocks":[{"type":"paragraph","text":"Домашнее измерение давления может дополнять наблюдение во время беременности. Особенно оно полезно, если раньше давление повышалось, результаты в клинике отличаются от домашних или врач назначил регулярный контроль."},{"type":"paragraph","text":"Измерять давление много раз в день всем беременным не требуется. Частоту лучше согласовать со специалистом, а технику — проверить заранее."},{"type":"heading","text":"Какой прибор выбрать"},{"type":"paragraph","text":"Предпочтителен автоматический тонометр с манжетой на плечо, точность которого проверена для использования при беременности, желательно также при преэклампсии."},{"type":"paragraph","text":"Манжета должна соответствовать окружности плеча. Слишком маленькая или большая может искажать результат. «Универсальная» подходит только в пределах размера, указанного производителем."},{"type":"paragraph","text":"Смарт-часы и приложения не заменяют подходящий медицинский тонометр. Прибор можно взять на приём, чтобы проверить технику и сопоставить показания."},{"type":"heading","text":"Как подготовиться"},{"type":"paragraph","text":"За 30 минут до планового измерения избегайте физической нагрузки и кофеина. Сходите в туалет, затем спокойно посидите не менее пяти минут."},{"type":"paragraph","text":"Сядьте на стул со спинкой. Стопы поставьте на пол, ноги не скрещивайте. Руку положите на опору так, чтобы манжета находилась примерно на уровне сердца."},{"type":"paragraph","text":"Манжету надевают на обнажённое плечо. Закатанный тугой рукав не должен сдавливать руку."},{"type":"heading","text":"Как выполнить измерение"},{"type":"paragraph","text":"Во время работы прибора не разговаривайте, не переписывайтесь в телефоне и не двигайтесь."},{"type":"paragraph","text":"Сделайте два измерения с интервалом не менее минуты. Запишите оба результата, если врач не предложил другую схему."},{"type":"paragraph","text":"Для наблюдения используйте одну и ту же руку, выбранную после сравнения показателей на приёме. По возможности измеряйте давление в сопоставимое время."},{"type":"heading","text":"Что сохранять в дневнике"},{"type":"paragraph","text":"Достаточно даты, времени и двух значений давления. Полезно добавить сведения о симптомах и приёме назначенных лекарств."},{"type":"paragraph","text":"Например: «Утро: 118/74 и 116/73, самочувствие обычное». Запись в телефоне подходит не хуже бумажного дневника."},{"type":"paragraph","text":"Не выбирайте только самое низкое значение из серии. И не повторяйте измерение десять раз подряд в надежде получить «правильную» цифру."},{"type":"heading","text":"Какие показатели требуют действий"},{"type":"paragraph","text":"Если верхнее давление 140 и выше или нижнее 90 и выше, спокойно посидите пять минут и измерьте снова. Если повышение сохраняется, свяжитесь с врачом или акушерской службой в тот же день."},{"type":"paragraph","text":"Достаточно повышения одной цифры: например, 145/80 тоже требует внимания."},{"type":"paragraph","text":"При верхнем давлении 160 и выше или нижнем 110 и выше нужна немедленная медицинская оценка. Не откладывайте обращение ради длительных повторных измерений."},{"type":"paragraph","text":"Сильная необычная головная боль, нарушения зрения, боль под рёбрами или в верхней части живота, выраженная одышка требуют срочного обращения, даже если домашнее давление кажется нормальным."},{"type":"heading","text":"Чего не делать самостоятельно"},{"type":"paragraph","text":"Не меняйте дозировки препаратов и не принимайте чужие таблетки. Если лечение уже назначено, попросите врача записать ваши целевые показатели и конкретный порядок действий при отклонениях."},{"type":"paragraph","text":"Дневник нужен, чтобы видеть динамику и принимать решения вместе с врачом. Он дополняет очные приёмы и помогает сделать их информативнее."}]},{"id":"pregnancy-049","number":49,"week":17,"title":"Спина начала уставать: как уменьшить нагрузку без лекарств","image":null,"blocks":[{"type":"paragraph","text":"К вечеру тянет поясницу, хочется чаще присесть, а стоять у плиты становится неудобно? Во время беременности меняются распределение нагрузки и работа мышц, поддерживающих позвоночник. Связки также становятся более податливыми. Дискомфорт может появиться ещё до того, как живот станет большим."},{"type":"paragraph","text":"При обычной мышечной усталости помогают небольшие изменения в течение дня."},{"type":"heading","text":"Чаще меняйте положение"},{"type":"paragraph","text":"Долго сидеть так же утомительно для спины, как долго стоять. Во время работы за столом регулярно вставайте и немного ходите. Можно поставить напоминание каждые 30 минут: это удобный ориентир, а не строгая медицинская норма."},{"type":"paragraph","text":"Сидя, опирайтесь спиной на спинку стула, ставьте стопы на пол или подставку. Небольшая подушка под поясницей может сделать положение комфортнее. Не нужно весь день удерживать спину напряжённо прямой."},{"type":"heading","text":"Сохраняйте посильную активность"},{"type":"paragraph","text":"При беременности без противопоказаний полезны прогулки, плавание и адаптированные упражнения. Начинайте с комфортной нагрузки и прекращайте движение, которое усиливает боль. Длительный постельный режим без назначения врача обычно не помогает восстановить нормальную работу мышц."},{"type":"heading","text":"Разгружайте спину во время отдыха"},{"type":"paragraph","text":"Попробуйте лежать на боку с подушкой между коленями. Если животу нужна поддержка, положите под него небольшую мягкую подушку. Иногда облегчение дают тёплый душ и мягкий массаж мышц спины без болезненного давления."},{"type":"paragraph","text":"Выбирайте устойчивую обувь и распределяйте покупки между двумя лёгкими сумками. Тяжёлые пакеты лучше передать помощнику."},{"type":"heading","text":"Когда нужен врач"},{"type":"paragraph","text":"Запишитесь на осмотр, если боль повторяется, мешает ходить или спать. Врач оценит её причину и при необходимости направит к специалисту по лечебной физкультуре."},{"type":"paragraph","text":"Сильная или нарастающая боль, особенно вместе с температурой, болезненным мочеиспусканием, кровянистыми выделениями, подтеканием жидкости или схваткообразными ощущениями, требует срочной оценки. При онемении промежности, слабости в ногах или нарушении контроля мочеиспускания нужна неотложная помощь."}]},{"id":"pregnancy-050","number":50,"week":17,"title":"Бандаж для беременных: нужен ли он каждой женщине","image":null,"blocks":[{"type":"paragraph","text":"Бандаж не входит в список обязательных покупок для беременности. Если вам удобно ходить, стоять и заниматься повседневными делами, начинать носить его только из-за срока или размера живота не требуется."},{"type":"paragraph","text":"Поддерживающий пояс может быть полезен при боли в пояснице или тазовом поясе — например, в области лобка. Но сначала важно понять, откуда возникает боль."},{"type":"heading","text":"Какую задачу решает бандаж"},{"type":"paragraph","text":"Мягкий пояс создаёт дополнительную поддержку и у некоторых женщин уменьшает дискомфорт во время движения. Это один из возможных способов помощи наряду с изменением нагрузки и индивидуально подобранными упражнениями."},{"type":"paragraph","text":"При этом убедительных оснований обещать, что обычный дородовый бандаж предотвратит растяжки, преждевременные роды или «удержит» шейку матки, нет. Он не заменяет лечение акушерских осложнений."},{"type":"heading","text":"Как выбрать подходящий"},{"type":"paragraph","text":"Разные модели решают разные задачи. Широкая поддержка живота и низкий тазовый пояс — не одно и то же. При боли в лобке особенно важно, чтобы специалист показал, где именно должен располагаться пояс."},{"type":"paragraph","text":"На примерке попробуйте пройтись, сесть и встать. Подходящая модель:"},{"type":"list-item","text":"уменьшает привычный дискомфорт;"},{"type":"list-item","text":"не сдавливает живот и не затрудняет дыхание;"},{"type":"list-item","text":"не натирает и не вызывает онемения;"},{"type":"list-item","text":"остаётся на месте при движении."},{"type":"paragraph","text":"Размер выбирают по измерениям и таблице производителя, а не только по сроку беременности."},{"type":"heading","text":"Как носить"},{"type":"paragraph","text":"Режим зависит от модели, симптомов и рекомендаций специалиста. Часто пояс используют во время нагрузки, которая вызывает боль, например на прогулке. Носить его постоянно и спать в нём без отдельной рекомендации не нужно."},{"type":"paragraph","text":"Если после надевания стало больнее, появилась выраженная стянутость или раздражение кожи, снимите пояс. Отсутствие эффекта — повод пересмотреть подбор и причину боли, а не затянуть бандаж сильнее."}]},{"id":"pregnancy-051","number":51,"week":17,"title":"Как правильно вставать, садиться и поднимать вещи с растущим животом","image":null,"blocks":[{"type":"paragraph","text":"По мере роста живота привычные движения могут становиться неудобными. Полезно освоить несколько приёмов, которые уменьшают нагрузку на поясницу и помогают сохранять равновесие."},{"type":"heading","text":"Как вставать с кровати"},{"type":"paragraph","text":"Повернитесь на бок, слегка согните колени. Опустите ноги за край кровати и одновременно приподнимите корпус, отталкиваясь руками. Несколько секунд посидите, затем встаньте."},{"type":"paragraph","text":"Так обычно удобнее, чем резко поднимать туловище из положения на спине. Если закружилась голова, не продолжайте вставать: останьтесь сидеть или лягте на бок."},{"type":"heading","text":"Как садиться и вставать со стула"},{"type":"paragraph","text":"Подойдите достаточно близко, чтобы чувствовать сиденье позади ног. Сгибайте колени и опускайтесь плавно, при необходимости держась за подлокотники."},{"type":"paragraph","text":"Чтобы встать, переместитесь ближе к краю, поставьте стопы под колени, немного наклоните корпус вперёд и поднимитесь с опорой на ноги и руки. Низкие мягкие кресла могут быть неудобны: из них труднее выбираться."},{"type":"heading","text":"Как поднять вещь с пола"},{"type":"paragraph","text":"Подойдите к предмету вплотную. Согните колени и тазобедренные суставы, сохраняя спину в удобном положении. Возьмите предмет и держите его ближе к телу. Поднимайтесь плавно, без рывка и задержки дыхания."},{"type":"paragraph","text":"Чтобы повернуться с предметом, переставляйте стопы, а не скручивайте туловище."},{"type":"heading","text":"Сколько можно поднимать"},{"type":"paragraph","text":"Единой безопасной цифры в килограммах для всех беременных нет. Значение имеют состояние здоровья, привычная нагрузка, частота подъёмов, высота и удобство захвата."},{"type":"paragraph","text":"Если приходится натуживаться, терять равновесие или прижимать предмет к животу, попросите помощи. Объёмная коробка может быть неудобнее небольшой вещи того же веса."},{"type":"paragraph","text":"При боли в лобке старайтесь избегать широкой постановки ног и асимметричной нагрузки. Обуваться и одеваться удобнее сидя. Движения, которые регулярно вызывают боль, стоит обсудить с врачом."}]},{"id":"pregnancy-052","number":52,"week":18,"title":"Второй скрининг: как подготовиться и что будет смотреть врач","image":null,"blocks":[{"type":"paragraph","text":"Второй скрининг — подробное ультразвуковое исследование, на котором врач оценивает строение органов малыша и особенности течения беременности. Его главная задача — выявить возможные нарушения развития и определить, нужны ли дополнительные обследования."},{"type":"paragraph","text":"В российских клинических рекомендациях для скринингового УЗИ второго триместра указан срок 18–20 недель и 6 дней. Запишитесь заранее и уточните дату по своему акушерскому сроку."},{"type":"heading","text":"Что проверяют на УЗИ"},{"type":"paragraph","text":"Врач оценивает:"},{"type":"list-item","text":"размеры головы, живота и длинных костей;"},{"type":"list-item","text":"головной мозг, лицо и позвоночник;"},{"type":"list-item","text":"строение сердца;"},{"type":"list-item","text":"органы грудной клетки и брюшной полости, почки и мочевой пузырь;"},{"type":"list-item","text":"конечности;"},{"type":"list-item","text":"расположение и особенности плаценты, количество околоплодных вод."},{"type":"paragraph","text":"Также оценивают длину шейки матки. Для более точного измерения может понадобиться трансвагинальное УЗИ. Исследование кровотока назначают с учётом клинической ситуации."},{"type":"heading","text":"Как подготовиться"},{"type":"paragraph","text":"Для самого УЗИ обычно не нужны голодание или специальная диета. Необходимость наполнить мочевой пузырь уточните в клинике: она зависит от способа исследования."},{"type":"paragraph","text":"Возьмите результаты предыдущих УЗИ и скрининга первого триместра. Наденьте одежду, в которой легко открыть живот. Если хотите узнать пол ребёнка или, наоборот, сохранить его в тайне, скажите об этом заранее."},{"type":"heading","text":"Если исследование затянулось"},{"type":"paragraph","text":"Малыш может лежать так, что отдельные структуры плохо видны. Врач предложит изменить положение, немного пройтись или прийти повторно. Само по себе это не означает, что обнаружена проблема."},{"type":"heading","text":"Что важно знать о результате"},{"type":"paragraph","text":"УЗИ не исключает абсолютно все заболевания и генетические нарушения. Если врач видит особенность, требующую уточнения, следующим шагом могут стать экспертное УЗИ, консультация генетика или другие исследования."},{"type":"paragraph","text":"Перед уходом спросите: всё ли удалось осмотреть, нужны ли дополнительные обследования и когда показать заключение акушеру-гинекологу."}]},{"id":"pregnancy-053","number":53,"week":18,"title":"Плацента: зачем врач указывает её расположение в заключении УЗИ","image":null,"blocks":[{"type":"paragraph","text":"Плацента обеспечивает обмен между организмом мамы и ребёнка: через неё малыш получает кислород и питательные вещества, а продукты обмена поступают в организм матери для выведения. Кроме того, плацента вырабатывает гормоны, поддерживающие беременность."},{"type":"paragraph","text":"В заключении УЗИ врач описывает, к какой стенке матки она прикреплена и насколько близко расположена к внутреннему зеву — выходу из полости матки в канал шейки."},{"type":"heading","text":"Передняя или задняя стенка: есть ли разница"},{"type":"paragraph","text":"Плацента по передней, задней или боковой стенке может быть вариантом нормального расположения. Сама по себе запись «по передней стенке» не означает осложнение и не определяет способ родов."},{"type":"paragraph","text":"Передняя плацента иногда смягчает ощущение первых толчков: она находится между малышом и передней стенкой живота. Поэтому движения могут стать заметны несколько позже."},{"type":"heading","text":"Что означает низкое расположение"},{"type":"paragraph","text":"Врач оценивает расстояние от края плаценты до внутреннего зева. Если плацента находится близко к нему, говорят о низком расположении; если перекрывает его — о предлежании."},{"type":"paragraph","text":"Этот результат важен для наблюдения, поскольку низко расположенная плацента может сопровождаться кровотечением. Но заключение в середине беременности ещё не определяет окончательный план родов."},{"type":"paragraph","text":"По мере роста матки расстояние до её выхода часто увеличивается. Плацента при этом не открепляется и не «ползёт»: меняются размеры и форма матки. Для контроля врач назначает повторное УЗИ."},{"type":"heading","text":"Что делать после такого заключения"},{"type":"paragraph","text":"Уточните, когда нужен контроль и есть ли ограничения именно в вашей ситуации. Упражнения, специальные позы и бандаж не способны «поднять» плаценту."},{"type":"paragraph","text":"Если раньше было кесарево сечение, обязательно сообщите об этом врачу УЗИ: расположение плаценты относительно рубца требует дополнительного внимания."},{"type":"paragraph","text":"При любых кровянистых выделениях нужна срочная медицинская оценка. При обильном кровотечении, слабости или головокружении вызывайте скорую помощь."}]},{"id":"pregnancy-054","number":54,"week":18,"title":"Можно ли узнать пол малыша точно и почему на УЗИ иногда ошибаются","image":null,"blocks":[{"type":"paragraph","text":"Во время второго скрининга врач нередко уже может предположить пол ребёнка по строению наружных половых органов. Но даже на этом сроке УЗИ не даёт стопроцентной гарантии."},{"type":"paragraph","text":"Важно помнить: определение пола — дополнительная возможность исследования. Основное время врач уделяет органам малыша, его росту и плаценте."},{"type":"heading","text":"От чего зависит точность"},{"type":"paragraph","text":"Большое значение имеет положение ребёнка. Если ножки сомкнуты или нужная область закрыта, получить надёжное изображение бывает трудно. Обзору также могут мешать движения малыша, пуповина и особенности прохождения ультразвука через ткани."},{"type":"paragraph","text":"На результат влияют срок беременности, качество изображения и опыт специалиста. Поэтому ответ «пока не могу уверенно сказать» — корректная профессиональная позиция."},{"type":"heading","text":"Почему предположение может измениться"},{"type":"paragraph","text":"УЗИ показывает органы под определённым углом. При неудобном ракурсе часть изображения можно истолковать неверно. Особенно осторожно нужно относиться к предположению, сделанному в первом триместре: наружные половые органы тогда различить сложнее."},{"type":"paragraph","text":"По одному сохранённому кадру самостоятельно перепроверить вывод врача обычно нельзя. Во время исследования специалист оценивает несколько проекций и движение в реальном времени."},{"type":"heading","text":"Нужно ли повторять УЗИ только ради пола"},{"type":"paragraph","text":"Обычно нет необходимости продлевать медицинское исследование или назначать дополнительное исключительно ради этого ответа. Можно вернуться к вопросу на следующем УЗИ, если оно предусмотрено планом наблюдения."},{"type":"heading","text":"А анализ крови точнее?"},{"type":"paragraph","text":"Некоторые варианты неинвазивного пренатального тестирования могут оценивать наличие материала Y-хромосомы. Но НИПТ — прежде всего скрининг хромосомных нарушений, а не обязательный анализ для определения пола."},{"type":"paragraph","text":"Если результаты разных исследований расходятся, обсудите их с врачом. Причиной может быть техническая ошибка, но иногда требуется дополнительная оценка. По переписке или фотографии УЗИ установить причину невозможно."}]},{"id":"pregnancy-055","number":55,"week":19,"title":"Первые шевеления: на что они похожи и почему их легко перепутать","image":null,"blocks":[{"type":"paragraph","text":"Первые движения малыша часто совсем не похожи на отчётливые пинки. Это могут быть лёгкое трепетание, перекаты, короткие касания или ощущение, будто внутри лопнул маленький пузырёк."},{"type":"paragraph","text":"Ребёнок двигается уже давно, но раньше его движения были слишком слабыми, чтобы вы могли их почувствовать."},{"type":"heading","text":"Когда обычно появляются ощущения"},{"type":"paragraph","text":"Большинство женщин замечают первые шевеления между 16-й и 24-й неделями. При первой беременности это нередко происходит после 20 недель. Если вы уже были беременны, знакомые ощущения иногда удаётся распознать раньше."},{"type":"paragraph","text":"На восприятие влияет расположение плаценты. Если она находится по передней стенке, движения могут ощущаться менее отчётливо. Во время ходьбы и повседневных дел слабые толчки также легче пропустить."},{"type":"paragraph","text":"Поэтому отсутствие уверенных шевелений на 19-й неделе само по себе ещё не означает проблему."},{"type":"heading","text":"Как отличить шевеления от работы кишечника"},{"type":"paragraph","text":"Надёжного домашнего теста нет. Вначале ощущения действительно похожи. Постепенно движения становятся отчётливее и узнаваемее: вы начинаете замечать повторяющиеся касания и толчки."},{"type":"paragraph","text":"Можно спокойно посидеть или полежать на боку и прислушаться к ощущениям. Специально голодать, есть сладкое или нажимать на живот, чтобы «разбудить» малыша, не нужно."},{"type":"heading","text":"Нужно ли уже считать толчки"},{"type":"paragraph","text":"На этом сроке регулярный индивидуальный ритм ещё может не сформироваться. Требовать определённого числа движений за час или ежедневно заполнять таблицу по собственной инициативе не требуется."},{"type":"paragraph","text":"Позже важнее будет замечать привычный характер активности ребёнка и его изменения, а не сравнивать малыша с чужими нормами."},{"type":"heading","text":"Когда обратиться за помощью"},{"type":"paragraph","text":"Если к 24 неделям вы ни разу не почувствовали движений, сообщите врачу."},{"type":"paragraph","text":"Если уже знакомая активность заметно уменьшилась или прекратилась, свяжитесь с медицинским специалистом сразу — не ждите следующего приёма. Домашний допплер не позволяет убедиться, что с ребёнком всё благополучно."}]},{"id":"pregnancy-056","number":56,"week":19,"title":"Железо во время беременности: всем ли нужны препараты","image":null,"blocks":[{"type":"paragraph","text":"Железо необходимо для образования гемоглобина — белка, который переносит кислород. Во время беременности увеличивается объём крови, растут ребёнок и плацента, поэтому потребность в железе повышается."},{"type":"paragraph","text":"Но повышенная потребность, дефицит железа и анемия — разные состояния. Именно поэтому назначение препарата должно иметь понятную цель."},{"type":"heading","text":"Почему рекомендации могут различаться"},{"type":"paragraph","text":"ВОЗ рекомендует ежедневный профилактический приём железа с фолиевой кислотой беременным как меру общественного здравоохранения."},{"type":"paragraph","text":"Российские клинические рекомендации «Нормальная беременность» не предусматривают рутинного назначения железа всем женщинам при нормальном гемоглобине. Профилактику рассматривают с учётом риска дефицита, а при подтверждённой железодефицитной анемии назначают лечение."},{"type":"paragraph","text":"Поэтому препараты нужны не только при уже развившейся анемии, но и не должны приниматься в лечебной дозе «на всякий случай»."},{"type":"heading","text":"Как понять, хватает ли железа"},{"type":"paragraph","text":"Общий анализ крови показывает уровень гемоглобина и характеристики эритроцитов. При подозрении на истощение запасов врач может назначить ферритин."},{"type":"paragraph","text":"Нормальный гемоглобин не всегда исключает дефицит железа. При этом ферритин оценивают вместе с другими данными: на него может влиять воспаление."},{"type":"paragraph","text":"Усталость, одышка и сердцебиение не позволяют поставить диагноз самостоятельно. Такие жалобы важно обсудить с врачом."},{"type":"heading","text":"Можно ли восстановить железо только едой"},{"type":"paragraph","text":"Мясо, птица, рыба, бобовые и другие продукты с железом полезны для полноценного питания. Однако подтверждённую железодефицитную анемию обычно нельзя устранить только рационом. Гранатовый сок, яблоки и гречка не заменяют назначенное лечение."},{"type":"heading","text":"Если препарат уже назначен"},{"type":"paragraph","text":"Уточните дозу, длительность курса и дату контрольного анализа. Покажите врачу состав витаминов, чтобы не дублировать железо."},{"type":"paragraph","text":"Тошнота или запор — повод обсудить переносимость и схему приёма. Не увеличивайте дозу самостоятельно и не прекращайте лечение только потому, что самочувствие улучшилось: восстановление запасов может занять больше времени."}]},{"id":"pregnancy-057","number":57,"week":19,"title":"Судороги в ногах: как сделать ночной сон комфортнее","image":null,"blocks":[{"type":"paragraph","text":"Ночная судорога — внезапное болезненное сокращение мышцы, чаще икроножной. Нога словно «каменеет», а стопу бывает трудно расслабить. После приступа некоторое время может сохраняться болезненность."},{"type":"paragraph","text":"Во время беременности судороги встречаются часто. Их причины не всегда удаётся точно установить, поэтому считать каждый приступ признаком нехватки магния неправильно."},{"type":"heading","text":"Что делать во время судороги"},{"type":"paragraph","text":"Если свело икру, осторожно выпрямите ногу и потяните носок стопы на себя, в сторону голени. Двигайтесь плавно, без рывков."},{"type":"paragraph","text":"После ослабления спазма можно слегка помассировать мышцу. Если чувствуете себя устойчиво, осторожно встаньте с опорой и немного походите. Сразу вскакивать с кровати не стоит: боль и сонливость увеличивают риск падения."},{"type":"heading","text":"Что можно попробовать перед сном"},{"type":"list-item","text":"Несколько раз плавно согните и разогните стопы, сделайте круговые движения."},{"type":"list-item","text":"Мягко растяните икроножные мышцы, не доводя до боли."},{"type":"list-item","text":"После дня на ногах дайте себе время на отдых."},{"type":"list-item","text":"В течение дня чередуйте сидение, ходьбу и стояние."},{"type":"list-item","text":"Пейте регулярно, ориентируясь на жажду и рекомендации врача."},{"type":"paragraph","text":"Эти меры могут облегчить состояние, но не гарантируют полного исчезновения судорог."},{"type":"heading","text":"Нужно ли принимать магний или кальций"},{"type":"paragraph","text":"Самостоятельно начинать добавки не стоит. Исследования их эффективности при судорогах беременных дают неоднозначные результаты. Врач учитывает питание, уже принимаемые препараты, сопутствующие заболевания и частоту приступов."},{"type":"paragraph","text":"Если судороги регулярно нарушают сон, расскажите, как часто они возникают, сколько длятся и есть ли симптомы днём."},{"type":"heading","text":"Когда это может быть не судорога"},{"type":"paragraph","text":"Постоянная боль в одной ноге, особенно вместе с отёком, покраснением или ощущением жара, требует срочного осмотра для исключения тромбоза. Такую ногу не нужно интенсивно массировать."},{"type":"paragraph","text":"При внезапной одышке, боли в груди или обмороке вызывайте скорую помощь."}]},{"id":"pregnancy-058","number":58,"week":20,"title":"Половина беременности позади: что стоит сделать уже сейчас","image":null,"blocks":[{"type":"paragraph","text":"20 недель — условная середина беременности. Предполагаемая дата родов остаётся ориентиром, а сейчас удобно проверить, что основные обследования запланированы и у вас есть понятный план на ближайшие месяцы."},{"type":"heading","text":"1. Пройдите второй скрининг и обсудите результат"},{"type":"paragraph","text":"Если УЗИ ещё впереди, проверьте дату записи. После исследования покажите заключение акушеру-гинекологу. Уточните, всё ли удалось осмотреть, нужна ли повторная оценка и есть ли особенности расположения плаценты или длины шейки матки."},{"type":"paragraph","text":"Даже понятное на первый взгляд заключение лучше обсуждать целиком, вместе с результатами предыдущих обследований."},{"type":"heading","text":"2. Уточните ближайшие анализы"},{"type":"paragraph","text":"Спросите, когда нужен общий анализ крови во втором триместре. Он помогает своевременно обнаружить анемию."},{"type":"paragraph","text":"Заранее обсудите обследование на гестационный диабет. Если нарушения углеводного обмена ранее не выявлены, пероральный глюкозотолерантный тест обычно проводят в 24–28 недель. Хорошее самочувствие не позволяет исключить это состояние."},{"type":"heading","text":"3. Проверьте план при отрицательном резус-факторе"},{"type":"paragraph","text":"Уточните необходимость контроля антирезусных антител и дальнейшей профилактики. Тактика зависит от результатов обследования и резус-принадлежности ребёнка, если она установлена."},{"type":"heading","text":"4. Пересмотрите повседневную нагрузку"},{"type":"paragraph","text":"Если нет противопоказаний, сохраняйте регулярную посильную активность. Начинайте постепенно, если раньше мало двигались. Боль, выраженная одышка, головокружение или кровянистые выделения — повод остановиться и обратиться за медицинской оценкой."},{"type":"heading","text":"5. Подготовьте контакты для срочной связи"},{"type":"paragraph","text":"Сохраните номер женской консультации и уточните, куда обращаться вечером или в выходной. Кровотечение, подтекание жидкости, сильная боль, выраженная головная боль или нарушения зрения не должны ждать планового приёма."},{"type":"heading","text":"6. Начните обсуждать помощь после родов"},{"type":"paragraph","text":"Кто возьмёт на себя покупки, еду и часть домашних дел? Кто сможет сопровождать вас на приём или побыть рядом после выписки? Такие договорённости полезно делать заранее, пока есть время спокойно обсудить ожидания."}]},{"id":"pregnancy-059","number":59,"week":20,"title":"Зачем беременной измеряют давление практически на каждом приёме","image":null,"blocks":[{"type":"paragraph","text":"Артериальное давление помогает врачу вовремя заметить состояния, которые могут протекать без явных симптомов. Поэтому в российских рекомендациях его измерение предусмотрено при первом и каждом последующем визите."},{"type":"paragraph","text":"Хорошее самочувствие не гарантирует нормального давления: головная боль и другие жалобы появляются далеко не всегда."},{"type":"heading","text":"Почему особенно важен срок после 20 недель"},{"type":"paragraph","text":"Во второй половине беременности может впервые возникнуть гестационная гипертензия — повышение давления, связанное с беременностью."},{"type":"paragraph","text":"Другое возможное осложнение — преэклампсия. При ней повышенное давление сочетается с белком в моче и/или признаками нарушения работы органов. Это состояние может влиять на здоровье женщины и ребёнка, поэтому требует своевременной оценки."},{"type":"paragraph","text":"Одного измерения недостаточно, чтобы самостоятельно поставить диагноз. Но высокое значение нельзя игнорировать."},{"type":"heading","text":"Какие цифры требуют действий"},{"type":"paragraph","text":"Если верхнее давление составляет 140 мм рт. ст. или выше, либо нижнее — 90 или выше, свяжитесь с врачом в тот же день. Достаточно повышения одного показателя. При хорошем самочувствии спокойно посидите и повторите измерение, сохранив оба результата."},{"type":"paragraph","text":"Если верхнее давление достигло 160, либо нижнее — 110, нужна неотложная медицинская помощь. Не ждите, пока появятся жалобы или давление снизится само."},{"type":"heading","text":"Как измерять дома"},{"type":"paragraph","text":"Используйте плечевой тонометр, подходящий для беременных, и манжету нужного размера. Перед измерением спокойно посидите около пяти минут. Спина должна иметь опору, стопы — стоять на полу, рука — лежать на уровне сердца. Во время измерения не разговаривайте."},{"type":"paragraph","text":"Не каждой женщине нужен ежедневный дневник: частоту контроля определяет врач."},{"type":"heading","text":"Какие симптомы нельзя откладывать"},{"type":"paragraph","text":"Сильная или необычная головная боль, «мушки» и затуманивание зрения, боль под рёбрами или в верхней части живота, внезапный выраженный отёк лица и рук требуют срочного обращения — даже если домашний тонометр показывает привычные цифры."},{"type":"paragraph","text":"Не принимайте чужие препараты от давления и не меняйте назначенную схему самостоятельно."}]},{"id":"pregnancy-060","number":60,"week":20,"title":"Почему 20 недель — хорошее время начинать подготовку к родам","image":null,"blocks":[{"type":"paragraph","text":"У подготовки к родам нет единственной правильной даты начала. Но середина беременности удобна: до рождения малыша ещё достаточно времени, чтобы постепенно разобраться в процессе, задать вопросы врачу и освоить простые навыки."},{"type":"paragraph","text":"Российские рекомендации советуют посещать занятия для будущих родителей со второй половины беременности."},{"type":"heading","text":"Начните с понимания процесса"},{"type":"paragraph","text":"Разберитесь, какие бывают периоды родов, что происходит во время схваток, потуг и рождения плаценты. Отдельно изучите признаки, при которых нужно связаться с роддомом: отхождение вод, кровянистые выделения, изменение шевелений и другие ситуации, обозначенные вашим врачом."},{"type":"paragraph","text":"Конкретный план обращения зависит от срока, расстояния до роддома и особенностей беременности."},{"type":"heading","text":"Постепенно осваивайте способы справляться с напряжением"},{"type":"paragraph","text":"Можно практиковать спокойное дыхание без длительных задержек и расслабление плеч, лица и кистей. Полезно познакомиться с удобными положениями тела и способами поддержки партнёром."},{"type":"paragraph","text":"Не нужно тренировать потуги, натуживаться или пытаться стимулировать роды. Если во время дыхательной практики кружится голова, прекратите упражнение и вернитесь к обычному дыханию."},{"type":"heading","text":"Изучите варианты помощи"},{"type":"paragraph","text":"Хорошая подготовка включает и немедикаментозные способы облегчения боли, и информацию об обезболивании, стимуляции родов и кесаревом сечении. Знание возможных вариантов помогает обсуждать решения с командой, если обстоятельства изменятся."},{"type":"paragraph","text":"Вопросы можно записывать заранее: «Зачем это предлагают?», «Какие есть альтернативы?», «Насколько срочно нужно принять решение?»"},{"type":"heading","text":"Подготовьтесь к первым дням после рождения"},{"type":"paragraph","text":"Включите в программу восстановление женщины, кормление, уход за ребёнком и организацию помощи дома. Роды — только часть перехода к родительству."},{"type":"heading","text":"Как выбрать полезное обучение"},{"type":"paragraph","text":"Ищите программу с квалифицированными специалистами, понятными объяснениями и опорой на медицинские рекомендации. Обещания гарантировать роды без боли, разрывов или вмешательств недостоверны."},{"type":"paragraph","text":"Задача подготовки — дать вам знания и практические навыки. Если потребуется обезболивание или операция, это не означает, что вы подготовились недостаточно."}]},{"id":"pregnancy-061","number":61,"week":21,"title":"Как подобрать удобную позу для сна с растущим животом","image":null,"blocks":[{"type":"paragraph","text":"Привычная поза стала неудобной, живот мешает повернуться, а утром тянет поясницу? По мере роста матки меняется распределение нагрузки, поэтому положение для сна приходится подбирать заново. Главные ориентиры — комфорт, свободное дыхание и отсутствие боли."},{"type":"heading","text":"На каком боку лучше спать"},{"type":"paragraph","text":"Можно спать и на левом, и на правом боку. Обязательного правила «всю ночь только слева» нет. Менять стороны нормально: так проще уменьшить давление на плечо и бедро."},{"type":"paragraph","text":"С 28 недель рекомендуется засыпать на боку — в том числе во время дневного сна. На 21-й неделе можно постепенно привыкать к такому положению, если оно уже стало удобнее остальных."},{"type":"paragraph","text":"Если ночью вы проснулись на спине, не нужно пугаться или пытаться определить, сколько времени так пролежали. Просто повернитесь на бок и продолжайте спать. Контролировать положение тела каждую минуту невозможно, и ставить для этого будильник не требуется."},{"type":"heading","text":"Как устроиться удобнее"},{"type":"paragraph","text":"Лягте на бок и слегка согните ноги. Попробуйте несколько вариантов поддержки:"},{"type":"list-item","text":"подушка между коленями помогает уменьшить перекос таза;"},{"type":"list-item","text":"небольшая мягкая подушка под животом может снизить ощущение натяжения;"},{"type":"list-item","text":"подушка за спиной создаёт дополнительную опору;"},{"type":"list-item","text":"подушка под головой должна поддерживать шею без сильного наклона вверх или вниз."},{"type":"paragraph","text":"Не обязательно использовать всё сразу. Начните с одной опоры и оцените, стало ли комфортнее. Слишком высокая подушка между ногами тоже может мешать: колено не должно подниматься настолько, чтобы таз заметно разворачивался."},{"type":"heading","text":"Почему на спине иногда становится плохо"},{"type":"paragraph","text":"Во второй половине беременности увеличенная матка в положении на спине может сдавливать крупные сосуды и уменьшать возврат крови к сердцу. У некоторых женщин появляются слабость, тошнота, головокружение или ощущение нехватки воздуха."},{"type":"paragraph","text":"Если такое произошло, повернитесь на бок. Если самочувствие быстро не восстанавливается, нужна медицинская помощь."},{"type":"heading","text":"Если мешает изжога"},{"type":"paragraph","text":"Попробуйте приподнять верхнюю часть туловища, а не только голову. Для этого удобнее клиновидная опора или приподнятое изголовье. Большая стопка подушек, которая сгибает шею и сдавливает живот, может сделать положение менее комфортным."},{"type":"heading","text":"Когда дело не только в позе"},{"type":"paragraph","text":"Боль, которая будит ночью, усиливается при переворотах или мешает ходить днём, стоит обсудить с врачом. Иногда требуется помощь при боли в тазовом поясе, а одной перестановки подушек недостаточно."}]},{"id":"pregnancy-062","number":62,"week":21,"title":"Тазовое дно во время беременности: почему важно не только укреплять, но и расслаблять","image":null,"blocks":[{"type":"paragraph","text":"Тазовое дно — группа мышц и соединительных тканей в нижней части таза. Оно поддерживает мочевой пузырь, матку и кишечник, участвует в удержании мочи и газов. Для нормальной работы эти мышцы должны уметь и сокращаться, и полностью отпускать напряжение."},{"type":"paragraph","text":"Поэтому полезная тренировка — это не бесконечные сжатия и не попытка весь день «держать всё подтянутым»."},{"type":"heading","text":"Зачем нужно укрепление"},{"type":"paragraph","text":"Во время беременности нагрузка на тазовое дно увеличивается. Правильно выполняемые упражнения помогают предупреждать и уменьшать подтекание мочи, например при кашле или чихании."},{"type":"paragraph","text":"Но подтекание не всегда означает только слабость мышц. Значение имеют их координация, способность расслабляться и состояние окружающих тканей. Если симптомы уже появились, лучше подобрать программу со специалистом."},{"type":"heading","text":"Зачем нужно расслабление"},{"type":"paragraph","text":"После сокращения мышца должна возвращаться в состояние покоя. Расслабление необходимо и для нормального опорожнения мочевого пузыря и кишечника."},{"type":"paragraph","text":"При избыточном напряжении могут возникать боль, дискомфорт при проникновении, затруднение мочеиспускания или ощущение, что мышцы трудно «отпустить». Эти симптомы имеют разные причины: самостоятельно ставить себе диагноз «гипертонус тазового дна» не стоит."},{"type":"paragraph","text":"Дополнительные интенсивные сжатия при таких жалобах могут оказаться неподходящей нагрузкой."},{"type":"heading","text":"Как почувствовать разницу"},{"type":"paragraph","text":"Сядьте с опорой под спиной или лягте на бок. Расслабьте ягодицы и бёдра."},{"type":"paragraph","text":"Представьте, что хотите одновременно удержать газы и мочу: мягко сожмите мышцы вокруг соответствующих отверстий и слегка подтяните их внутрь. Продолжайте спокойно дышать. Затем полностью отпустите усилие и сделайте паузу."},{"type":"paragraph","text":"Не нужно сильно сжимать ягодицы, сводить колени или втягивать живот. Если возникает ощущение выталкивания вниз, техника требует проверки."},{"type":"paragraph","text":"Не тренируйтесь регулярно, останавливая струю мочи: это может мешать нормальному опорожнению мочевого пузыря."},{"type":"heading","text":"Простая практика расслабления"},{"type":"paragraph","text":"Устройтесь удобно и сделайте несколько спокойных дыхательных циклов. На вдохе позвольте нижним рёбрам расшириться, животу — мягко двигаться, а промежности — расслабиться. На выдохе не добавляйте намеренного сжатия."},{"type":"paragraph","text":"Расслабление не означает натуживание. Не нужно давить вниз, задерживать дыхание или пытаться «раскрыть таз»."},{"type":"heading","text":"Когда нужна индивидуальная помощь"},{"type":"paragraph","text":"Обратитесь к врачу или специалисту по реабилитации тазового дна, если упражнения вызывают боль, усиливают давление в промежности либо вы не можете различить сокращение и расслабление."},{"type":"paragraph","text":"Подготовка тазового дна полезна для его функции, но не гарантирует роды без разрывов или других вмешательств."}]},{"id":"pregnancy-063","number":63,"week":21,"title":"Секс во второй половине беременности: какие изменения могут быть абсолютно нормальными","image":null,"blocks":[{"type":"paragraph","text":"При неосложнённой беременности и отсутствии медицинских ограничений сексуальная жизнь обычно допустима. Проникновение не достигает ребёнка: малыш находится в матке, защищён плодными оболочками и околоплодными водами."},{"type":"paragraph","text":"При этом привычные ощущения и желания могут меняться. Ориентироваться стоит на собственный комфорт, а не на то, какой была близость до беременности."},{"type":"heading","text":"Желание может стать сильнее — или почти исчезнуть"},{"type":"paragraph","text":"У некоторых женщин во втором триместре возвращаются энергия и интерес к сексу. Другим мешают усталость, тревога, чувствительность груди или непривычные изменения тела."},{"type":"paragraph","text":"Оба варианта возможны. Нет медицинской нормы частоты секса и необходимости поддерживать прежний ритм. Отсутствие желания не нужно преодолевать через силу."},{"type":"paragraph","text":"Полезно прямо обсуждать с партнёром, какие прикосновения сейчас приятны, какие вызывают дискомфорт и хочется ли вообще проникновения."},{"type":"heading","text":"Ощущения могут стать другими"},{"type":"paragraph","text":"Из-за изменений кровоснабжения и чувствительности тканей привычные прикосновения иногда ощущаются интенсивнее. Может измениться количество естественной смазки."},{"type":"paragraph","text":"При сухости допустим лубрикант на водной основе без раздражающих добавок. Если появляется жжение, боль или зуд, прекратите контакт: такие симптомы требуют выяснения причины, а не только дополнительной смазки."},{"type":"heading","text":"Позиции приходится менять"},{"type":"paragraph","text":"Растущий живот может мешать, а глубокое проникновение — вызывать неприятные ощущения. Часто удобнее положение на боку или другое положение, в котором женщина контролирует глубину и скорость движений."},{"type":"paragraph","text":"Избегайте давления на живот. Если лёжа на спине вы чувствуете дурноту, тошноту или нехватку воздуха, измените положение."},{"type":"paragraph","text":"Объятия, массаж и другие комфортные формы близости тоже остаются полноценной частью сексуальной жизни."},{"type":"heading","text":"После оргазма живот может ненадолго напрячься"},{"type":"paragraph","text":"Кратковременные нерегулярные сокращения матки возможны. Обычно они быстро проходят и не усиливаются."},{"type":"paragraph","text":"Однако регулярное или болезненное напряжение, кровянистые выделения, подтекание жидкости либо сохраняющаяся боль требуют обращения за медицинской помощью. Даже небольшую кровь после секса не стоит автоматически объяснять чувствительной шейкой матки."},{"type":"heading","text":"Когда нужны ограничения"},{"type":"paragraph","text":"Их обсуждают индивидуально — например, при предлежании плаценты, кровотечении, подтекании вод или признаках угрозы преждевременных родов."},{"type":"paragraph","text":"Если врач рекомендовал «половой покой», уточните, что именно ограничено: проникновение, оргазм или другие виды активности, и на какой срок."},{"type":"paragraph","text":"Беременность не защищает от инфекций, передающихся половым путём. При соответствующем риске необходимы презервативы и обследование."}]},{"id":"pregnancy-064","number":64,"week":22,"title":"Почему живот иногда становится твёрдым и быстро расслабляется","image":null,"blocks":[{"type":"paragraph","text":"Вы положили ладонь на живот и заметили, что он стал плотным, а через некоторое время снова мягким. Во второй половине беременности так могут ощущаться кратковременные сокращения матки, которые называют сокращениями Брекстона—Хикса, или тренировочными."},{"type":"paragraph","text":"Они не обязательно появляются у каждой женщины и не показывают, насколько хорошо организм «готовится к родам»."},{"type":"heading","text":"Какие ощущения бывают при тренировочных сокращениях"},{"type":"paragraph","text":"Обычно напряжение:"},{"type":"list-item","text":"возникает нерегулярно;"},{"type":"list-item","text":"не становится постепенно сильнее и чаще;"},{"type":"list-item","text":"проходит самостоятельно;"},{"type":"list-item","text":"не сопровождается выраженной болью."},{"type":"paragraph","text":"Иногда появляется ощущение стягивания или давления. Но определить состояние шейки матки по плотности живота невозможно. Поэтому слово «тонус» само по себе ещё не объясняет причину ощущений и не определяет, нужно ли лечение."},{"type":"paragraph","text":"Не всякое затвердение живота связано именно с сокращением матки: на ощущения также могут влиять положение ребёнка и напряжение мышц брюшной стенки."},{"type":"heading","text":"Что можно сделать при единичном безболезненном эпизоде"},{"type":"paragraph","text":"Остановитесь, если были заняты физической работой. Измените положение, удобно сядьте или лягте на бок. Если хочется в туалет — опорожните мочевой пузырь. Если давно не пили — выпейте воды в обычном для вас количестве."},{"type":"paragraph","text":"Отметьте, прошло ли напряжение и не повторяется ли оно с определённым интервалом. Можно записать время нескольких эпизодов, чтобы точнее описать их врачу."},{"type":"paragraph","text":"Но домашнее наблюдение подходит только при кратком, безболезненном эпизоде и хорошем самочувствии. Оно не должно откладывать обращение при тревожных признаках."},{"type":"heading","text":"Когда нужно связаться с врачом сразу"},{"type":"paragraph","text":"На 22-й неделе требуют срочной оценки:"},{"type":"list-item","text":"повторяющиеся или регулярные сокращения;"},{"type":"list-item","text":"боль, похожая на менструальную;"},{"type":"list-item","text":"новое давление вниз, в таз или промежность;"},{"type":"list-item","text":"необычная постоянная боль в пояснице;"},{"type":"list-item","text":"кровянистые выделения;"},{"type":"list-item","text":"водянистые выделения или подозрение на подтекание вод;"},{"type":"list-item","text":"сильная боль либо живот, который остаётся болезненно напряжённым."},{"type":"paragraph","text":"Не нужно ждать, пока сокращения станут «как в настоящих родах». На таком сроке преждевременные роды могут начинаться с умеренных ощущений. Правило «ехать, когда схватки каждые пять минут» здесь не подходит."},{"type":"heading","text":"Нужно ли принимать что-то от “тонуса”"},{"type":"paragraph","text":"Не начинайте самостоятельно спазмолитики, магний или другие препараты. Тактика зависит от причины симптомов. Если напряжение повторяется и вы сомневаетесь, лучше обсудить его с медицинским специалистом."}]},{"id":"pregnancy-065","number":65,"week":22,"title":"Как меняется осанка беременной и почему начинает уставать поясница","image":null,"blocks":[{"type":"paragraph","text":"По мере роста живота тело приспосабливается к новому распределению веса. Может меняться положение таза, усиливаться поясничный прогиб, появляться привычка отклонять плечи назад. Мышцам приходится иначе удерживать равновесие и поддерживать позвоночник."},{"type":"paragraph","text":"Эти изменения не означают, что осанка «испортилась». Но длительная нагрузка в одной позе действительно может вызывать усталость и боль."},{"type":"heading","text":"Почему поясница реагирует первой"},{"type":"paragraph","text":"Растущий живот меняет условия работы мышц брюшной стенки и спины. Дополнительное значение имеют прежние проблемы с поясницей, рабочее место, привычка долго стоять и переносить тяжёлые вещи."},{"type":"paragraph","text":"Поэтому у двух женщин на одинаковом сроке ощущения могут сильно различаться. Размер живота сам по себе не позволяет предсказать, будет ли болеть спина."},{"type":"heading","text":"Нужно ли постоянно держать спину идеально прямо"},{"type":"paragraph","text":"Нет. Попытка весь день жёстко отводить плечи назад, втягивать живот и напрягать ягодицы может только добавить усталости."},{"type":"paragraph","text":"Полезнее искать устойчивое, удобное положение и регулярно его менять. Даже внешне «правильная» поза становится утомительной, если оставаться в ней надолго."},{"type":"heading","text":"Что изменить в повседневных делах"},{"type":"paragraph","text":"Во время работы за столом придвиньте стул достаточно близко, чтобы не тянуться вперёд. Поддерживайте поясницу спинкой или небольшой подушкой, поставьте стопы на опору. Монитор расположите так, чтобы не приходилось постоянно наклонять голову."},{"type":"paragraph","text":"Если долго стоите, распределяйте вес между обеими ногами. Периодически проходите несколько шагов или садитесь. Во время готовки старайтесь работать ближе к поверхности, а не наклоняться к ней издалека."},{"type":"paragraph","text":"Покупки лучше переносить небольшими порциями. При подъёме предметов держите их ближе к телу и поворачивайтесь переступанием стоп."},{"type":"heading","text":"Движение обычно полезнее длительной неподвижности"},{"type":"paragraph","text":"При отсутствии противопоказаний сохраняйте прогулки, плавание или адаптированные упражнения. Их задача — поддерживать переносимость нагрузки, а не исправлять изгибы позвоночника любой ценой."},{"type":"paragraph","text":"Если после конкретного движения боль усиливается, уменьшите амплитуду или исключите его до консультации. Продолжать через боль не требуется."},{"type":"heading","text":"Когда стоит обратиться за помощью"},{"type":"paragraph","text":"Если боль влияет на походку, мешает переворачиваться в кровати или постоянно возвращается, расскажите врачу. Может потребоваться индивидуальная программа упражнений."},{"type":"paragraph","text":"Срочная оценка нужна при боли вместе с температурой, болезненным мочеиспусканием, кровянистыми выделениями или повторяющимися сокращениями матки. Онемение промежности, нарастающая слабость в ногах и нарушение контроля мочеиспускания требуют неотложной помощи."}]},{"id":"pregnancy-066","number":66,"week":22,"title":"Подушка для беременных: действительно полезная вещь или маркетинг","image":null,"blocks":[{"type":"paragraph","text":"Подушка для беременных может сделать сон удобнее, если помогает поддерживать живот, спину или ноги. Но особая форма и надпись на упаковке не делают её обязательной медицинской покупкой."},{"type":"paragraph","text":"Оценивать пользу лучше по конкретному результату: стало ли легче устроиться, уменьшилось ли натяжение и проще ли поворачиваться."},{"type":"heading","text":"Что подушка действительно может дать"},{"type":"paragraph","text":"Когда вы лежите на боку, верхняя нога иногда уходит вперёд и разворачивает таз. Опора между ногами может сделать положение устойчивее."},{"type":"paragraph","text":"Небольшая поддержка под животом бывает полезна, если чувствуется натяжение. Опора за спиной помогает расслабиться и найти удобный угол положения тела."},{"type":"paragraph","text":"При этом подушка не лечит причину выраженной боли, не «поднимает» плаценту и не гарантирует профилактику осложнений беременности."},{"type":"heading","text":"Обязательно ли покупать специальную"},{"type":"paragraph","text":"Нет. Сначала можно попробовать обычные домашние подушки или мягкий валик. Если они хорошо держатся и обеспечивают нужную поддержку, дополнительная покупка может не понадобиться."},{"type":"paragraph","text":"Специальная модель бывает удобна, когда несколько отдельных подушек постоянно разъезжаются. Но большая конструкция занимает место, может мешать переворачиваться и оказаться слишком тёплой."},{"type":"heading","text":"Как выбрать форму"},{"type":"paragraph","text":"Выбирайте под задачу:"},{"type":"list-item","text":"длинная прямая подушка подходит для поддержки ноги и объятий;"},{"type":"list-item","text":"С-образная может поддерживать несколько участков тела;"},{"type":"list-item","text":"U-образная даёт опору с двух сторон, но требует больше места;"},{"type":"list-item","text":"небольшой клин удобен для локальной поддержки, например под животом."},{"type":"paragraph","text":"Это различия в удобстве, а не рейтинг медицинской эффективности. Универсальной лучшей формы для всех беременных нет."},{"type":"heading","text":"Что проверить перед покупкой"},{"type":"paragraph","text":"Важно, чтобы высота и плотность подходили именно вам. Подушка не должна сильно отводить верхнее колено, скручивать таз или поднимать голову к плечу."},{"type":"paragraph","text":"Проверьте, можно ли легко поменять сторону и встать с кровати. Практичны съёмный чехол, понятные правила стирки и возможность изменить количество наполнителя. Возможность возврата особенно полезна: удобство трудно оценить по фотографии."},{"type":"heading","text":"Если с подушкой всё равно больно"},{"type":"paragraph","text":"Не стоит бесконечно покупать новые модели. Боль в области лобка, таза или поясницы, которая мешает спать и двигаться, требует оценки специалистом."},{"type":"paragraph","text":"После рождения ребёнка используйте такую подушку только по назначению. Объёмные взрослые подушки не подходят для сна младенца: ему нужна отдельная ровная твёрдая поверхность без мягких бортиков и валиков."}]},{"id":"pregnancy-067","number":67,"week":23,"title":"Как лучше организовать питание, если после еды появляется тяжесть","image":null,"blocks":[{"type":"paragraph","text":"Во второй половине беременности привычная порция иногда вызывает ощущение переполнения, отрыжку или изжогу. На пищеварение влияют гормональные изменения, а растущая матка постепенно меняет положение органов брюшной полости."},{"type":"paragraph","text":"Часто помогает не строгая диета, а изменение объёма порций, времени еды и положения тела после неё."},{"type":"heading","text":"Начните с размера порции"},{"type":"paragraph","text":"Если после большого обеда тяжело, разделите его на два меньших приёма. Например, основное блюдо съешьте в обед, а фрукт или йогурт оставьте на более поздний перекус."},{"type":"paragraph","text":"Не обязательно переходить на строго определённое количество приёмов пищи. Подбирайте ритм, при котором вы не доходите до сильного голода и не переедаете за один раз."},{"type":"paragraph","text":"Есть медленнее тоже полезно: делайте небольшие паузы и останавливайтесь, когда появились комфортное насыщение и первые признаки переполнения."},{"type":"heading","text":"Сохраните полноценность питания"},{"type":"paragraph","text":"Уменьшение порции не должно превращаться в хроническое недоедание. В течение дня по-прежнему нужны источники белка, углеводов, жиров и пищевых волокон."},{"type":"paragraph","text":"Если объёмная сырая пища усиливает дискомфорт, попробуйте часть овощей в приготовленном виде. Например, запечённые или тушёные овощи вместо большой миски салата. Это способ подобрать переносимую форму, а не повод исключать целую группу продуктов."},{"type":"heading","text":"Проверьте индивидуальные провокаторы"},{"type":"paragraph","text":"Жирная и жареная пища, острые блюда, шоколад и напитки с кофеином у некоторых женщин усиливают изжогу. Но запрещать всё сразу не нужно."},{"type":"paragraph","text":"На несколько дней запишите, что и сколько вы ели, когда появились симптомы. Так проще заметить повторяющуюся связь и избежать ненужных ограничений."},{"type":"heading","text":"После еды оставайтесь вертикально"},{"type":"paragraph","text":"Не ложитесь сразу после приёма пищи. Лучше спокойно посидеть или немного пройтись, если вам комфортно. Избегайте одежды, которая давит на верхнюю часть живота."},{"type":"paragraph","text":"При ночной изжоге постарайтесь заканчивать плотный ужин примерно за три часа до сна. Воду продолжайте пить в течение дня: ограничивать жидкость ради борьбы с тяжестью не требуется."},{"type":"heading","text":"Когда нужна помощь"},{"type":"paragraph","text":"Если изменения питания не помогают, обсудите симптомы с врачом. При беременности существуют допустимые средства от изжоги, но выбор зависит от жалоб и других лекарств."},{"type":"paragraph","text":"Сильную или постоянную боль, повторную рвоту, затруднение глотания, кровь в рвоте либо чёрный дегтеобразный стул нельзя объяснять обычной тяжестью. Боль под правыми рёбрами или вверху живота вместе с головной болью либо нарушением зрения требует срочной оценки."}]},{"id":"pregnancy-068","number":68,"week":23,"title":"Как сохранить хороший сон во второй половине беременности","image":null,"blocks":[{"type":"paragraph","text":"Ночные пробуждения во время беременности встречаются часто. Могут мешать походы в туалет, изжога, неудобная поза, шевеления и мысли о предстоящих изменениях. Даже если раньше вы засыпали без усилий, теперь сну может понадобиться больше внимания."},{"type":"paragraph","text":"Цель — создать условия для отдыха и устранить конкретные помехи. Добиваться «идеальной ночи» любой ценой не нужно."},{"type":"heading","text":"Закрепите время подъёма"},{"type":"paragraph","text":"Старайтесь вставать примерно в одно время, включая выходные. Утренний дневной свет и обычная дневная активность помогают поддерживать ритм сна и бодрствования."},{"type":"paragraph","text":"Ложитесь, когда появляется сонливость. Если вы провели плохую ночь, не обязательно проводить весь следующий день в постели: это может затруднить засыпание вечером."},{"type":"heading","text":"Пересмотрите дневной сон"},{"type":"paragraph","text":"Если короткий отдых помогает и не влияет на ночь, его можно оставить. Если после дневного сна долго не удаётся заснуть вечером, попробуйте сократить его или перенести на более раннее время."},{"type":"paragraph","text":"Длительная вечерняя дремота часто мешает сильнее, чем небольшой отдых в первой половине дня."},{"type":"heading","text":"Сделайте вечер спокойнее"},{"type":"paragraph","text":"За некоторое время до сна уменьшите яркость освещения и отложите работу, тревожные новости и обсуждение сложных вопросов. Выберите повторяющийся ритуал: душ, спокойное чтение, музыка или несколько минут расслабления."},{"type":"paragraph","text":"Кофеин может мешать засыпанию, даже если напиток выпит не непосредственно перед сном. Учитывайте кофе, чай, колу и другие его источники."},{"type":"heading","text":"Устраните конкретную причину пробуждений"},{"type":"paragraph","text":"При изжоге помогает более ранний ужин и подходящее положение туловища. При дискомфорте в спине — опора под животом или между ногами. Если часто хочется в туалет, основную часть питья можно распределить на день, но не доводить себя до жажды и обезвоживания."},{"type":"paragraph","text":"Если вы долго лежите без сна и начинаете раздражаться, можно ненадолго встать, заняться спокойным делом при приглушённом свете и вернуться в постель, когда снова появится сонливость."},{"type":"heading","text":"Когда стоит обратиться к врачу"},{"type":"paragraph","text":"Обсудите сон, если проблемы повторяются и заметно мешают жить днём. Особенно важно сообщить о громком храпе с остановками дыхания, выраженной дневной сонливости или неприятных ощущениях в ногах, из-за которых постоянно хочется ими двигать."},{"type":"paragraph","text":"Стойкая тревога, подавленность и потеря интереса к привычным занятиям тоже требуют внимания. При длительной бессоннице может помочь когнитивно-поведенческая терапия."},{"type":"paragraph","text":"Не начинайте самостоятельно снотворные, мелатонин или «натуральные» успокаивающие сборы: их безопасность при беременности нужно оценивать отдельно."}]},{"id":"pregnancy-069","number":69,"week":23,"title":"Какие упражнения помогают мягко разгружать спину и таз","image":null,"blocks":[{"type":"paragraph","text":"При обычной мышечной усталости спокойные движения могут уменьшать скованность и помогать переносить повседневную нагрузку. Для этого не нужна интенсивная тренировка: важнее комфортная амплитуда и регулярность."},{"type":"paragraph","text":"Упражнения подходят при неосложнённой беременности, если врач не ограничил физическую активность. При новой, выраженной или нарастающей боли сначала нужно выяснить её причину."},{"type":"heading","text":"1. Мягкое округление спины на четвереньках"},{"type":"paragraph","text":"Встаньте на устойчивую нескользкую поверхность. Ладони расположите примерно под плечами, колени — под тазом. Оставьте животу достаточно пространства."},{"type":"paragraph","text":"На спокойном выдохе немного округлите спину, без сильного втягивания живота. Затем плавно вернитесь в удобное нейтральное положение."},{"type":"paragraph","text":"Не нужно глубоко прогибать поясницу и запрокидывать голову. Начните с нескольких повторений; при хорошем самочувствии можно постепенно довести их примерно до десяти."},{"type":"paragraph","text":"Если болят запястья или колени, не пытайтесь терпеть ради упражнения — попросите специалиста подобрать другой вариант."},{"type":"heading","text":"2. Небольшие движения тазом у стены"},{"type":"paragraph","text":"Встаньте спиной к стене, слегка согните колени. Мягко измените положение таза так, чтобы поясничный прогиб немного уменьшился. Затем отпустите усилие."},{"type":"paragraph","text":"Движение должно быть небольшим. Не прижимайте спину силой и не задерживайте дыхание. Выполните несколько комфортных повторений, наблюдая за ощущениями."},{"type":"heading","text":"3. Короткие прогулки вместо одной длинной"},{"type":"paragraph","text":"Если к концу длительной прогулки начинает болеть таз или поясница, разделите её на несколько небольших выходов. Выбирайте ровную поверхность и темп, при котором можете спокойно разговаривать."},{"type":"paragraph","text":"При боли в лобке уменьшение длины шага иногда делает ходьбу удобнее. Если боль сохраняется или меняет походку, нужна индивидуальная оценка."},{"type":"heading","text":"4. Движение в воде"},{"type":"paragraph","text":"Плавание и адаптированные занятия в бассейне могут облегчать нагрузку благодаря поддержке воды. Выбирайте движения, которые не вызывают боли. При дискомфорте в области лобка широкое разведение ног, в том числе при некоторых плавательных движениях, может не подходить."},{"type":"heading","text":"Как оценить результат"},{"type":"paragraph","text":"После занятия допустимо ощущение лёгкой работы мышц. Нарастание боли, давления в промежности или ухудшение самочувствия означает, что нагрузку нужно изменить."},{"type":"paragraph","text":"Не нужно растягиваться через боль, делать широкие выпады ради «раскрытия таза» или пытаться самостоятельно «вправить» его."},{"type":"paragraph","text":"Прекратите занятие при головокружении, кровянистых выделениях, подтекании жидкости, болезненных повторяющихся сокращениях, боли в груди или необычной одышке. При таких симптомах обратитесь за медицинской помощью."}]},{"id":"pregnancy-070","number":70,"week":24,"title":"Глюкозотолерантный тест: зачем его делают беременным и как он проходит","image":null,"blocks":[{"type":"paragraph","text":"Гестационный сахарный диабет — повышение уровня глюкозы, впервые выявленное во время беременности и соответствующее определённым диагностическим критериям. Он может развиваться без жажды, слабости и других заметных симптомов."},{"type":"paragraph","text":"Поэтому хорошее самочувствие и нормальный анализ в начале беременности не всегда позволяют отказаться от обследования во втором триместре."},{"type":"heading","text":"Почему тест проводят именно сейчас"},{"type":"paragraph","text":"Во время беременности чувствительность тканей к инсулину постепенно снижается. Это связано в том числе с действием гормонов плаценты. Поджелудочной железе приходится вырабатывать больше инсулина, чтобы удерживать глюкозу в нужном диапазоне."},{"type":"paragraph","text":"Если этой адаптации недостаточно, уровень глюкозы повышается. Гестационный диабет может возникнуть и у женщины без лишнего веса, которая не злоупотребляет сладким."},{"type":"paragraph","text":"Стандартное время для перорального глюкозотолерантного теста, или ПГТТ, — 24–28 недель, если диабет не был установлен раньше."},{"type":"heading","text":"Как проходит исследование"},{"type":"paragraph","text":"В российской практике используют тест с 75 г глюкозы:"},{"type":"paragraph","text":"1. Утром натощак берут кровь из вены."},{"type":"paragraph","text":"2. Если исходный результат позволяет продолжать исследование, женщина выпивает раствор глюкозы."},{"type":"paragraph","text":"3. Повторные пробы венозной крови берут через один и два часа от начала приёма раствора."},{"type":"paragraph","text":"Раствор обычно нужно выпить в течение пяти минут. Точные указания даёт сотрудник лаборатории."},{"type":"paragraph","text":"Между заборами крови необходимо спокойно сидеть. Нельзя есть, курить, гулять по магазинам или специально ходить по лестнице: физическая активность влияет на результат. Возможность пить обычную воду уточните у персонала."},{"type":"heading","text":"Какие ощущения возможны"},{"type":"paragraph","text":"Раствор очень сладкий и иногда вызывает тошноту. Если стало плохо, сразу сообщите сотруднику. При рвоте тест обычно нельзя достоверно завершить — дальнейший план определит врач."},{"type":"paragraph","text":"При отсутствии противопоказаний ПГТТ считается безопасным диагностическим исследованием. Он не вызывает диабет, а показывает, как организм справляется с углеводной нагрузкой."},{"type":"heading","text":"Что означает повышенный результат"},{"type":"paragraph","text":"Для диагностики используют специальные нормы для беременности. Достаточным может быть отклонение одного из показателей. Оценивать результат по нормам для небеременных или показаниям домашнего глюкометра неправильно."},{"type":"paragraph","text":"Если выявлен гестационный диабет, врач объяснит, как организовать питание, контролировать глюкозу и поддерживать допустимую активность. Некоторым женщинам требуется инсулин."},{"type":"paragraph","text":"Своевременное лечение помогает уменьшить риски, включая чрезмерный рост ребёнка и снижение его глюкозы после рождения. Диагноз не означает, что осложнения обязательно произойдут или что женщина «сама виновата»."}]},{"id":"pregnancy-071","number":71,"week":24,"title":"Как подготовиться к глюкозотолерантному тесту, чтобы не пришлось пересдавать","image":null,"blocks":[{"type":"paragraph","text":"Задача подготовки к ПГТТ — получить достоверный результат в обычных для организма условиях. Специальная «диета для хорошего сахара» перед исследованием может помешать оценке."},{"type":"paragraph","text":"Даже правильная подготовка не исключает переноса теста, например из-за болезни или рвоты. Но несколько простых правил помогают избежать наиболее частых проблем."},{"type":"heading","text":"За три дня: питайтесь привычно"},{"type":"paragraph","text":"Не переходите на низкоуглеводное питание, не голодайте и не исключайте каши, хлеб, фрукты и другие источники углеводов ради анализа."},{"type":"paragraph","text":"Российский протокол предусматривает обычное питание с не менее чем 150 г углеводов в сутки минимум в течение трёх дней перед тестом. Речь идёт о количестве питательного вещества, а не о весе еды и не о необходимости съесть 150 г сахара."},{"type":"paragraph","text":"Сохраняйте привычную посильную активность. Не добавляйте непривычные интенсивные тренировки и не пытайтесь заранее «израсходовать глюкозу»."},{"type":"heading","text":"Накануне: обычный ужин"},{"type":"paragraph","text":"Последний приём пищи должен содержать углеводы. В протоколе указан ориентир 30–50 г углеводов: это может быть обычная порция гарнира с учётом остальных продуктов ужина."},{"type":"paragraph","text":"Не нужно устраивать ни сладкую «загрузку», ни ужин только из мяса и огурцов. Если вам уже назначено лечебное питание, заранее согласуйте подготовку с врачом."},{"type":"heading","text":"Утром: приходите натощак"},{"type":"paragraph","text":"Обычно требуется ночной перерыв без еды не менее восьми часов; чрезмерно продлевать голодание не следует. Уточните время последнего приёма пищи по инструкции вашей лаборатории."},{"type":"paragraph","text":"Обычная вода разрешена. Кофе, чай, сок, молоко, леденцы и жевательная резинка не подходят. Не курите и не используйте вейп."},{"type":"heading","text":"Лекарства обсудите заранее"},{"type":"paragraph","text":"Некоторые препараты могут влиять на глюкозу. Сообщите врачу обо всём, что принимаете, включая витамины и сиропы. Не отменяйте необходимое лечение самостоятельно: специалист решит, можно ли перенести приём на время после исследования."},{"type":"heading","text":"Когда нужно предупредить клинику"},{"type":"paragraph","text":"Позвоните заранее, если появились температура, инфекция, выраженная тошнота или рвота. Обязательно сообщите о перенесённых операциях на желудке, включая бариатрические, и если диабет уже установлен."},{"type":"heading","text":"Что взять с собой"},{"type":"paragraph","text":"Возьмите воду, спокойное занятие на время ожидания и перекус, который можно съесть после последнего забора крови. Заложите больше двух часов на весь визит."},{"type":"paragraph","text":"Если вы случайно позавтракали, выпили кофе или нарушили подготовку, скажите об этом до начала исследования. Это поможет избежать недостоверного результата."}]},{"id":"pregnancy-072","number":72,"week":24,"title":"Отёки ног к вечеру: почему обувь и кольца могут становиться теснее","image":null,"blocks":[{"type":"paragraph","text":"К вечеру обувь давит, от носков остаются следы, а привычное кольцо снимается труднее. Во второй половине беременности организм удерживает больше жидкости, а растущая матка может затруднять отток крови от ног."},{"type":"paragraph","text":"Поэтому постепенная отёчность стоп и лодыжек, особенно после жары или долгого стояния, встречается часто. Но оценивать нужно не только наличие отёка, а скорость его появления, симметричность и сопутствующие симптомы."},{"type":"heading","text":"Какая картина чаще бывает при обычной отёчности"},{"type":"paragraph","text":"Обе ноги отекают примерно одинаково. К вечеру отёчность заметнее, после ночного отдыха — меньше. Нет выраженной боли, покраснения одной ноги или резкого ухудшения самочувствия."},{"type":"paragraph","text":"Такую ситуацию всё равно стоит обсудить на приёме, особенно если отёки появились впервые. По одному внешнему виду нельзя окончательно определить их причину."},{"type":"heading","text":"Что помогает в течение дня"},{"type":"paragraph","text":"Чередуйте ходьбу, сидение и отдых. Если работаете за столом, регулярно двигайте стопами и ненадолго вставайте. При долгом стоянии делайте перерывы."},{"type":"paragraph","text":"Во время отдыха удобно приподнимите ноги на опору. Выбирайте обувь с достаточным пространством для стопы и носки без тугой резинки."},{"type":"paragraph","text":"Если врач рекомендует компрессионный трикотаж, уточните размер и степень компрессии. Случайно выбранные очень тугие гольфы не заменяют правильный подбор."},{"type":"heading","text":"Что делать с кольцами"},{"type":"paragraph","text":"Если кольца стали теснее, лучше снять их заранее. Не ждите, пока они начнут болезненно сдавливать палец."},{"type":"paragraph","text":"Если кольцо не снимается, а палец синеет, немеет или сильно болит, нужна срочная помощь для его удаления."},{"type":"heading","text":"Нужно ли меньше пить"},{"type":"paragraph","text":"Не ограничивайте резко воду и не принимайте мочегонные препараты или травяные сборы самостоятельно. Отёки не означают, что вся выпитая вода «остаётся в ногах». Не требуется и полностью бессолевая диета без медицинских показаний."},{"type":"heading","text":"Когда обращаться срочно"},{"type":"paragraph","text":"Внезапное нарастание отёков, особенно лица и рук, требует оценки врача. Если одновременно появились сильная головная боль, нарушения зрения, боль вверху живота или повышенное давление, помощь нужна без промедления."},{"type":"paragraph","text":"Отёк сам по себе не подтверждает преэклампсию. При этом преэклампсия может развиваться и без заметных отёков."},{"type":"paragraph","text":"Если одна нога стала значительно больше другой, болит, покраснела или ощущается горячей, необходимо срочно исключить тромбоз. Не массируйте её."},{"type":"paragraph","text":"При внезапной одышке, боли в груди или обмороке вызывайте скорую помощь."}]},{"id":"pregnancy-073","number":73,"week":25,"title":"Изжога во время беременности: почему появляется и как облегчить состояние","image":null,"blocks":[{"type":"paragraph","text":"Жжение за грудиной, кислый привкус во рту, неприятные ощущения после еды или в положении лёжа — так часто проявляется изжога. Во время беременности она может появиться даже у тех, кто раньше с ней не сталкивался."},{"type":"paragraph","text":"Одна из причин — расслабление мышечного кольца между пищеводом и желудком под влиянием гормональных изменений. Содержимому желудка становится легче попадать обратно в пищевод. По мере роста матки добавляется давление на органы брюшной полости."},{"type":"heading","text":"Что помогает без лекарств"},{"type":"paragraph","text":"Начните с объёма порций. Если после плотного обеда появляется жжение, попробуйте есть меньшими порциями, распределяя питание в течение дня. Не нужно терпеть сильный голод, а затем съедать большой объём за один раз."},{"type":"paragraph","text":"После еды оставайтесь в вертикальном положении. Не ложитесь сразу и по возможности избегайте работы в наклоне. Последний плотный приём пищи лучше закончить примерно за три часа до сна."},{"type":"paragraph","text":"Одежда не должна сдавливать верхнюю часть живота. При ночной изжоге иногда помогает приподнятое изголовье или клиновидная опора под верхнюю часть туловища."},{"type":"heading","text":"Нужно ли исключать определённые продукты"},{"type":"paragraph","text":"У некоторых женщин симптомы усиливают жирные блюда, шоколад, кофе, острые или кислые продукты. Но универсального списка запретов нет."},{"type":"paragraph","text":"Полезнее несколько дней наблюдать за связью между едой и ощущениями. Если конкретный продукт стабильно вызывает жжение, уменьшите его количество или временно замените. Не исключайте сразу множество продуктов без необходимости."},{"type":"heading","text":"Если этого недостаточно"},{"type":"paragraph","text":"Обсудите с врачом лекарственную помощь. При беременности могут применяться некоторые антациды, которые нейтрализуют кислоту, и альгинаты, уменьшающие её заброс. При стойких симптомах врач может подобрать другую терапию."},{"type":"paragraph","text":"Не все средства от изжоги подходят беременным. Соду как домашнее лечение использовать не стоит."},{"type":"paragraph","text":"Антациды могут мешать всасыванию железа и фолиевой кислоты: обычно между их приёмом требуется интервал не менее двух часов. Уточните схему с учётом конкретных препаратов."},{"type":"heading","text":"Когда нельзя списывать всё на изжогу"},{"type":"paragraph","text":"Обратитесь к врачу при затруднении глотания, повторной рвоте, снижении веса или постоянной боли."},{"type":"paragraph","text":"Сильная боль в груди, особенно с одышкой и слабостью, требует неотложной помощи. Боль вверху живота или под правыми рёбрами вместе с головной болью, нарушением зрения либо повышенным давлением также нуждается в срочной оценке."}]},{"id":"pregnancy-074","number":74,"week":25,"title":"Варикоз во время беременности: как уменьшить нагрузку на ноги","image":null,"blocks":[{"type":"paragraph","text":"На ногах стали заметнее вены, к вечеру появляется тяжесть, а после долгого стояния хочется скорее присесть? Во время беременности объём циркулирующей крови увеличивается, венозная стенка становится более податливой, а растущая матка может затруднять отток крови от нижних конечностей."},{"type":"paragraph","text":"В результате поверхностные вены иногда расширяются. Наследственная предрасположенность и варикоз до беременности повышают вероятность таких изменений."},{"type":"heading","text":"Какие проявления возможны"},{"type":"paragraph","text":"Варикоз может сопровождаться ощущением тяжести, распирания, зудом над венами и отёчностью к вечеру. Иногда видимые вены почти не беспокоят."},{"type":"paragraph","text":"По внешнему виду нельзя определить, насколько хорошо работает венозная система. Если появились новые симптомы, расскажите врачу. При необходимости он направит на ультразвуковое исследование вен."},{"type":"heading","text":"Почему полезно двигаться"},{"type":"paragraph","text":"Во время ходьбы мышцы голени помогают продвигать кровь вверх. Долгое неподвижное стояние или сидение лишает ноги этой поддержки."},{"type":"paragraph","text":"Не обязательно устраивать длительные прогулки. Полезны короткие перерывы: пройтись по комнате, несколько раз плавно согнуть и разогнуть стопы, изменить положение."},{"type":"paragraph","text":"Если приходится долго сидеть, поставьте стопы на опору и не поджимайте ноги под себя. Если долго стоите — найдите возможность периодически присаживаться."},{"type":"heading","text":"Как организовать отдых"},{"type":"paragraph","text":"Удобно расположите ноги на подставке или подушке. Положение не должно вызывать натяжение под коленями или боль в пояснице."},{"type":"paragraph","text":"Выбирайте обувь, которая не сдавливает стопу, и одежду без тугих резинок. Если жара усиливает симптомы, избегайте перегрева и длительного пребывания в душном помещении."},{"type":"paragraph","text":"Врач может рекомендовать медицинский компрессионный трикотаж. Он помогает уменьшить венозный застой и неприятные ощущения, но не заменяет движение."},{"type":"heading","text":"Что не стоит делать самостоятельно"},{"type":"paragraph","text":"Не начинайте приём «венотоников», мочегонных и растительных средств без согласования. Безопасность и необходимость каждого препарата оценивают отдельно."},{"type":"paragraph","text":"Не пытайтесь интенсивно разминать болезненную вену или «разгонять кровь» сильным массажем."},{"type":"heading","text":"Когда нужна срочная оценка"},{"type":"paragraph","text":"Если одна нога внезапно отекла сильнее другой, появилась боль, покраснение или ощущение жара, необходимо исключить тромбоз. Болезненный плотный участок по ходу поверхностной вены тоже требует осмотра."},{"type":"paragraph","text":"Внезапная одышка, боль в груди или обморок — повод вызвать скорую помощь. Обычный варикоз и тромбоз — разные состояния, но отличать их при новых симптомах должен специалист."}]},{"id":"pregnancy-075","number":75,"week":25,"title":"Компрессионный трикотаж: кому он может быть полезен и как его выбирать","image":null,"blocks":[{"type":"paragraph","text":"Медицинские гольфы, чулки и колготки создают рассчитанное давление на ноги. Обычно оно сильнее в области лодыжки и уменьшается выше. Такая компрессия помогает венозной крови возвращаться к сердцу и может уменьшать отёчность, тяжесть и боль."},{"type":"paragraph","text":"Но «чем сильнее сдавливает, тем лучше» — неправильный принцип выбора."},{"type":"heading","text":"Кому может понадобиться компрессия"},{"type":"paragraph","text":"Врач может рекомендовать её при симптомах варикозной болезни, некоторых видах отёков и в отдельных ситуациях повышенного риска венозных осложнений."},{"type":"paragraph","text":"Беременность сама по себе не означает, что каждой женщине обязательно нужны лечебные чулки. Сначала определяют задачу: облегчение симптомов, помощь при заболевании вен или профилактика в конкретной ситуации."},{"type":"paragraph","text":"При высоком риске тромбоза одного трикотажа может быть недостаточно. Если назначены препараты для профилактики, чулки не заменяют их."},{"type":"heading","text":"Что важно при выборе"},{"type":"paragraph","text":"У медицинского изделия должны быть указаны уровень давления в миллиметрах ртутного столба и соответствующий стандарт. Обозначение DEN характеризует плотность нити, а не лечебную компрессию."},{"type":"paragraph","text":"Нумерация классов в разных стандартах может отличаться. Поэтому ориентируйтесь на назначение специалиста и параметры изделия, а не только на надпись «первый» или «второй класс»."},{"type":"paragraph","text":"Гольфы, чулки и колготки выбирают с учётом расположения симптомов. Более длинная модель не обязательно эффективнее подходящих гольфов."},{"type":"heading","text":"Размер определяют по измерениям"},{"type":"paragraph","text":"Обычно нужны окружности лодыжки и голени, а для чулок — также бедра и длина ноги. Измерения делают по инструкции производителя, желательно утром, пока отёчность минимальна."},{"type":"paragraph","text":"Размер обуви и размер обычной одежды не позволяют точно подобрать компрессионное изделие."},{"type":"heading","text":"Как носить"},{"type":"paragraph","text":"Надевайте трикотаж без складок и перекручиваний. Не подворачивайте верхний край: плотный валик может сильно пережимать ткани."},{"type":"paragraph","text":"Для дневной активности изделия обычно надевают утром и снимают перед сном, если врач не назначил другой режим. Госпитальный противоэмболический трикотаж имеет свои правила применения."},{"type":"heading","text":"Какие ощущения ненормальны"},{"type":"paragraph","text":"Онемение, нарастающая боль, холодные или изменившие цвет пальцы — повод снять изделие и обратиться за консультацией."},{"type":"paragraph","text":"При заболеваниях артерий ног, повреждениях кожи и некоторых других состояниях компрессия требует особой оценки. А при внезапном одностороннем отёке сначала нужен врач — покупка более тугих чулок не должна откладывать обследование."}]},{"id":"pregnancy-076","number":76,"week":26,"title":"Тренировочные сокращения матки: почему они могут появляться задолго до родов","image":null,"blocks":[{"type":"paragraph","text":"Матка состоит преимущественно из мышечной ткани. Во время беременности она может кратковременно сокращаться, а затем расслабляться. Такие эпизоды называют сокращениями Брекстона—Хикса, или тренировочными."},{"type":"paragraph","text":"Некоторые женщины замечают их уже во втором триместре, другие — гораздо позже. Отсутствие заметных тренировочных сокращений тоже нормально."},{"type":"heading","text":"Почему название может вводить в заблуждение"},{"type":"paragraph","text":"Слово «тренировочные» не означает, что матка должна выполнять определённую программу или что по частоте сокращений можно оценить готовность к родам."},{"type":"paragraph","text":"Эти ощущения не позволяют предсказать дату рождения ребёнка. По ним также нельзя судить, насколько легко пройдут роды."},{"type":"heading","text":"Как они обычно ощущаются"},{"type":"paragraph","text":"Живот на некоторое время становится плотнее, может появляться стягивание. Типичные тренировочные сокращения нерегулярны, не усиливаются последовательно и не становятся всё чаще. Чаще они безболезненны, хотя могут быть неприятными."},{"type":"paragraph","text":"Отдельные эпизоды иногда заметнее после физической активности или оргазма. Но ни обстоятельства появления, ни уменьшение ощущений после отдыха не дают полной гарантии, что обследование не требуется."},{"type":"heading","text":"Что делать при единичном эпизоде"},{"type":"paragraph","text":"Прекратите нагрузку, удобно сядьте или лягте на бок. При необходимости сходите в туалет, выпейте воды, если давно не пили."},{"type":"paragraph","text":"Обратите внимание, полностью ли прошло напряжение и нет ли других симптомов. Если эпизоды повторяются, можно записать время их начала и длительность, чтобы описать врачу."},{"type":"paragraph","text":"Не нужно постоянно ощупывать живот или пытаться самостоятельно проверять шейку матки."},{"type":"heading","text":"Когда обращаться без ожидания"},{"type":"paragraph","text":"На 26-й неделе регулярные, учащающиеся или болезненные сокращения требуют срочной медицинской оценки. Особенно если появились:"},{"type":"list-item","text":"тянущая боль, похожая на менструальную;"},{"type":"list-item","text":"давление вниз, в таз или промежность;"},{"type":"list-item","text":"необычная постоянная боль в пояснице;"},{"type":"list-item","text":"кровь или водянистые выделения;"},{"type":"list-item","text":"заметное уменьшение привычных шевелений."},{"type":"paragraph","text":"Преждевременные роды не всегда начинаются с сильной боли. Поэтому не нужно ждать коротких интервалов между схватками или ориентироваться на правила для доношенной беременности."},{"type":"heading","text":"Нужно ли лечить тренировочные сокращения"},{"type":"paragraph","text":"Единичные физиологические сокращения сами по себе не означают необходимость лекарств или постельного режима. Но при повторяющихся симптомах причину должен оценить врач."},{"type":"paragraph","text":"Не начинайте самостоятельно спазмолитики, магний или другие средства «от тонуса»: они могут оказаться ненужными и отсрочить правильную оценку состояния."}]},{"id":"pregnancy-077","number":77,"week":26,"title":"Почему ночью становится трудно найти удобную позу","image":null,"blocks":[{"type":"paragraph","text":"К вечеру хочется лечь, но в кровати оказывается неудобно: тянет живот, затекает бедро, мешает изжога или приходится часто переворачиваться. Обычно это связано сразу с несколькими изменениями — ростом матки, перераспределением нагрузки и повышенной чувствительностью отдельных участков тела."},{"type":"paragraph","text":"При этом не всякую ночную боль нужно считать неизбежной частью беременности."},{"type":"heading","text":"Сначала определите, что именно мешает"},{"type":"paragraph","text":"Если неприятно лежать на плече или бедре, попробуйте сменить сторону и скорректировать высоту подушки."},{"type":"paragraph","text":"Если тянет живот, может помочь небольшая опора под него. Если верхняя нога уходит вперёд и разворачивает таз — подушка между ногами."},{"type":"paragraph","text":"Если беспокоит жжение за грудиной, важнее приподнять верхнюю часть туловища и пересмотреть время ужина, чем искать особое положение ног."},{"type":"paragraph","text":"Меняйте по одному элементу: так проще понять, что действительно помогает."},{"type":"heading","text":"Как уменьшить нагрузку на таз"},{"type":"paragraph","text":"Лёжа на боку, слегка согните ноги и подберите опору такой высоты, чтобы таз не перекручивался. Слишком толстая подушка может чрезмерно поднять верхнее колено и усилить дискомфорт."},{"type":"paragraph","text":"При болезненных переворотах двигайтесь медленнее, помогая себе руками. Если боль в лобке усиливается при разведении ног, старайтесь поворачиваться с коленями ближе друг к другу, в комфортном диапазоне."},{"type":"paragraph","text":"Такая боль — повод обсудить состояние тазового пояса со специалистом."},{"type":"heading","text":"Нужно ли всю ночь лежать на одном боку"},{"type":"paragraph","text":"Нет. Можно менять левый и правый бок."},{"type":"paragraph","text":"С 28 недель рекомендуется засыпать на боку. Если вы проснулись на спине, достаточно повернуться — не нужно тревожиться или устанавливать ночной контроль положения."},{"type":"paragraph","text":"Если на спине появляются тошнота, слабость или головокружение, смените позу сразу. Если состояние не улучшается, обратитесь за помощью."},{"type":"heading","text":"Что подготовить рядом с кроватью"},{"type":"paragraph","text":"Поставьте воду, обеспечьте свободный проход и мягкое освещение для ночных подъёмов. Вставайте через бок: сначала опустите ноги, помогите себе руками, немного посидите и только потом поднимайтесь."},{"type":"heading","text":"Когда нужна оценка врача"},{"type":"paragraph","text":"Обратитесь за консультацией, если боль регулярно будит, мешает ходить или не уменьшается после смены положения."},{"type":"paragraph","text":"Внезапную нехватку воздуха, боль в груди, выраженную слабость, болезненные регулярные сокращения или подтекание жидкости нельзя объяснять только неудобной позой. В таких ситуациях требуется срочная медицинская помощь."}]},{"id":"pregnancy-078","number":78,"week":26,"title":"Как выбрать обувь на последние месяцы беременности","image":null,"blocks":[{"type":"paragraph","text":"Во второй половине беременности привычная обувь иногда начинает давить. Стопы могут отекать к вечеру, а увеличение нагрузки и изменение равновесия делают некоторые модели менее удобными."},{"type":"paragraph","text":"Покупать специальную «обувь для беременных» необязательно. Важнее, чтобы она подходила вашим стопам сейчас и позволяла уверенно ходить."},{"type":"heading","text":"Начните с посадки"},{"type":"paragraph","text":"Пальцы не должны упираться в носок или сжиматься с боков. При этом обувь не должна болтаться: слишком свободная пара заставляет удерживать её пальцами и повышает риск споткнуться."},{"type":"paragraph","text":"Примеряйте обе полупары и пройдитесь по магазину. Если отёчность появляется преимущественно вечером, полезно оценивать посадку во второй половине дня."},{"type":"paragraph","text":"Не рассчитывайте, что болезненно тесная обувь обязательно «разносится»."},{"type":"heading","text":"Выбирайте устойчивость"},{"type":"paragraph","text":"Для ежедневной ходьбы обычно удобнее невысокая устойчивая подошва, хорошее сцепление с поверхностью и надёжная фиксация стопы."},{"type":"paragraph","text":"Высокая узкая шпилька и неустойчивая платформа могут затруднять сохранение равновесия. Но и абсолютно плоская тонкая подошва подходит не всем: ориентируйтесь на удобство, поддержку и отсутствие боли."},{"type":"paragraph","text":"Домашние тапочки тоже должны держаться на ноге и не скользить."},{"type":"heading","text":"Обратите внимание на застёжку"},{"type":"paragraph","text":"Регулируемые шнурки, липучки или ремешки помогают адаптировать посадку при изменении объёма стопы. Застёжка должна фиксировать обувь, а не пережимать ногу."},{"type":"paragraph","text":"Если наклоняться стало трудно, используйте длинную ложку для обуви и обувайтесь сидя. Не стоит стоять на одной ноге, одновременно пытаясь попасть второй в ботинок."},{"type":"heading","text":"Нужны ли ортопедические стельки"},{"type":"paragraph","text":"Не всем. Боль в стопе, пятке или выраженная усталость могут быть поводом для оценки специалистом. Стельки подбирают под конкретную задачу, а не автоматически из-за беременности."},{"type":"paragraph","text":"Обувь не должна требовать болезненного «привыкания». Натирание, онемение пальцев и нарастание боли означают, что модель или размер не подходят."},{"type":"heading","text":"Когда дело не в обуви"},{"type":"paragraph","text":"Если обе стопы постепенно отекают к вечеру, обсудите это на приёме. Но внезапный выраженный отёк, особенно лица и рук, требует более быстрой оценки."},{"type":"paragraph","text":"Если одна нога стала заметно больше другой, болит или покраснела, не ограничивайтесь покупкой свободной пары — необходимо срочно исключить венозное осложнение."}]},{"id":"pregnancy-079","number":79,"week":27,"title":"Второй триместр заканчивается: что стоит успеть проверить и организовать","image":null,"blocks":[{"type":"paragraph","text":"Переход к третьему триместру — удобный момент, чтобы сверить медицинский план и бытовые задачи. Не нужно завершать все приготовления за одну неделю. Полезнее убедиться, что обследования назначены вовремя, результаты разобраны, а помощь организована."},{"type":"heading","text":"Проверьте обследование на гестационный диабет"},{"type":"paragraph","text":"Если диабет не выявляли раньше, стандартное окно для глюкозотолерантного теста — 24–28 недель. Если тест ещё не назначен или был перенесён, свяжитесь с врачом сейчас."},{"type":"paragraph","text":"Если результат уже готов, важно не просто сохранить его, а получить интерпретацию и дальнейшие рекомендации."},{"type":"heading","text":"Уточните результаты анализов крови"},{"type":"paragraph","text":"Проверьте, выполнен ли общий анализ крови второго триместра. Если назначено железо, уточните, когда оценивать ответ на лечение и как долго продолжать приём."},{"type":"paragraph","text":"Не отменяйте препарат только потому, что стало меньше усталости. Самочувствие и восстановление запасов железа не всегда меняются одновременно."},{"type":"heading","text":"При отрицательном резус-факторе обсудите ближайшие шаги"},{"type":"paragraph","text":"Обычно перед плановой профилактикой проверяют антирезусные антитела. Если они отсутствуют и есть показания, введение антирезусного иммуноглобулина планируют на 28–30 недель."},{"type":"paragraph","text":"Заранее уточните, где проводится процедура и какие результаты нужно иметь с собой."},{"type":"heading","text":"Вернитесь к заключению второго скрининга"},{"type":"paragraph","text":"Если врач рекомендовал контроль расположения плаценты, роста ребёнка или другой особенности, проверьте, есть ли запись и понятный срок."},{"type":"paragraph","text":"Не назначайте себе повторные УЗИ только из-за перехода в новый триместр. Дополнительные исследования должны отвечать на конкретный вопрос."},{"type":"heading","text":"Организуйте ближайший месяц"},{"type":"paragraph","text":"Запишите даты приёмов и обследований в один календарь. Если работаете, заранее узнайте порядок оформления отпуска по беременности и родам применительно к вашей ситуации."},{"type":"paragraph","text":"Обсудите с близкими помощь с тяжёлыми покупками, дорогой на приёмы и домашними делами."},{"type":"heading","text":"Сохраните контакты для срочной связи"},{"type":"paragraph","text":"Нужны номер наблюдающей организации и понятный маршрут обращения вечером или в выходной. Уточните это заранее, а не во время тревожного эпизода."},{"type":"paragraph","text":"Кровотечение, подтекание жидкости, регулярные болезненные сокращения, выраженная головная боль, нарушения зрения и уменьшение привычных шевелений не должны ждать следующего планового визита."},{"type":"paragraph","text":"На ближайшем приёме можно задать один объединяющий вопрос: «Какие обследования и действия нужны мне в следующие четыре недели и что должно стать поводом обратиться раньше?»"}]},{"id":"pregnancy-080","number":80,"week":27,"title":"Отрицательный резус-фактор: зачем врач контролирует антитела","image":null,"blocks":[{"type":"paragraph","text":"Отрицательный резус-фактор — особенность крови, а не заболевание. Он означает, что на поверхности эритроцитов отсутствует антиген D."},{"type":"paragraph","text":"Если у женщины резус-отрицательная кровь, а у ребёнка — резус-положительная, иногда требуется профилактика образования антител. Сама по себе разница резус-факторов ещё не означает, что возникло осложнение."},{"type":"heading","text":"Как могут появиться антитела"},{"type":"paragraph","text":"Небольшое количество эритроцитов ребёнка может попасть в кровоток матери во время беременности, родов, кровотечения, травмы живота или некоторых процедур."},{"type":"paragraph","text":"Иммунная система женщины может распознать антиген D как чужой и начать вырабатывать антитела. Некоторые из них способны проходить через плаценту и разрушать резус-положительные эритроциты ребёнка, вызывая анемию."},{"type":"paragraph","text":"Именно поэтому врач проверяет не только резус-фактор, но и наличие антител."},{"type":"heading","text":"Если антител нет"},{"type":"paragraph","text":"Это означает, что признаков соответствующей сенсибилизации на момент анализа не обнаружено."},{"type":"paragraph","text":"При наличии показаний российские рекомендации предусматривают плановое введение антирезусного иммуноглобулина в 28–30 недель. Препарат помогает предотвратить формирование собственного иммунного ответа женщины."},{"type":"paragraph","text":"Он не меняет резус-фактор матери или ребёнка. Необходимость профилактики зависит, в частности, от того, может ли ребёнок быть резус-положительным. Если его резус-отрицательная принадлежность достоверно установлена, тактика меняется."},{"type":"heading","text":"Если антитела обнаружены"},{"type":"paragraph","text":"Это не повод самостоятельно делать вывод о состоянии малыша. Врач уточняет, какие именно антитела выявлены, оценивает анамнез и назначает необходимое наблюдение."},{"type":"paragraph","text":"Антирезусный иммуноглобулин не является лечением уже сформировавшейся сенсибилизации. При значимых антителах может потребоваться наблюдение в специализированном центре и исследование кровотока у плода."},{"type":"paragraph","text":"После профилактического введения иммуноглобулина анализ иногда временно показывает пассивные антитела. Поэтому обязательно сообщайте дату и название введённого препарата."},{"type":"heading","text":"Когда нельзя ждать плановой процедуры"},{"type":"paragraph","text":"При кровотечении, травме живота или проведении инвазивного исследования сразу сообщите врачу об отрицательном резус-факторе. Может понадобиться дополнительная профилактика, даже если плановая процедура уже была."},{"type":"heading","text":"Что происходит после родов"},{"type":"paragraph","text":"Определяют резус-фактор ребёнка. Если он положительный и у матери нет соответствующей сенсибилизации, обычно требуется послеродовое введение иммуноглобулина, желательно в первые 72 часа."},{"type":"paragraph","text":"Сохраните в документах все результаты антител и сведения о введённых дозах: они важны и для текущей, и для будущих беременностей."}]},{"id":"pregnancy-081","number":81,"week":27,"title":"Какие документы и результаты обследований стоит хранить в отдельной папке","image":null,"blocks":[{"type":"paragraph","text":"Во время беременности сведения постепенно накапливаются в разных местах: часть остаётся в приложении лаборатории, часть — в бумажной карте, часть — в переписке с клиникой. Отдельная папка помогает быстро показать врачу важные данные и уменьшает вероятность ненужного повторения исследований."},{"type":"paragraph","text":"Главная задача — не собрать максимальное количество бумаги, а сделать информацию понятной и доступной."},{"type":"heading","text":"Основной медицинский документ"},{"type":"paragraph","text":"Если вам уже выдана обменная карта, храните её так, чтобы можно было взять на любой приём или поездку. Проверяйте, внесены ли туда значимые результаты и назначения."},{"type":"paragraph","text":"Если карта пока не выдана, уточните у наблюдающей организации, какой документ использовать для передачи сведений другим врачам."},{"type":"heading","text":"Что положить в медицинский раздел"},{"type":"paragraph","text":"Полезно собрать:"},{"type":"list-item","text":"заключения УЗИ и результаты пренатальных скринингов;"},{"type":"list-item","text":"результат глюкозотолерантного теста, если он проводился;"},{"type":"list-item","text":"анализы крови и мочи, особенно с отклонениями и последующим контролем;"},{"type":"list-item","text":"документ о группе крови и резус-факторе;"},{"type":"list-item","text":"результаты исследования антител;"},{"type":"list-item","text":"заключения профильных специалистов;"},{"type":"list-item","text":"выписки после госпитализаций и сведения о значимых операциях;"},{"type":"list-item","text":"информацию об аллергии и серьёзных реакциях на лекарства."},{"type":"paragraph","text":"Если раньше было кесарево сечение или другая операция на матке, сохраните соответствующую выписку."},{"type":"heading","text":"Составьте короткий список лекарств"},{"type":"paragraph","text":"Укажите название, дозу и время приёма каждого препарата. Добавьте витамины, добавки и средства, которые принимаете не ежедневно."},{"type":"paragraph","text":"Если вводили антирезусный иммуноглобулин, сохраните дату, дозу и документ о процедуре. При контроле давления или глюкозы приложите актуальный дневник."},{"type":"heading","text":"Как разложить результаты"},{"type":"paragraph","text":"Удобно выделить несколько разделов: «УЗИ», «Анализы», «Назначения», «Выписки». Внутри располагайте документы по датам."},{"type":"paragraph","text":"Сохраняйте полные заключения: фотография одной строки без даты, срока беременности и единиц измерения может оказаться бесполезной."},{"type":"heading","text":"Нужны ли электронные копии"},{"type":"paragraph","text":"Да, как резерв. Сделайте читаемые фотографии или сканы и сохраните их в защищённом месте. Желательно иметь доступ к ключевым файлам без интернета."},{"type":"paragraph","text":"При этом цифровая копия не всегда заменяет документ, который запрашивает конкретная организация."},{"type":"heading","text":"Что уточнить ближе к родам"},{"type":"paragraph","text":"У выбранного роддома запросите актуальный список документов для планового поступления и партнёрских родов. Требования могут различаться."},{"type":"paragraph","text":"При экстренной ситуации не тратьте время на поиск папки: сначала обращайтесь за медицинской помощью. Документы можно передать позже."}]},{"id":"pregnancy-082","number":82,"week":28,"title":"Третий триместр начался: что теперь меняется в вашем расписании","image":null,"blocks":[{"type":"paragraph","text":"С 28 недель начинается третий триместр. Это не означает, что нужно резко ограничивать обычную жизнь. Но медицинское наблюдение и повседневный график постепенно требуют больше внимания: появляются новые обследования, а привычные дела могут занимать больше времени."},{"type":"paragraph","text":"Удобнее составить план на ближайшие недели вместе с врачом."},{"type":"heading","text":"Приёмы и анализы"},{"type":"paragraph","text":"На визитах продолжают оценивать самочувствие, давление, рост матки и состояние ребёнка. Кратность посещений зависит от течения беременности и выявленных рисков."},{"type":"paragraph","text":"В третьем триместре предусмотрены повторные анализы крови и мочи, обследования на некоторые инфекции и необходимые консультации. Не все исследования нужно сдавать строго в день наступления 28 недель: уточните даты по своему плану."},{"type":"paragraph","text":"Если назначено лечение анемии, гестационного диабета или другого состояния, контроль может понадобиться чаще."},{"type":"heading","text":"Резус-профилактика"},{"type":"paragraph","text":"При отрицательном резус-факторе, отсутствии антител и наличии показаний на 28–30 недель планируют антирезусный иммуноглобулин. Если этот вопрос ещё не обсуждался, поднимите его на ближайшем приёме."},{"type":"heading","text":"УЗИ и КТГ"},{"type":"paragraph","text":"Переход в третий триместр сам по себе не означает, что УЗИ нужно делать каждую неделю. Срок планового исследования и необходимость дополнительных определяет врач."},{"type":"paragraph","text":"КТГ — запись сердцебиения ребёнка и маточной активности — обычно входит в наблюдение на более позднем сроке, часто начиная с 32 недель. По показаниям исследование могут назначить раньше."},{"type":"paragraph","text":"Нормальный результат обследования не отменяет обращения, если после него появились новые симптомы."},{"type":"heading","text":"Сон и движение"},{"type":"paragraph","text":"С этого срока рекомендуется засыпать на боку. Дневную нагрузку распределяйте так, чтобы между активными делами оставалось время на отдых."},{"type":"paragraph","text":"Если нет противопоказаний, сохраняйте прогулки и привычную адаптированную активность. Полный отказ от движения без назначения врача не является стандартной мерой подготовки к родам."},{"type":"heading","text":"Что добавить в календарь"},{"type":"paragraph","text":"Помимо приёмов, можно запланировать обсуждение роддома, подготовку партнёра и оформление необходимых документов. Не ставьте несколько утомительных задач на один день."},{"type":"paragraph","text":"Сохраните контакты для срочного обращения и уточните, куда ехать при уменьшении шевелений, кровотечении, подтекании вод или признаках преждевременных родов."},{"type":"paragraph","text":"Главное изменение расписания — больше гибкости. Если самочувствие меняется, бытовые планы можно переносить, а медицинскую оценку при тревожных симптомах — нет."}]},{"id":"pregnancy-083","number":83,"week":28,"title":"Шевеления малыша: как познакомиться с его привычным режимом активности","image":null,"blocks":[{"type":"paragraph","text":"К третьему триместру движения ребёнка обычно становятся хорошо узнаваемыми. Вы можете чувствовать толчки, перекаты, потягивания и отдельные выпирания под кожей."},{"type":"paragraph","text":"Для наблюдения важнее всего постепенно понять, как обычно двигается именно ваш малыш. Универсального количества шевелений, которое одинаково подходит всем детям и всем часам суток, нет."},{"type":"heading","text":"Что полезно замечать"},{"type":"paragraph","text":"Обращайте внимание, в какие части дня движения обычно заметнее, какими они бывают по силе и характеру. Для этого не нужно постоянно лежать и прислушиваться к животу."},{"type":"paragraph","text":"Если хотите, можно делать короткие заметки: «вечером обычно активнее», «после того как сажусь отдыхать, замечаю перекаты». Это способ познакомиться с ощущениями, а не обязательный диагностический дневник."},{"type":"paragraph","text":"Во время ходьбы и занятости движения легче пропустить. Но заметное изменение уже знакомой активности не следует автоматически объяснять тем, что день был насыщенным."},{"type":"heading","text":"Нужно ли считать движения"},{"type":"paragraph","text":"Рутинный подсчёт по одной таблице не обязателен для каждой беременной. Если врач рекомендовал конкретный метод, уточните, когда его применять и при каком результате обращаться."},{"type":"paragraph","text":"Даже достижение указанного в таблице числа не отменяет обращения, если движения стали явно слабее или существенно отличаются от привычных."},{"type":"heading","text":"Что меняется по мере роста"},{"type":"paragraph","text":"Характер движений может меняться: вместо резких пинков чаще ощущаются перекаты и потягивания. Но ребёнок не должен заметно меньше двигаться только потому, что ему «стало тесно»."},{"type":"paragraph","text":"Ощущать движения важно вплоть до родов. Они не должны исчезать в ожидании их начала."},{"type":"heading","text":"Если малыш двигается меньше"},{"type":"paragraph","text":"Свяжитесь с роддомом или наблюдающим медицинским специалистом сразу, если активность уменьшилась, прекратилась или заметно изменилась. Не ждите утра, следующего приёма или окончания условной нормы подсчёта."},{"type":"paragraph","text":"Не тратьте время на попытки проверить состояние сладким напитком, холодной водой или надавливанием на живот. Домашний допплер тоже не заменяет обследование: услышанное сердцебиение не позволяет оценить благополучие ребёнка."},{"type":"heading","text":"Что будет при обращении"},{"type":"paragraph","text":"Врач уточнит изменения, проверит состояние женщины и ребёнка и определит необходимые исследования — например, КТГ и УЗИ."},{"type":"paragraph","text":"Если после благополучной проверки ситуация повторилась, обращайтесь снова. Предыдущий нормальный результат не означает, что новое уменьшение движений можно игнорировать."}]},{"id":"pregnancy-084","number":84,"week":28,"title":"Почему в третьем триместре особенно полезно регулярно контролировать давление","image":null,"blocks":[{"type":"paragraph","text":"Повышение давления во время беременности может долго не ощущаться. Поэтому отсутствие головной боли и хорошее самочувствие не заменяют измерение тонометром."},{"type":"paragraph","text":"В третьем триместре контроль помогает своевременно выявить гипертензивные осложнения, включая преэклампсию. Это состояние связано не только с цифрами давления: оно может сопровождаться нарушением работы органов женщины и плаценты."},{"type":"heading","text":"Всем ли нужен домашний дневник"},{"type":"paragraph","text":"Давление измеряют на плановых приёмах. Домашний контроль особенно полезен, если раньше уже были повышенные значения, есть факторы риска или врач назначил наблюдение."},{"type":"paragraph","text":"Частоту измерений лучше согласовать. Одним женщинам достаточно проверки в определённые дни, другим рекомендуют измерять утром и вечером."},{"type":"paragraph","text":"Не нужно проверять давление каждые несколько минут при нормальных значениях и хорошем самочувствии."},{"type":"heading","text":"Как получить достоверный результат"},{"type":"paragraph","text":"Используйте плечевой тонометр, проверенный для применения у беременных, и подходящую по окружности руки манжету."},{"type":"paragraph","text":"Перед измерением спокойно посидите около пяти минут. Спина должна иметь опору, ноги не перекрещены, стопы стоят на полу. Положите руку так, чтобы манжета находилась примерно на уровне сердца."},{"type":"paragraph","text":"Не разговаривайте и не измеряйте поверх плотной одежды. Записывайте дату, время, показатели и необычные симптомы. При назначенном лечении отмечайте время приёма препарата."},{"type":"heading","text":"Какие значения требуют обращения"},{"type":"paragraph","text":"Если верхнее давление 140 мм рт. ст. или выше, либо нижнее 90 или выше, свяжитесь с врачом в тот же день. Повышения одного показателя достаточно, чтобы обратить внимание."},{"type":"paragraph","text":"При хорошем самочувствии можно спокойно повторить измерение, сохранив оба результата. Но не пытайтесь получить «хорошую цифру» десятками повторов."},{"type":"paragraph","text":"Если верхнее давление достигло 160, либо нижнее — 110, нужна неотложная помощь. Не ждите плановой консультации."},{"type":"heading","text":"Когда обращаться независимо от показаний тонометра"},{"type":"paragraph","text":"Сильная или необычная головная боль, нарушение зрения, боль вверху живота или под правыми рёбрами, выраженная одышка, внезапное ухудшение состояния требуют срочной оценки."},{"type":"paragraph","text":"Домашняя нормальная цифра не исключает все опасные причины симптомов."},{"type":"heading","text":"Чего не делать"},{"type":"paragraph","text":"Не принимайте чужие таблетки и не удваивайте назначенную дозу самостоятельно. Если препарат уже назначен, не отменяйте его из-за нескольких нормальных измерений: они могут означать, что лечение работает."},{"type":"paragraph","text":"Задача дневника — помочь врачу увидеть закономерность и вовремя скорректировать наблюдение, а не самостоятельно поставить диагноз."}]},{"id":"pregnancy-085","number":85,"week":29,"title":"У малыша уже есть свой режим: когда он чаще спит и бодрствует","image":null,"blocks":[{"type":"paragraph","text":"В течение суток у ребёнка чередуются периоды активности и покоя. Поэтому движения не должны ощущаться непрерывно каждую минуту."},{"type":"paragraph","text":"Но слово «режим» здесь условное. У малыша пока нет расписания, которое можно точно определить по часам или подстроить под мамин ночной сон."},{"type":"heading","text":"Как устроены спокойные периоды"},{"type":"paragraph","text":"Периоды сна у плода обычно длятся около 20–40 минут и редко превышают 90 минут. Эти цифры описывают физиологию, но не являются правилом домашнего ожидания."},{"type":"paragraph","text":"Если вы заметили, что ребёнок двигается существенно меньше обычного, не нужно самостоятельно решать, что он спит, и отсчитывать полтора часа до обращения."},{"type":"paragraph","text":"По отсутствию ощущений невозможно достоверно определить фазу сна и состояние малыша."},{"type":"heading","text":"Почему движения заметнее вечером"},{"type":"paragraph","text":"У многих детей периоды более выраженной активности приходятся на вторую половину дня и вечер. Кроме того, вечером мама чаще сидит или лежит спокойно и лучше замечает движения."},{"type":"paragraph","text":"Это не означает, что ребёнок обязательно будет бодрствовать ночью после рождения. По внутриутробной активности нельзя надёжно предсказать режим сна новорождённого."},{"type":"heading","text":"Можно ли “приучить” малыша спать ночью"},{"type":"paragraph","text":"Доказанного способа установить ему нужное расписание во время беременности нет. Не требуется специально будить ребёнка громкими звуками, надавливанием на живот или сладкой едой."},{"type":"paragraph","text":"Спокойное общение и прикосновения могут быть приятной частью ожидания малыша, но не служат тестом его здоровья и не заменяют наблюдение."},{"type":"heading","text":"Какие ощущения считать движениями"},{"type":"paragraph","text":"Вы можете замечать толчки, повороты и потягивания. Ритмичные однотипные подёргивания иногда связаны с икотой. Наличие икоты не заменяет оценку обычной двигательной активности."},{"type":"paragraph","text":"Не нужно пытаться по месту толчков самостоятельно определить точное положение ребёнка или сделать вывод о том, удобно ли ему."},{"type":"heading","text":"Что должно насторожить"},{"type":"paragraph","text":"Важен заметный отход от знакомой картины: ребёнок двигается реже, слабее, движения прекратились или существенно изменились."},{"type":"paragraph","text":"В такой ситуации свяжитесь с медицинским специалистом сразу. Не списывайте изменения на погоду, собственную усталость или то, что ребёнок «просто спокойный»."},{"type":"paragraph","text":"Если вечером малыш обычно активен, а сегодня вы замечаете выраженное отличие, не ложитесь спать в надежде проверить всё утром. Оценить состояние ребёнка можно с помощью медицинского обследования, а не предположения о его режиме."}]},{"id":"pregnancy-086","number":86,"week":29,"title":"Одышка при ходьбе и подъёме по лестнице: как распределять нагрузку","image":null,"blocks":[{"type":"paragraph","text":"Во время беременности потребность организма в кислороде увеличивается, гормоны влияют на дыхание, а растущая матка меняет положение диафрагмы. Поэтому привычный подъём по лестнице может требовать больше усилий."},{"type":"paragraph","text":"Небольшая постепенно возникшая одышка при нагрузке бывает физиологичной. Но новую, выраженную или нарастающую нехватку воздуха нельзя автоматически объяснять беременностью."},{"type":"heading","text":"Как выглядит более спокойная ситуация"},{"type":"paragraph","text":"Одышка возникает при быстрой ходьбе или подъёме, уменьшается после остановки и не сопровождается болью в груди, обмороком, выраженным сердцебиением или другими тревожными признаками."},{"type":"paragraph","text":"Даже такую жалобу полезно обсудить на приёме. Врач оценит, не связана ли она с анемией, заболеванием дыхательных путей или другой причиной."},{"type":"heading","text":"Снизьте темп заранее"},{"type":"paragraph","text":"Не начинайте движение в привычном быстром ритме, если уже знаете, что он вызывает дискомфорт. Идите медленнее, выбирайте маршрут с местами для отдыха и закладывайте больше времени на дорогу."},{"type":"paragraph","text":"На лестнице используйте перила и делайте остановки. Лифт — подходящий выбор, если подъём стал утомительным."},{"type":"paragraph","text":"Не несите одновременно тяжёлые пакеты: перенос веса заметно увеличивает нагрузку."},{"type":"heading","text":"Используйте разговорный ориентир"},{"type":"paragraph","text":"При умеренной активности вы должны сохранять возможность разговаривать. Если приходится прерывать короткую фразу ради вдоха, снизьте темп или остановитесь."},{"type":"paragraph","text":"Это ориентир для дозирования нагрузки, а не способ исключить заболевание."},{"type":"paragraph","text":"После остановки примите удобное положение с опорой, расслабьте плечи и дышите спокойно. Не пытайтесь компенсировать ощущение нехватки воздуха частыми максимально глубокими вдохами."},{"type":"heading","text":"Нужно ли полностью отказаться от движения"},{"type":"paragraph","text":"Если врач не установил ограничений, обычно полезнее уменьшить интенсивность и продолжительность отдельных нагрузок. Несколько коротких прогулок могут переноситься лучше одной длинной."},{"type":"paragraph","text":"Но сначала нужно оценить симптомы, если одышка появилась недавно или стала заметно сильнее."},{"type":"heading","text":"Когда помощь нужна срочно"},{"type":"paragraph","text":"Вызывайте скорую при внезапной сильной одышке, боли в груди, обмороке, кровохарканье или выраженном ухудшении состояния."},{"type":"paragraph","text":"Быстрой медицинской оценки требуют также нехватка воздуха в покое, невозможность лежать из-за удушья, свистящее дыхание, высокая температура или сочетание одышки с болью и отёком одной ноги."},{"type":"paragraph","text":"Не ждите следующего анализа крови и не начинайте самостоятельно железо или другие препараты, пытаясь угадать причину."}]},{"id":"pregnancy-087","number":87,"week":29,"title":"Как не перегружать себя делами перед рождением малыша","image":null,"blocks":[{"type":"paragraph","text":"Подготовка к рождению ребёнка легко превращается в длинный список: закончить работу, купить вещи, разобрать шкафы, выбрать роддом, всё вымыть и заранее приготовить еду. Но количество задач не должно определять допустимую нагрузку."},{"type":"paragraph","text":"В третьем триместре полезно планировать дела с учётом самочувствия и возможности восстановиться после них."},{"type":"heading","text":"Разделите задачи по необходимости"},{"type":"paragraph","text":"Выделите три группы:"},{"type":"list-item","text":"нужно решить до родов: медицинские вопросы, контакты, базовые вещи для ребёнка;"},{"type":"list-item","text":"можно поручить: покупки, тяжёлую уборку, сборку мебели;"},{"type":"list-item","text":"можно отложить: идеальное оформление комнаты, большие перестановки, необязательные проекты."},{"type":"paragraph","text":"Такой список помогает увидеть, что далеко не всё требует вашего личного участия."},{"type":"heading","text":"Делите работу на короткие этапы"},{"type":"paragraph","text":"Вместо уборки всей квартиры за один день выберите одну небольшую задачу. Между делами оставляйте время присесть, поесть, попить и оценить состояние."},{"type":"paragraph","text":"Если после обычных дел боль и усталость сохраняются до следующего дня, объём нагрузки стоит уменьшить."},{"type":"paragraph","text":"Не используйте тренировочные сокращения, головокружение или выраженную одышку как сигнал «потерпеть ещё немного и закончить»."},{"type":"heading","text":"Уберите задачи с риском падения"},{"type":"paragraph","text":"Мытьё высоких окон, работа на стремянке, перенос тяжёлых коробок и передвижение мебели лучше передать другим."},{"type":"paragraph","text":"При работе на полу учитывайте, сможете ли вы спокойно подняться. Если появляются боль в лобке или пояснице, меняйте положение и сокращайте время задачи."},{"type":"heading","text":"Сделайте просьбы о помощи конкретными"},{"type":"paragraph","text":"Вместо «мне нужна поддержка» можно договориться: «Ты заказываешь продукты по средам», «Сборку кроватки берёт на себя родственник», «На этот приём я еду с сопровождением»."},{"type":"paragraph","text":"Заранее обсудите и первые недели после родов: приготовление еды, бытовые дела, помощь со старшими детьми."},{"type":"heading","text":"Сохраняйте место для отдыха и обычной жизни"},{"type":"paragraph","text":"Отдых не обязан быть наградой за законченный список. Его стоит включать в расписание заранее."},{"type":"paragraph","text":"При отсутствии противопоказаний спокойные прогулки и приятная активность могут оставаться частью дня. Подготовка к ребёнку не требует постоянного лежания, но и не должна становиться марафоном на выносливость."},{"type":"heading","text":"Когда усталость требует внимания"},{"type":"paragraph","text":"Расскажите врачу о выраженной слабости, сердцебиении, головокружении или одышке при небольшой нагрузке. Если тревога заставляет постоянно что-то делать, мешает спать и не позволяет остановиться, это тоже повод обратиться за поддержкой."},{"type":"paragraph","text":"Количество выполненных дел не определяет вашу готовность быть мамой."}]},{"id":"pregnancy-088","number":88,"week":30,"title":"План родов: что это такое и почему его полезно составить заранее","image":null,"blocks":[{"type":"paragraph","text":"План родов — короткое описание ваших пожеланий, важных обстоятельств и вопросов к медицинской команде. Он помогает обсудить варианты заранее, когда есть время спокойно разобраться в информации."},{"type":"paragraph","text":"Это не обещание, что роды пройдут по определённому сценарию. Обстоятельства могут измениться, а ваши предпочтения — поменяться уже в процессе."},{"type":"heading","text":"Что полезно включить"},{"type":"paragraph","text":"Начните с действительно важного:"},{"type":"list-item","text":"кого вы хотите видеть рядом;"},{"type":"list-item","text":"какие способы поддержки помогают вам успокоиться;"},{"type":"list-item","text":"хотите ли свободно двигаться и менять положения;"},{"type":"list-item","text":"какие варианты обезболивания хотели бы обсудить;"},{"type":"list-item","text":"есть ли особенности здоровья, аллергии или неприятный опыт обследований;"},{"type":"list-item","text":"что для вас важно в общении с персоналом;"},{"type":"list-item","text":"какие пожелания есть к первым минутам после рождения ребёнка."},{"type":"paragraph","text":"Например: «Пожалуйста, объясняйте, что вы собираетесь делать», «Мне важно предупреждение перед прикосновением», «Если возможно, я хочу контакт кожа к коже после рождения»."},{"type":"heading","text":"Как сформулировать пожелания"},{"type":"paragraph","text":"Лучше писать коротко и конкретно. Одна страница с несколькими приоритетами обычно удобнее длинного документа с множеством запретов."},{"type":"paragraph","text":"Вместо категоричного «никаких вмешательств» полезнее обсудить: какие вмешательства могут понадобиться, при каких обстоятельствах и какие есть альтернативы."},{"type":"paragraph","text":"Можно заранее подготовить вопросы: «Зачем это нужно?», «Что изменится, если немного подождать?», «Какие преимущества и риски именно в моей ситуации?»"},{"type":"heading","text":"Обсудите план с роддомом"},{"type":"paragraph","text":"Возможности учреждений различаются: наличие индивидуальных боксов, душа, беспроводного мониторинга и правила сопровождения лучше уточнять заранее."},{"type":"paragraph","text":"Если предполагается кесарево сечение или есть особенности беременности, план тоже полезен. В нём можно обсудить обезболивание, присутствие сопровождающего там, где это возможно, контакт с ребёнком и помощь после операции."},{"type":"heading","text":"Оставьте место для изменений"},{"type":"paragraph","text":"Во время схваток вы можете захотеть другой способ обезболивания, отказаться от прикосновений или выбрать положение, которое раньше не нравилось."},{"type":"paragraph","text":"Изменение решения нормально. План нужен для общения, а не для оценки того, насколько «правильно» вы родили."},{"type":"heading","text":"Когда начать"},{"type":"paragraph","text":"На 30-й неделе можно составить черновик и обсудить его на ближайшей консультации. Ближе к родам — уточнить с учётом состояния здоровья и возможностей учреждения."},{"type":"paragraph","text":"Покажите документ партнёру, если он будет рядом. Его задача — помогать озвучивать ваши пожелания и поддерживать контакт с командой, а не спорить с врачами вместо вас."}]},{"id":"pregnancy-089","number":89,"week":30,"title":"Позы в схватках: какие варианты стоит попробовать ещё во время беременности","image":null,"blocks":[{"type":"paragraph","text":"Во время схваток положение тела может влиять на ощущения и помогать переносить нагрузку. При неосложнённых родах обычно поощряются подвижность и выбор удобного положения."},{"type":"paragraph","text":"Но универсальной «лучшей позы» нет. Одной женщине хочется ходить, другой — опираться на кровать, третьей — лежать на боку. Предпочтения могут меняться по ходу родов."},{"type":"heading","text":"Зачем пробовать заранее"},{"type":"paragraph","text":"Спокойное знакомство помогает понять, где нужна опора, какие движения удобны для спины и как партнёр может помочь."},{"type":"paragraph","text":"Во время беременности это именно примерка положений. Не нужно имитировать сильные схватки, натуживаться, долго удерживать неудобную позу или пытаться стимулировать роды."},{"type":"heading","text":"Стоя с опорой"},{"type":"paragraph","text":"Поставьте стопы устойчиво и обопритесь руками или предплечьями на надёжную поверхность. Можно немного наклониться вперёд, если так удобнее."},{"type":"paragraph","text":"Попробуйте мягко переносить вес с ноги на ногу. Не делайте глубоких движений через боль и не используйте опору, которая может сдвинуться."},{"type":"heading","text":"На четвереньках"},{"type":"paragraph","text":"Расположитесь на мягкой нескользкой поверхности. Под колени можно положить подкладку. Найдите комфортное положение спины, не провисая в пояснице."},{"type":"paragraph","text":"Если болят запястья, вариант опоры на предплечья или более высокую поверхность лучше подобрать со специалистом."},{"type":"heading","text":"Лёжа на боку"},{"type":"paragraph","text":"Эта поза подходит для отдыха. Поддержите голову, а между ногами при необходимости положите подушку. Во время родов партнёр или акушерка могут помочь расположить верхнюю ногу."},{"type":"paragraph","text":"Лежать на боку — полноценный вариант, а не признак недостаточной активности."},{"type":"heading","text":"Сидя с поддержкой"},{"type":"paragraph","text":"Можно попробовать устойчивый стул. Фитбол допустим, если вы уверенно им пользуетесь, стопы полностью опираются на пол и рядом есть надёжная поддержка. Прыжки не нужны."},{"type":"paragraph","text":"Если есть боль в лобке или тазовом поясе, широкое разведение ног и глубокие приседания могут усиливать симптомы."},{"type":"heading","text":"Что изменится в родах"},{"type":"paragraph","text":"КТГ, внутривенные препараты или эпидуральное обезболивание могут потребовать адаптации движений. При сниженной чувствительности и силе ног нельзя вставать без разрешения и помощи персонала."},{"type":"paragraph","text":"Иногда медицинская ситуация требует определённого положения. Уточняйте, какие варианты доступны сейчас."},{"type":"paragraph","text":"Заранее достаточно познакомиться с несколькими удобными позами. Они могут помогать справляться с ощущениями, но не гарантируют определённую скорость раскрытия или отсутствие вмешательств."}]},{"id":"pregnancy-090","number":90,"week":30,"title":"Дыхание в родах: почему лучше потренироваться заранее","image":null,"blocks":[{"type":"paragraph","text":"Во время сильных ощущений человек нередко задерживает дыхание, напрягает плечи и начинает дышать слишком часто. Знакомая спокойная дыхательная практика может помочь заметить это и вернуть более удобный ритм."},{"type":"paragraph","text":"Дыхание — один из способов поддержки в родах. Оно не гарантирует безболезненные схватки и не заменяет медицинское обезболивание, если оно необходимо или вы его хотите."},{"type":"heading","text":"Что даёт предварительная практика"},{"type":"paragraph","text":"Заранее проще понять, как расслаблять лицо, плечи и кисти, не делать чрезмерно глубоких вдохов и возвращаться к обычному дыханию после напряжения."},{"type":"paragraph","text":"Навык не требует сложной схемы. В родах легче пользоваться тем, что вы уже попробовали и что не вызывает дискомфорта."},{"type":"heading","text":"Простой вариант для знакомства"},{"type":"paragraph","text":"Устройтесь сидя с опорой или лёжа на боку."},{"type":"paragraph","text":"Сделайте спокойный вдох через нос, затем мягкий свободный выдох через рот или нос — как удобнее. Не старайтесь набрать максимум воздуха."},{"type":"paragraph","text":"Можно несколько циклов понаблюдать, чтобы выдох был плавным и не сопровождался напряжением. Затем продолжайте дышать обычно."},{"type":"paragraph","text":"Для начала достаточно нескольких минут. Счёт необязателен: если он мешает или заставляет терпеть нехватку воздуха, откажитесь от него."},{"type":"heading","text":"Как это может пригодиться в схватке"},{"type":"paragraph","text":"В начале схватки попробуйте расслабить плечи и найти переносимый ритм. На пике задача — продолжать дышать, а не идеально соблюдать цифры. После схватки вернитесь к обычному дыханию и отдыху."},{"type":"paragraph","text":"Партнёр может тихо напоминать о расслаблении или дышать рядом в спокойном темпе, если вам это помогает."},{"type":"paragraph","text":"Не всем нравятся голосовые подсказки. Обсудите заранее, какая поддержка приятна, а какая раздражает."},{"type":"heading","text":"Каких ошибок избегать"},{"type":"paragraph","text":"Частое и слишком глубокое дыхание может вызвать головокружение, покалывание в пальцах или вокруг рта. Если это произошло, прекратите упражнение, примите устойчивое положение и вернитесь к обычному дыханию. Если симптомы не проходят, обратитесь за помощью."},{"type":"paragraph","text":"Не практикуйте длительные задержки дыхания и натуживание во время беременности."},{"type":"heading","text":"А как дышать в потугах"},{"type":"paragraph","text":"Тактика зависит от стадии родов, наличия позыва, обезболивания и состояния ребёнка. Её обсуждают с акушеркой и врачом непосредственно в процессе. Самостоятельно «тренировать потуги» на 30-й неделе не нужно."},{"type":"paragraph","text":"Вам не требуется освоить единственную правильную технику. Полезнее иметь несколько простых способов успокоиться и помнить, что попросить дополнительное обезболивание можно независимо от подготовки."}]},{"id":"pregnancy-091","number":91,"week":31,"title":"Когда начинать собирать сумку в роддом","image":null,"blocks":[{"type":"paragraph","text":"На 31-й неделе удобно составить список и постепенно собрать вещи, которые не нужны каждый день. Единого медицинского срока для готовности сумки нет. При неосложнённой беременности практичный ориентир — закончить основные сборы примерно к 36–37 неделям. Если возможна более ранняя госпитализация, ориентируйтесь на план врача."},{"type":"heading","text":"Сначала узнайте правила роддома"},{"type":"paragraph","text":"Уточните, что учреждение выдаёт маме и ребёнку, какие вещи разрешены в родильном отделении и как передают дополнительные пакеты. Требование прозрачной сумки, разрешённая одежда и количество личных вещей могут различаться."},{"type":"paragraph","text":"Отдельно спросите о документах и подготовке сопровождающего. Список из социальных сетей может включать ненужные покупки и не учитывать правила выбранного роддома."},{"type":"heading","text":"Разделите вещи на три набора"},{"type":"list-item","text":"На поступление и роды: документы, телефон, зарядка, моющиеся тапочки, разрешённая удобная одежда, вода и предметы личного комфорта."},{"type":"list-item","text":"На послеродовое пребывание: гигиенические принадлежности, бельё, послеродовые прокладки, одежда для кормления, согласованные вещи для ребёнка."},{"type":"list-item","text":"На выписку: одежда по погоде для вас и малыша. Этот набор можно оставить дома, если его привезут позже."},{"type":"paragraph","text":"Так сопровождающему будет проще найти нужное, а вам не придётся разбирать большой чемодан между схватками."},{"type":"heading","text":"Оставьте список того, что добавить в последний момент"},{"type":"paragraph","text":"Обычно это документы, которыми вы продолжаете пользоваться, очки, телефон и ежедневно принимаемые лекарства. Препараты возьмите в оригинальных упаковках вместе со списком дозировок. После поступления сообщите о них персоналу: привычную схему иногда нужно согласовать с процедурами."},{"type":"paragraph","text":"Покажите близкому человеку, где лежит сумка, и сохраните адрес приёмного отделения. Проверять готовность ежедневно не требуется: достаточно вернуться к списку ближе к предполагаемой госпитализации."},{"type":"heading","text":"Если роды начались раньше сборов"},{"type":"paragraph","text":"Не откладывайте обращение ради покупок и упаковки. При кровотечении, подозрении на отхождение вод, уменьшении шевелений или регулярных сокращениях до 37 недель сначала нужна медицинская оценка. Вещи можно привезти позже."}]},{"id":"pregnancy-092","number":92,"week":31,"title":"Как подготовить партнёра к совместным родам","image":null,"blocks":[{"type":"paragraph","text":"Партнёр на родах нужен прежде всего для постоянной поддержки. Ему не требуется выполнять обязанности акушерки или знать все медицинские термины. Полезнее понимать ход родов, ваши предпочтения и простые способы помощи."},{"type":"paragraph","text":"Присутствие должно быть добровольным для обоих. Сопровождающим может быть не только отец ребёнка: обсудите с роддомом, кого вы можете пригласить."},{"type":"heading","text":"Разберитесь в процессе вместе"},{"type":"paragraph","text":"Изучите, чем начало родов отличается от активных схваток, что происходит в потугах и после рождения малыша. Обсудите возможное обезболивание, индукцию и кесарево сечение. Знание разных вариантов уменьшает растерянность, если первоначальный план изменится."},{"type":"paragraph","text":"Партнёру важно заранее узнать, как вызвать персонал и какие изменения сразу сообщать: кровотечение, резкое ухудшение самочувствия, сильный позыв тужиться, необычную постоянную боль."},{"type":"heading","text":"Потренируйте конкретную помощь"},{"type":"paragraph","text":"Попробуйте несколько действий: подать воду, помочь сменить положение, поддержать подушки, мягко помассировать поясницу. Уточняйте согласие перед прикосновением. То, что приятно сейчас, в родах может раздражать."},{"type":"paragraph","text":"Договоритесь о коротких подсказках. Например: «Я рядом», «Хочешь сменить позу?», «Позвать акушерку?» Команды «не кричи» и «терпи» обычно не помогают. Дыхание можно спокойно показывать своим примером, если женщина этого хочет."},{"type":"heading","text":"Обсудите общение с командой"},{"type":"paragraph","text":"Партнёр может напомнить о ваших пожеланиях, попросить объяснить назначение и помочь услышать ответ. Решения обсуждают с самой женщиной, когда она способна их принимать. Сопровождающий не должен самостоятельно отменять помощь или спорить от её имени вопреки её желанию."},{"type":"heading","text":"Подготовьте организационные детали"},{"type":"paragraph","text":"Уточните необходимые обследования, документы, одежду и возможность присутствовать при разных сценариях родов. Соберите воду, перекус и зарядку для сопровождающего. Ему тоже понадобятся короткие перерывы."},{"type":"paragraph","text":"Если партнёру становится дурно, нужно сесть и сообщить персоналу, а не пытаться выстоять любой ценой. Заранее допустимо договориться, что он остаётся у изголовья или выходит на отдельном этапе. Качество поддержки не определяется тем, увидел ли он все медицинские процедуры."}]},{"id":"pregnancy-093","number":93,"week":31,"title":"Как выбрать роддом: 7 вопросов, которые действительно стоит задать","image":null,"blocks":[{"type":"paragraph","text":"Комфорт палаты важен, но при выборе роддома сначала стоит оценить медицинские возможности и организацию помощи. Начните с врача, который ведёт беременность: при некоторых состояниях нужен стационар определённого уровня, даже если другой находится ближе или выглядит уютнее."},{"type":"heading","text":"1. Подходит ли роддом для моей беременности?"},{"type":"paragraph","text":"Назовите значимые особенности: многоплодие, диабет, заболевания сердца, предыдущие операции на матке. Спросите, есть ли необходимая помощь новорождённым и что происходит, если женщине или ребёнку требуется перевод."},{"type":"heading","text":"2. Как поступать планово и экстренно?"},{"type":"paragraph","text":"Уточните адрес входа ночью, контакт приёмного отделения, порядок направления и запасной маршрут. Время в дороге и доступность помощи важнее рейтинга, основанного на нескольких отзывах."},{"type":"heading","text":"3. Какие варианты обезболивания доступны?"},{"type":"paragraph","text":"Спросите об эпидуральной анальгезии, работе анестезиолога и немедикаментозной поддержке. Доступность метода не означает, что он подходит всем: противопоказания оценивают индивидуально."},{"type":"heading","text":"4. Как организованы партнёрские роды?"},{"type":"paragraph","text":"Кто может сопровождать, какие нужны документы и обследования, разрешено ли присутствие во время индукции? Отдельно уточните условия при кесаревом сечении и возможность замены сопровождающего."},{"type":"heading","text":"5. Можно ли двигаться и выбирать положение?"},{"type":"paragraph","text":"Узнайте о душе, фитболе, опорах и вариантах мониторинга. Полезен конкретный ответ: как обеспечивают движение, если необходима КТГ или установлена капельница."},{"type":"heading","text":"6. Что делают сразу после рождения?"},{"type":"paragraph","text":"Обсудите контакт «кожа к коже», помощь с первым кормлением и совместное пребывание. Спросите, как эти возможности адаптируют, если маме или малышу нужна дополнительная помощь."},{"type":"heading","text":"7. Как объясняют вмешательства и поддерживают после родов?"},{"type":"paragraph","text":"Попросите рассказать, как обсуждают индукцию, амниотомию и изменение способа родоразрешения. Кто поможет с кормлением ночью? Как организован уход после операции?"},{"type":"heading","text":"Как сравнивать ответы"},{"type":"paragraph","text":"Запишите ответы двух-трёх подходящих учреждений в одинаковом порядке. Отзывы полезны для поиска вопросов, но не показывают ваши персональные риски. Процент кесаревых сечений тоже нельзя оценивать отдельно от того, насколько сложные беременности принимает стационар. Приоритет — подходящая медицинская помощь, понятное общение и реалистичный маршрут поступления."}]},{"id":"pregnancy-094","number":94,"week":32,"title":"УЗИ третьего триместра: кому и зачем его назначают","image":null,"blocks":[{"type":"paragraph","text":"Позднее УЗИ помогает оценить рост малыша и уточнить обстоятельства, важные для дальнейшего наблюдения и родов. Оно не повторяет полностью задачи первого и второго скринингов: часть вопросов становится актуальной именно ближе к концу беременности."},{"type":"paragraph","text":"В российских клинических рекомендациях «Нормальная беременность» предусмотрено плановое УЗИ в 34–35 недель и 6 дней. На 32-й неделе удобно проверить запись. Более раннее или дополнительное исследование могут назначить по индивидуальным показаниям."},{"type":"heading","text":"Что оценивают"},{"type":"paragraph","text":"Врач измеряет отдельные части тела ребёнка и рассчитывает предполагаемую массу. Также оценивают количество околоплодных вод, расположение плаценты, положение и предлежание малыша. Некоторые особенности строения органов становятся заметны позже, поэтому анатомию тоже осматривают в доступном объёме."},{"type":"paragraph","text":"При необходимости исследуют кровоток с помощью допплерометрии. Она отвечает на определённые клинические вопросы и не заменяет остальные измерения."},{"type":"heading","text":"Когда УЗИ может понадобиться дополнительно"},{"type":"paragraph","text":"Поводами могут стать подозрение на замедленный рост, несоответствие размеров матки сроку, особенности плаценты, нарушения давления, диабет или другие осложнения. При изменении шевелений сначала нужна своевременная медицинская оценка: врач определит, какие исследования требуются прямо сейчас."},{"type":"paragraph","text":"Самостоятельно ждать даты планового УЗИ при тревожных симптомах нельзя."},{"type":"heading","text":"Как подготовиться"},{"type":"paragraph","text":"Обычно специальная диета, голодание и наполненный мочевой пузырь не нужны, если клиника не дала иных указаний. Возьмите предыдущие заключения, чтобы врач мог оценить динамику. Уточните цель: плановая оценка, контроль роста или проверка конкретной особенности."},{"type":"heading","text":"Какие вопросы задать после исследования"},{"type":"paragraph","text":"Спросите, соответствует ли рост сроку, всё ли удалось осмотреть и требуется ли контроль. Если в заключении есть отклонение, важно понять его значение вместе с акушером-гинекологом."},{"type":"paragraph","text":"Одно УЗИ не предсказывает точный день родов, не гарантирует отсутствие всех заболеваний и не определяет способ родоразрешения по единственному показателю. Заключение оценивают вместе с течением беременности, предыдущими исследованиями и вашим состоянием."}]},{"id":"pregnancy-095","number":95,"week":32,"title":"Вес малыша по УЗИ: почему это всегда приблизительная цифра","image":null,"blocks":[{"type":"paragraph","text":"Запись «предполагаемая масса плода» означает расчёт, а не взвешивание. Аппарат использует измерения головы, живота и бедренной кости, подставляя их в специальную формулу. Поэтому результат вроде 2300 г не означает, что масса известна с точностью до грамма."},{"type":"paragraph","text":"Погрешность может составлять сотни граммов, особенно ближе к родам. Она зависит от условий измерения и особенностей самого ребёнка."},{"type":"heading","text":"Откуда появляется неточность"},{"type":"paragraph","text":"Малыш может лежать неудобно для нужной проекции. Контуры органов иногда видны хуже из-за положения, количества вод и особенностей тканей. Даже небольшая разница в измерении окружности живота влияет на итоговый расчёт."},{"type":"paragraph","text":"Кроме того, формула описывает усреднённую связь размеров с массой. Дети с одинаковой окружностью головы не обязательно имеют одинаковые пропорции тела."},{"type":"heading","text":"Почему врач смотрит на процентили"},{"type":"paragraph","text":"Процентиль показывает положение результата среди значений для данного срока. Например, 10-й процентиль означает, что примерно у 10 из 100 детей в используемой таблице показатель ниже, а у остальных — выше."},{"type":"paragraph","text":"Низкий процентиль ещё не доказывает задержку роста, а высокий сам по себе не определяет способ родов. Важно учитывать окружность живота, изменения показателей со временем, кровоток, количество вод и состояние женщины."},{"type":"heading","text":"Динамика полезнее соревнования цифр"},{"type":"paragraph","text":"Повторное исследование назначают через интервал, который позволяет оценить реальный рост. УЗИ через день ради проверки прибавки обычно малоинформативно: небольшие различия могут отражать погрешность."},{"type":"paragraph","text":"Если два специалиста указали разную массу, покажите оба заключения наблюдающему врачу. Самостоятельно выбирать более приятную цифру или усреднять результаты не нужно."},{"type":"heading","text":"Что делать с заключением «крупный» или «маловесный»"},{"type":"paragraph","text":"Уточните, насколько результат отличается от ожидаемого, требуется ли контроль и меняется ли план наблюдения. Не пытайтесь «уменьшить ребёнка» голоданием или «откормить» его сладким. При нарушениях роста нужна оценка причины, а питание подбирают с учётом здоровья матери."},{"type":"paragraph","text":"Предполагаемая масса — полезная часть медицинской картины. Но решать вопрос об индукции или кесаревом сечении только по одной цифре без обсуждения остальных обстоятельств неправильно."}]},{"id":"pregnancy-096","number":96,"week":32,"title":"Живот маленький или очень большой: почему сравнивать себя с другими беременными бессмысленно","image":null,"blocks":[{"type":"paragraph","text":"На одинаковом сроке живот может выглядеть совершенно по-разному. На его форму влияют рост женщины, длина туловища, состояние мышц брюшной стенки, количество предыдущих беременностей и положение ребёнка. Одежда, ракурс фотографии и время суток дополнительно меняют впечатление."},{"type":"paragraph","text":"По внешнему виду нельзя надёжно определить массу малыша, количество вод или срок родов. «У меня было больше» — не медицинский критерий."},{"type":"heading","text":"Что измеряет врач"},{"type":"paragraph","text":"На приёмах оценивают рост матки, в том числе высоту её дна — расстояние от области лобковой кости до верхней границы матки. Результат сопоставляют со сроком и предыдущими измерениями."},{"type":"paragraph","text":"Это ориентир для наблюдения, а не самостоятельный диагноз. На точность влияют особенности телосложения, миомы, многоплодие и другие обстоятельства. Если возникает вопрос о росте ребёнка или количестве вод, врач назначает УЗИ."},{"type":"heading","text":"Почему большой живот не всегда означает крупного ребёнка"},{"type":"paragraph","text":"Объём живота складывается из нескольких составляющих: матки, малыша, околоплодных вод и тканей самой женщины. Иногда внешнее впечатление связано с положением ребёнка или более растянутой брюшной стенкой."},{"type":"paragraph","text":"При действительно ускоренном увеличении матки нужно выяснять причину. Но ставить диагноз «многоводие» по фотографии нельзя."},{"type":"heading","text":"Маленький живот тоже оценивают по данным"},{"type":"paragraph","text":"У высокой женщины с длинным туловищем беременность может быть менее заметна. При этом миниатюрный живот не гарантирует маленького ребёнка и не исключает необходимость планового наблюдения."},{"type":"paragraph","text":"Если врач видит отставание измерений или изменение темпа роста, важно выполнить назначенное обследование. Успокаиваться только словами «у всех по-разному» в такой ситуации тоже не стоит."},{"type":"heading","text":"На что ориентироваться дома"},{"type":"paragraph","text":"Сохраняйте обычное наблюдение за шевелениями и посещайте назначенные приёмы. Ежедневно измерять живот сантиметровой лентой не нужно: домашние колебания легко интерпретировать неправильно."},{"type":"paragraph","text":"При уменьшении движений, подтекании жидкости, кровотечении или сильной боли обращайтесь сразу, независимо от размера живота. Если тревогу вызывают комментарии окружающих, можно ответить: «Рост ребёнка оценивает врач по обследованиям». Дополнительные оправдания не обязательны."}]},{"id":"pregnancy-097","number":97,"week":33,"title":"Тренировочные схватки: как использовать их для тренировки дыхания и расслабления","image":null,"blocks":[{"type":"paragraph","text":"Краткое нерегулярное напряжение матки может напомнить о навыках расслабления. Но специально вызывать сокращения, усиливать нагрузку или ждать их ради тренировки не нужно. Дыхание можно спокойно практиковать и без каких-либо ощущений в животе."},{"type":"paragraph","text":"На 33-й неделе главный вопрос — не техника дыхания, а отсутствие признаков преждевременных родов."},{"type":"heading","text":"Сначала оцените характер ощущений"},{"type":"paragraph","text":"Типичные тренировочные сокращения появляются нерегулярно, не становятся последовательно сильнее и чаще, проходят самостоятельно. Обычно это напряжение или стягивание, а не нарастающая боль."},{"type":"paragraph","text":"Если сокращения повторяются ритмично, сопровождаются болью, давлением вниз, необычной болью в пояснице, кровью или водянистыми выделениями, свяжитесь с роддомом сразу. Не проверяйте, удастся ли «продышать» симптомы. До 37 недель не следует ждать интервалов, которые обсуждали для доношенных родов."},{"type":"heading","text":"Как потренироваться при единичном безболезненном эпизоде"},{"type":"paragraph","text":"Остановитесь и примите устойчивое удобное положение: сядьте с опорой или лягте на бок. Отпустите плечи, разожмите кисти, расслабьте челюсть."},{"type":"paragraph","text":"Сделайте обычный спокойный вдох и свободный выдох. Не набирайте воздух до предела и не задерживайте дыхание. Можно мысленно сопровождать выдох словом «отпускаю», если это помогает, но специальная формула не обязательна."},{"type":"paragraph","text":"После расслабления живота вернитесь к обычному дыханию. Нескольких циклов достаточно: тренировка не должна превращаться в испытание выносливости."},{"type":"heading","text":"Что считать полезным результатом"},{"type":"paragraph","text":"Вы заметили, где непроизвольно напряглись, и смогли немного уменьшить это напряжение. Цель не в том, чтобы дыханием остановить маточные сокращения или повлиять на шейку матки. У дыхательной практики нет такой диагностической или лечебной функции."},{"type":"paragraph","text":"Если кружится голова или покалывают пальцы, прекратите упражнение. Слишком частое и глубокое дыхание может вызывать такие ощущения. При сохраняющемся недомогании нужна медицинская оценка."},{"type":"heading","text":"Можно ли привлечь партнёра"},{"type":"paragraph","text":"Попросите его тихо напомнить о расслабленных плечах или помочь устроиться удобнее. Заранее скажите, нужны ли прикосновения. Если сокращения изменились или вызывают сомнения, следующая задача партнёра — помочь связаться с медицинским специалистом, а не продолжать тренировку."}]},{"id":"pregnancy-098","number":98,"week":33,"title":"Появилось молозиво: нужно ли готовить грудь к кормлению","image":null,"blocks":[{"type":"paragraph","text":"На белье появились небольшие желтоватые или прозрачные следы? Во время беременности грудь может выделять молозиво — первое молоко. Оно содержит питательные и защитные компоненты, которые будут нужны ребёнку после рождения."},{"type":"paragraph","text":"У одних женщин выделения заметны заранее, у других до родов их нет. Ни количество капель, ни их отсутствие не позволяют предсказать будущий объём молока."},{"type":"heading","text":"Что делать сейчас"},{"type":"paragraph","text":"Обычно достаточно привычного душа, мягкого белья и при необходимости впитывающих вкладышей. Меняйте их, когда они становятся влажными. Не нужно выдавливать молозиво, чтобы проверить, «работает ли грудь»."},{"type":"paragraph","text":"Если появились боль, покраснение, уплотнение или необычные выделения, особенно кровянистые и только из одной груди, расскажите врачу. Не стоит автоматически объяснять любые изменения подготовкой к кормлению."},{"type":"heading","text":"Нужно ли закалять соски"},{"type":"paragraph","text":"Растирать их жёстким полотенцем, вытягивать, обрабатывать спиртом и натирать до чувствительности не требуется. Повреждение кожи не делает кормление легче."},{"type":"paragraph","text":"Плоские или втянутые соски тоже не означают, что грудное вскармливание невозможно. Если их форма вас тревожит, заранее обсудите помощь с прикладыванием, особенно при прежних операциях на груди или сложностях с кормлением старшего ребёнка."},{"type":"heading","text":"А можно ли заранее сцеживать молозиво"},{"type":"paragraph","text":"Дородовой сбор молозива — отдельная практика, которую иногда обсуждают ближе к доношенному сроку, например при риске низкой глюкозы у новорождённого. Это не обязательная подготовка для каждой женщины."},{"type":"paragraph","text":"На 33-й неделе самостоятельно начинать сцеживание руками или молокоотсосом не нужно. Срок, допустимость и хранение обсуждают с наблюдающей командой: стимуляция сосков может сопровождаться сокращениями матки."},{"type":"heading","text":"Какая подготовка действительно пригодится"},{"type":"paragraph","text":"Узнайте, кто поможет с первым прикладыванием в роддоме и куда обратиться после выписки. Полезно заранее разобраться в признаках эффективного сосания, ранних сигналах голода и оценке достаточности питания."},{"type":"paragraph","text":"Сохраните контакты специалиста по грудному вскармливанию. После рождения болезненность, повреждение соска или трудности с захватом — повод попросить помощи, а не терпеть до появления трещин. Учиться кормлению можно постепенно, вместе с ребёнком и поддерживающей командой."}]},{"id":"pregnancy-099","number":99,"week":33,"title":"Что взять малышу в роддом и какие вещи на самом деле не понадобятся","image":null,"blocks":[{"type":"paragraph","text":"Для первых дней ребёнку нужен небольшой набор вещей. Его состав зависит от того, что предоставляет роддом: в одном отделении выдают пелёнки и одежду, в другом предлагают использовать свои. Начните со списка учреждения, а затем добавьте необходимое для вашего удобства."},{"type":"paragraph","text":"Собирать запас на весь первый месяц не требуется. Заранее договоритесь, кто сможет привезти пополнение."},{"type":"heading","text":"Базовый набор"},{"type":"list-item","text":"Подгузники подходящего размера небольшим запасом."},{"type":"list-item","text":"Несколько простых комплектов одежды, если свои вещи разрешены."},{"type":"list-item","text":"Пелёнки, если они нужны по правилам отделения."},{"type":"list-item","text":"Средства для очищения кожи, согласованные с персоналом."},{"type":"list-item","text":"Отдельный комплект на выписку по погоде."},{"type":"paragraph","text":"Выбирайте одежду, которую легко расстегнуть для осмотра и смены подгузника. Крупные декоративные элементы, тугие резинки и сложные застёжки в первые дни скорее мешают. Новые вещи постирайте и хорошо высушите."},{"type":"heading","text":"Чего не нужно покупать заранее для палаты"},{"type":"paragraph","text":"Большие наборы косметики, ароматизированные средства, присыпки, парфюмированные масла и многочисленные кремы обычно не требуются. Новорождённому не нужен ежедневный сложный уход из нескольких этапов. Если кожа требует лечения, средство подбирают по конкретной причине."},{"type":"paragraph","text":"Подушка, позиционер, мягкое «гнездо» и бортики не нужны для сна. Не приносите их, чтобы сделать больничную кроватку уютнее: мягкие предметы могут мешать безопасному дыханию."},{"type":"heading","text":"Что с бутылочками и смесью"},{"type":"paragraph","text":"Не нужно автоматически покупать несколько видов «на всякий случай». Если планируется кормление смесью или вероятен докорм, заранее уточните, что предоставляет роддом и какие правила действуют для приготовления. При медицинской необходимости питание ребёнка организуют вместе с персоналом."},{"type":"heading","text":"Подготовьте дорогу домой"},{"type":"paragraph","text":"Если поедете на машине, заранее установите подходящее детское удерживающее устройство для новорождённого против хода движения. Потренируйтесь пользоваться ремнями по инструкции. Толстый зимний комбинезон под ремнями может мешать их плотному прилеганию; тепло обеспечивают с учётом инструкции производителя, например укрывая уже пристёгнутого малыша сверху."},{"type":"paragraph","text":"Сложите вещи на выписку отдельно и подпишите пакет. Главные критерии — удобство ухода, безопасный сон и безопасная перевозка, а не количество покупок."}]},{"id":"pregnancy-100","number":100,"week":34,"title":"Массаж промежности перед родами: что о нём известно и как его выполнять","image":null,"blocks":[{"type":"paragraph","text":"Промежность — ткани между входом во влагалище и анусом. Дородовой массаж предполагает их мягкое растяжение. Исследования показывают, что он может уменьшать вероятность эпизиотомии и травмы, требующей наложения швов, особенно перед первыми вагинальными родами."},{"type":"paragraph","text":"Это добровольная практика, а не обязательное условие подготовки. Она не гарантирует отсутствие разрывов, в том числе тяжёлых."},{"type":"heading","text":"Когда начинать"},{"type":"paragraph","text":"Обычно массаж рассматривают с 34–35 недель. На 34-й неделе удобно обсудить его с врачом или акушеркой; в рекомендациях RCOG указан старт с 35 недель."},{"type":"paragraph","text":"При кровянистых выделениях, подозрении на подтекание вод, инфекции влагалища или генитальном герпесе массаж не выполняют. Если вам ограничили проникновение из-за осложнений беременности, сначала уточните допустимость процедуры."},{"type":"heading","text":"Как подготовиться"},{"type":"paragraph","text":"Вымойте руки, коротко подстригите ногти, опорожните мочевой пузырь. Устройтесь полусидя с опорой под спиной или в другом устойчивом удобном положении. Не нужно балансировать на одной ноге."},{"type":"paragraph","text":"Используйте небольшое количество нейтрального лубриканта, подходящего для слизистых, без отдушек и раздражающих добавок. При склонности к аллергии особенно внимательно проверьте состав. Эфирные масла не подходят."},{"type":"heading","text":"Как выполнять"},{"type":"paragraph","text":"1. Осторожно введите большой палец или пальцы неглубоко во влагалище так, чтобы воздействовать на нижнюю часть его входа."},{"type":"paragraph","text":"2. Мягко направьте давление вниз, в сторону ануса, и немного в стороны. Не давите на переднюю стенку в области мочеиспускательного канала."},{"type":"paragraph","text":"3. При ощущении умеренного растяжения спокойно дышите. Затем выполняйте небольшие плавные движения по нижней дуге, напоминающей букву U."},{"type":"paragraph","text":"4. Ограничьтесь несколькими минутами. Регулярность важнее силы: достаточно коротких сеансов несколько раз в неделю, если они комфортны."},{"type":"paragraph","text":"Не нужно добиваться боли, сильного жжения или увеличивать растяжение каждый раз. При крови, болезненных сокращениях или стойком дискомфорте прекратите массаж и обратитесь за консультацией."},{"type":"heading","text":"Если самостоятельно неудобно"},{"type":"paragraph","text":"Помочь может партнёр, если вам обоим это комфортно и он соблюдает ваши указания. Отказ от массажа тоже нормален. В родах у команды остаются другие способы бережной защиты промежности, включая тёплые компрессы по ситуации."}]},{"id":"pregnancy-101","number":101,"week":34,"title":"Контакт «кожа к коже»: что происходит в первые минуты после рождения","image":null,"blocks":[{"type":"paragraph","text":"Если состояние мамы и ребёнка позволяет, после рождения малыша обсушивают и укладывают непосредственно на обнажённую грудь или живот матери. Сверху его укрывают, сохраняя лицо открытым. Это и есть контакт «кожа к коже»."},{"type":"paragraph","text":"Он помогает ребёнку сохранять тепло, адаптироваться к новой среде и знакомиться с грудью. Для мамы это возможность постепенно рассмотреть малыша и почувствовать его рядом."},{"type":"heading","text":"Что может делать ребёнок"},{"type":"paragraph","text":"Новорождённый не обязательно сразу активно ищет сосок. Он может некоторое время спокойно лежать, открывать глаза, двигать руками, облизывать губы, поворачивать голову. Персонал наблюдает за состоянием и помогает с кормлением, когда появляются признаки готовности."},{"type":"paragraph","text":"Не нужно силой прижимать голову к груди или расстраиваться, если первое прикладывание не получилось за несколько минут. Важна помощь с положением и захватом, а не соревнование со временем."},{"type":"heading","text":"Почему контакт стараются не прерывать"},{"type":"paragraph","text":"При благополучном состоянии его обычно поддерживают в течение первого часа и до завершения первого кормления. Многие обычные наблюдения можно проводить рядом с мамой. Если требуется срочная помощь, обследование или лечение имеют приоритет."},{"type":"paragraph","text":"Заранее спросите, как организуют первый час в вашем роддоме и какие процедуры действительно требуют разлучения."},{"type":"heading","text":"Безопасное положение обязательно"},{"type":"paragraph","text":"Мама должна быть достаточно бодрой, чтобы удерживать малыша, и получать помощь персонала. Голова ребёнка повернута в сторону, шея не согнута резко, нос и рот свободны, цвет кожи и дыхание доступны наблюдению."},{"type":"paragraph","text":"Если вы сильно устали, засыпаете или чувствуете дурноту, сразу скажите об этом. Контакт на груди взрослого не заменяет безопасное место для сна. Партнёр может помогать наблюдать, но медицинский контроль остаётся задачей команды."},{"type":"heading","text":"Если было кесарево сечение или разлучение"},{"type":"paragraph","text":"Контакт нередко возможен и после операции, когда состояние женщины и условия позволяют. Иногда первым малыша держит партнёр — по согласованию с персоналом и под наблюдением."},{"type":"paragraph","text":"Если сразу встретиться не удалось, контакт можно начать позже. Задержка не означает, что привязанность нарушена или грудное вскармливание невозможно. Тепло, прикосновения, кормление и забота продолжают строить отношения после первого часа жизни."}]},{"id":"pregnancy-102","number":102,"week":34,"title":"Что обсудить с партнёром до родов: 10 решений, которые лучше принять заранее","image":null,"blocks":[{"type":"paragraph","text":"В родах и первые дни после них проще опираться на конкретные договорённости. Не нужно предсказывать все события: достаточно обсудить основные вопросы и оставить возможность изменить решение."},{"type":"heading","text":"1. Кто сопровождает вас"},{"type":"paragraph","text":"Согласны ли вы оба на совместные роды? Кто сможет помочь, если партнёр заболеет или не успеет? Проверьте требования роддома заранее."},{"type":"heading","text":"2. Как вы добираетесь"},{"type":"paragraph","text":"Сохраните адрес приёмного отделения, маршрут и запасной транспорт. При экстренных симптомах нужна скорая помощь, а не обязательная поездка в заранее выбранный дальний роддом."},{"type":"heading","text":"3. Кто отвечает за вещи и документы"},{"type":"paragraph","text":"Покажите, где лежат сумки и что добавить перед выходом. Не оставляйте поиск зарядки, обменной карты и очков только на себя."},{"type":"heading","text":"4. Какая поддержка вам приятна"},{"type":"paragraph","text":"Обсудите прикосновения, массаж, музыку и короткие фразы. Договоритесь, что просьба прекратить действие выполняется сразу, без обиды."},{"type":"heading","text":"5. Как обсуждать обезболивание"},{"type":"paragraph","text":"Партнёру важно знать ваши предпочтения и поддерживать их изменение. Просьба об эпидуральной анальгезии не должна становиться поводом уговаривать «ещё потерпеть»."},{"type":"heading","text":"6. Как общаться с медицинской командой"},{"type":"paragraph","text":"Кто записывает вопросы и помогает уточнять ответы? Партнёр поддерживает ваш голос, но не подменяет его собственными решениями."},{"type":"heading","text":"7. Можно ли снимать фото и видео"},{"type":"paragraph","text":"Обсудите конкретные моменты и публикацию. Согласие на съёмку не равно согласию отправлять фотографии родственникам или размещать их в интернете."},{"type":"heading","text":"8. Кто сообщает новости близким"},{"type":"paragraph","text":"Выберите одного человека для сообщений. Можно заранее предупредить: «Мы напишем сами, когда будем готовы». Отвечать всем во время схваток не обязательно."},{"type":"heading","text":"9. Кто помогает дома"},{"type":"paragraph","text":"Распределите еду, уборку, покупки, заботу о старших детях и ночную бытовую помощь. Формулировка «разберёмся потом» менее полезна, чем понятные задачи и резервный помощник."},{"type":"heading","text":"10. Как действовать при изменении плана"},{"type":"paragraph","text":"Обсудите возможную операцию, дополнительное наблюдение за ребёнком и более долгую госпитализацию. Где будет партнёр, кто привезёт вещи, кто возьмёт домашние дела?"},{"type":"paragraph","text":"Вернитесь к договорённостям ближе к родам. Их задача — уменьшить нагрузку и поддержать вас обоих, а не создать правила, которые нельзя пересмотреть."}]},{"id":"pregnancy-103","number":103,"week":35,"title":"Организм начинает готовиться к родам: какие изменения можно заметить","image":null,"blocks":[{"type":"paragraph","text":"Ближе к концу беременности ощущения могут меняться: чаще хочется в туалет, появляются короткие напряжения живота, становится труднее найти удобную позу. Часть изменений связана с ростом и положением малыша, часть — с постепенной подготовкой тканей к родам."},{"type":"paragraph","text":"Но на 35-й неделе беременность ещё не достигла доношенного срока. Поэтому регулярные схватки или отхождение вод нельзя воспринимать как обычный финал ожидания."},{"type":"heading","text":"Живот может расположиться ниже"},{"type":"paragraph","text":"Когда предлежащая часть ребёнка опускается, иногда становится легче глубоко вдохнуть, но усиливаются давление на мочевой пузырь и дискомфорт в тазу. У одних женщин это происходит заранее, у других — только в родах."},{"type":"paragraph","text":"По фотографии или ощущению «живот опустился» нельзя определить, сколько дней осталось. Отсутствие опущения тоже не означает проблему."},{"type":"heading","text":"Нерегулярные напряжения могут стать заметнее"},{"type":"paragraph","text":"Тренировочные сокращения обычно не образуют устойчивого нарастающего ритма. При единичном безболезненном эпизоде можно остановиться, сменить положение и отдохнуть."},{"type":"paragraph","text":"Если сокращения повторяются регулярно, усиливаются, сопровождаются менструальноподобной болью, необычной болью в пояснице или давлением вниз, свяжитесь с роддомом сразу. На этом сроке не ждут правила «каждые пять минут»."},{"type":"heading","text":"Выделений иногда становится больше"},{"type":"paragraph","text":"Обычные выделения могут быть светлыми и не сопровождаться резким запахом, зудом или болью. Но водянистое подтекание, кровь, неприятный запах и жжение требуют оценки. Определять дома, воды это или выделения, по одному внешнему виду ненадёжно."},{"type":"paragraph","text":"Отхождение слизистого сгустка до 37 недель также стоит обсудить с медицинским специалистом, особенно если есть другие изменения."},{"type":"heading","text":"Чего ждать не нужно"},{"type":"paragraph","text":"Малыш не должен заметно меньше двигаться из-за подготовки к родам. При уменьшении или существенном изменении шевелений обращайтесь сразу."},{"type":"paragraph","text":"Сильная головная боль, нарушения зрения, боль вверху живота и резкое ухудшение самочувствия тоже не относятся к обычным предвестникам."},{"type":"heading","text":"Как провести ближайшие недели"},{"type":"paragraph","text":"Сохраняйте посильный режим, заканчивайте сборы постепенно и уточните план приёмов. Наличие или отсутствие «предвестников» не оценивает вашу готовность. Надёжнее ориентироваться на срок, конкретные симптомы и рекомендации наблюдающей команды."}]},{"id":"pregnancy-104","number":104,"week":35,"title":"Анализ на стрептококк группы B: зачем его могут предложить перед родами","image":null,"blocks":[{"type":"paragraph","text":"Стрептококк группы B, или Streptococcus agalactiae, может присутствовать в кишечнике и половых путях без каких-либо жалоб. Носительство не означает плохую гигиену и не считается классической инфекцией, передающейся половым путём."},{"type":"paragraph","text":"Для большинства взрослых бактерия не вызывает болезни. Но при родах она иногда передаётся ребёнку и может стать причиной тяжёлой инфекции. Анализ помогает заранее спланировать профилактику."},{"type":"heading","text":"Когда и как берут материал"},{"type":"paragraph","text":"Российские рекомендации «Нормальная беременность» предусматривают обследование в 35–37 недель. Исследуют материал из влагалища и прямой кишки с помощью посева или предусмотренного протоколом молекулярного метода."},{"type":"paragraph","text":"Это отдельное исследование: обычный мазок на флору или давний анализ мочи не всегда его заменяет. Уточните у врача, какой анализ назначен, где его выполнить и требуется ли подготовка. Самостоятельно проводить спринцевания или использовать антисептики перед мазком не нужно."},{"type":"heading","text":"Если результат положительный"},{"type":"paragraph","text":"Обычно планируют введение антибиотика внутривенно во время родов, чтобы уменьшить риск ранней инфекции у ребёнка. Пытаться заранее «очистить организм» самостоятельным курсом антибиотика не следует: носительство может возникнуть снова."},{"type":"paragraph","text":"Инфекция мочевых путей или наличие бактерии в моче требуют отдельной оценки. Сообщите врачу, если стрептококк уже находили в эту беременность или у предыдущего ребёнка была связанная с ним инфекция."},{"type":"heading","text":"Что обязательно сообщить при поступлении"},{"type":"paragraph","text":"Покажите результат и расскажите об аллергии на антибиотики — важно описать, какая именно была реакция. При начале схваток или отхождении вод свяжитесь с роддомом без промедления: время профилактики имеет значение."},{"type":"paragraph","text":"Если результат неизвестен, команда оценит дополнительные факторы риска. Срочную необходимую помощь не откладывают ради ожидания мазка или завершения курса профилактики."},{"type":"heading","text":"Если планируется кесарево сечение"},{"type":"paragraph","text":"При операции до начала родов и при целых оболочках отдельная профилактика именно стрептококковой инфекции обычно не требуется. При этом стандартная антибиотикопрофилактика операции — другой вопрос. Если схватки начались или воды отошли раньше назначенной даты, тактика меняется."},{"type":"paragraph","text":"Положительный анализ сам по себе не означает, что ребёнок обязательно заболеет, и не является автоматическим показанием к кесареву сечению."}]},{"id":"pregnancy-105","number":105,"week":35,"title":"Сумка в роддом: финальный чек-лист мамы","image":null,"blocks":[{"type":"paragraph","text":"На 35-й неделе удобно проверить уже собранные вещи и убрать лишнее. Сначала сверьтесь со списком роддома: часть принадлежностей предоставляют на месте, а правила отделений различаются. Ни одна покупка не должна становиться условием своевременного обращения за помощью."},{"type":"heading","text":"Документы и важная информация"},{"type":"list-item","text":"Документ, удостоверяющий личность, и документы для оформления по требованиям учреждения."},{"type":"list-item","text":"Обменная карта и значимые выписки."},{"type":"list-item","text":"Результаты обследований, включая анализ на стрептококк группы B, если он готов."},{"type":"list-item","text":"Список лекарств, дозировок и аллергических реакций."},{"type":"list-item","text":"Короткий план родов, если вы его составили."},{"type":"paragraph","text":"При приёме препаратов, влияющих на свёртывание крови, отдельно уточните план действий при начале родов. Не отменяйте лечение самостоятельно. Запишите время последней дозы и сообщите его персоналу."},{"type":"heading","text":"На поступление и роды"},{"type":"paragraph","text":"Подготовьте телефон, зарядку, очки при необходимости, моющиеся тапочки и разрешённую удобную одежду. Добавьте резинку для волос и бальзам для губ. Вода и перекус — по правилам отделения и вашей клинической ситуации."},{"type":"paragraph","text":"Не нужно заранее голодать «на случай операции», если такого указания не было. При плановой процедуре правила еды и питья уточняют отдельно."},{"type":"heading","text":"На послеродовое пребывание"},{"type":"paragraph","text":"Возьмите мягкое бельё, послеродовые прокладки, средства обычной гигиены, полотенце, удобную одежду с доступом к груди. Количество сменных вещей соотнесите с предполагаемой длительностью пребывания и возможностью передачи."},{"type":"paragraph","text":"Тампоны для послеродовых выделений не подходят. Самостоятельные свечи, спреи для швов и «заживляющие» составы заранее использовать не нужно — уход определяют после осмотра."},{"type":"heading","text":"Лекарства и средства поддержки"},{"type":"paragraph","text":"Постоянные препараты берите в упаковках с названиями. Компрессионный трикотаж — если он рекомендован, подходящего размера и типа. Молокоотсос, накладки на соски и послеродовой бандаж не являются обязательными для каждой женщины."},{"type":"heading","text":"Последняя проверка"},{"type":"paragraph","text":"Подпишите отдельные пакеты, положите сверху документы, оставьте близким список того, что добавить перед выходом. Тяжёлую сумку пусть несёт сопровождающий."},{"type":"paragraph","text":"При кровотечении, уменьшении шевелений, отхождении вод или регулярных сокращениях на этом сроке сначала обращайтесь за помощью. Даже идеально собранные вещи менее важны, чем своевременная оценка состояния."}]},{"id":"pregnancy-106","number":106,"week":36,"title":"Как малыш располагается перед родами и почему положение ещё может меняться","image":null,"blocks":[{"type":"paragraph","text":"К концу беременности большинство детей располагаются головой вниз. Это называют головным предлежанием. Если ближе к выходу из матки находятся ягодицы или ноги, предлежание тазовое. При поперечном положении ребёнок лежит поперёк матки."},{"type":"paragraph","text":"Предлежание помогает планировать роды, но установить его по месту толчков, икоте или форме живота надёжно нельзя."},{"type":"heading","text":"Как врач определяет положение"},{"type":"paragraph","text":"Специалист осторожно ощупывает живот и при необходимости подтверждает результат на УЗИ. Одновременно важны расположение плаценты, количество вод, рост ребёнка и другие особенности беременности."},{"type":"paragraph","text":"На 36-й неделе поворот ещё возможен, хотя по мере роста малыша пространства для него становится меньше. Поэтому заключение обсуждают сейчас, а не откладывают до первых схваток."},{"type":"heading","text":"Если ребёнок лежит тазом вниз"},{"type":"paragraph","text":"Врач может предложить наружный акушерский поворот — попытку повернуть малыша через брюшную стенку. Его обычно рассматривают около 36–37 недель или позже с учётом ситуации."},{"type":"paragraph","text":"Процедуру выполняет подготовленный специалист в стационаре, где доступны наблюдение за сердцебиением и экстренное родоразрешение. Есть противопоказания; успех не гарантирован. Это не домашний массаж и не манипуляция, которую должен делать партнёр."},{"type":"paragraph","text":"Если тазовое предлежание сохраняется, обсуждают плановое кесарево сечение или, в подходящих условиях и при строгом отборе, вагинальные роды с опытной командой. Решение зависит от конкретных данных, а не только от желания «попробовать»."},{"type":"heading","text":"Помогут ли специальные позы"},{"type":"paragraph","text":"Надёжных оснований обещать поворот от определённой гимнастики нет. Не выполняйте опасные перевёрнутые положения и не позволяйте непрофессионалам давить на живот. Комфортная активность может оставаться частью дня, но не заменяет медицинский план."},{"type":"heading","text":"Если положение поперечное или нестабильное"},{"type":"paragraph","text":"Нужна отдельная договорённость о сроке осмотра, возможной госпитализации и действиях при отхождении вод. При таком положении повышается риск выпадения пуповины после разрыва оболочек."},{"type":"paragraph","text":"Если воды отошли или начались схватки, немедленно свяжитесь с медицинской службой. При видимой или ощущаемой во влагалище петле пуповины вызывайте скорую и не пытайтесь вправить её самостоятельно."}]},{"id":"pregnancy-107","number":107,"week":36,"title":"Что врач оценивает на последних приёмах перед родами","image":null,"blocks":[{"type":"paragraph","text":"Последние визиты нужны не только для вопроса «когда рожать». Их задача — проверить состояние женщины и ребёнка, уточнить условия родоразрешения и убедиться, что дальнейший план понятен."},{"type":"paragraph","text":"Даже если самочувствие хорошее, не пропускайте назначенное наблюдение: некоторые осложнения сначала выявляются по измерениям и анализам."},{"type":"heading","text":"Самочувствие и давление"},{"type":"paragraph","text":"Расскажите о головной боли, нарушениях зрения, боли вверху живота, зуде, одышке и новых выраженных отёках. Врач измерит давление, оценит результаты мочи и при необходимости назначит дополнительное обследование."},{"type":"paragraph","text":"Зуд ладоней и стоп, особенно усиливающийся ночью и без заметной сыпи, тоже требует внимания. Не обязательно ждать следующего приёма, если симптом появился недавно."},{"type":"heading","text":"Рост и положение ребёнка"},{"type":"paragraph","text":"Оценивают размеры матки, предлежание, сердцебиение и характер шевелений. КТГ и УЗИ выполняют в соответствии с планом и показаниями. Не каждое посещение должно включать все возможные исследования."},{"type":"paragraph","text":"Обязательно сообщите об изменении активности малыша, даже если недавно была нормальная запись КТГ."},{"type":"heading","text":"Результаты и назначения"},{"type":"paragraph","text":"Уточните, разобраны ли анализ на стрептококк группы B, показатели крови и обследования, назначенные по вашим рискам. При анемии, диабете или повышенном давлении нужен понятный план контроля и приёма препаратов."},{"type":"paragraph","text":"Покажите список лекарств. Особенно важно заранее обсудить действия при начале родов, если принимаете антикоагулянты или другие средства, влияющие на выбор обезболивания и процедур."},{"type":"heading","text":"Нужен ли осмотр на кресле"},{"type":"paragraph","text":"Влагалищное исследование не является обязательным способом предсказать дату родов при каждом визите. Его проводят по показаниям и с объяснением цели, например для оценки шейки перед индукцией."},{"type":"paragraph","text":"Состояние шейки помогает выбрать тактику, но не позволяет точно назвать день рождения. Отделение оболочек пальцем — отдельная процедура, требующая обсуждения и согласия, а не незаметное дополнение к обычному осмотру."},{"type":"heading","text":"С чем уйти с приёма"},{"type":"paragraph","text":"Запишите дату следующего контакта, адрес обращения при начале родов и план на случай достижения 41 недели. Если предложена госпитализация, уточните причину и срочность. Между визитами кровотечение, отхождение вод, уменьшение шевелений и резкое ухудшение состояния требуют обращения сразу."}]},{"id":"pregnancy-108","number":108,"week":36,"title":"Что должно быть готово дома к возвращению с новорождённым","image":null,"blocks":[{"type":"paragraph","text":"К выписке не обязательно заканчивать ремонт и покупать всё из детского магазина. Важнее подготовить безопасное место для сна, базовый уход и помощь взрослому, который восстанавливается после родов."},{"type":"paragraph","text":"Удобный вопрос для проверки: «Сможем ли мы покормить ребёнка, сменить подгузник, безопасно уложить его и сами поесть?»"},{"type":"heading","text":"Место для сна"},{"type":"paragraph","text":"Подготовьте отдельную кроватку или люльку с ровным твёрдым матрасом и подходящей натяжной простынёй. Укладывайте малыша на спину. Внутри не нужны подушка, мягкие бортики, игрушки, позиционеры и объёмные одеяла."},{"type":"paragraph","text":"В первые шесть месяцев безопаснее размещать детское спальное место в комнате родителей. Для сна не подходят диван, кресло или грудь уснувшего взрослого. Заранее продумайте, куда положить малыша, если во время кормления начинает клонить в сон."},{"type":"heading","text":"Уход без сложного оборудования"},{"type":"paragraph","text":"Достаточно запаса подгузников, простой одежды, средств для очищения кожи, термометра и места для хранения. Переодевать ребёнка можно на устойчивой поверхности. Если она высокая, всё необходимое должно находиться в пределах руки: оставлять малыша одного даже ненадолго нельзя."},{"type":"paragraph","text":"Не требуется стерилизовать квартиру. Обычная уборка, мытьё рук и отсутствие табачного дыма важнее ежедневной обработки всех поверхностей сильными средствами."},{"type":"heading","text":"Кормление и восстановление мамы"},{"type":"paragraph","text":"Подготовьте удобное сиденье с опорой, воду и простую еду. При планируемом кормлении смесью заранее изучите правила её безопасного приготовления и ухода за инвентарём. При грудном вскармливании полезнее иметь контакт специалиста, чем большой запас приспособлений без понятной задачи."},{"type":"paragraph","text":"Соберите назначенные лекарства, прокладки и удобную одежду для себя. После операции заранее уберите необходимость часто наклоняться и переносить тяжести."},{"type":"heading","text":"Помощь и контакты"},{"type":"paragraph","text":"Договоритесь, кто готовит еду, закупает продукты и помогает со старшими детьми. Уточните порядок первого осмотра новорождённого после выписки и сохраните контакты медицинской помощи."},{"type":"paragraph","text":"Посещения гостей можно отложить или сделать короткими. Людям с симптомами инфекции лучше перенести встречу."},{"type":"paragraph","text":"Самое полезное приготовление — доступная помощь. Даже полностью оборудованная детская не заменяет взрослого, который принесёт обед и позволит вам спокойно принять душ."}]},{"id":"pregnancy-109","number":109,"week":37,"title":"37 недель: начинается финальный этап ожидания родов","image":null,"blocks":[{"type":"paragraph","text":"С 37 недель роды уже не относят к преждевременным. Но это не означает, что ребёнку обязательно пора родиться сегодня или что оставшиеся недели не имеют значения. Созревание продолжается, и при благополучной беременности нет необходимости самостоятельно приближать роды."},{"type":"paragraph","text":"В международной классификации 37 недель — 38 недель и 6 дней называют ранним доношенным сроком, а 39 недель — 40 недель и 6 дней — полным доношенным. Эти различия учитывают при планировании вмешательств."},{"type":"heading","text":"Что меняется для вас"},{"type":"paragraph","text":"Проверьте, что знаете маршрут в роддом, вещи доступны, а сопровождающий понимает свою роль. Обсудите с командой, при каких схватках именно вам нужно приезжать: значение имеют первые или повторные роды, расстояние, предлежание и медицинские особенности."},{"type":"paragraph","text":"Если врач назначил плановое родоразрешение раньше ПДР, уточните причину. Необходимость родить в определённый срок может быть связана с рисками, которые не ощущаются самостоятельно."},{"type":"heading","text":"Как жить в ожидании"},{"type":"paragraph","text":"Сохраняйте удобную активность, ешьте регулярно и отдыхайте при усталости. Не нужно проводить весь день в кровати, но и длинные прогулки через боль ради «запуска» родов не полезны."},{"type":"paragraph","text":"При отсутствии противопоказаний обычная близость может оставаться частью жизни, однако надёжным способом вызвать роды она не считается. Не начинайте травяные сборы, касторовое масло или стимуляцию сосков самостоятельно."},{"type":"heading","text":"Какие изменения возможны"},{"type":"paragraph","text":"Может усилиться давление в тазу, участиться мочеиспускание или стать заметнее нерегулярное напряжение матки. Эти признаки не составляют точный календарь: роды могут начаться и без предварительных ощущений."},{"type":"paragraph","text":"Не нужно каждый вечер проверять шейку матки самостоятельно или по внешнему виду живота пытаться определить раскрытие."},{"type":"heading","text":"Что остаётся важным каждый день"},{"type":"paragraph","text":"Малыш должен продолжать двигаться в привычном для него режиме. Уменьшение активности не объясняют тем, что он «собирается родиться»."},{"type":"paragraph","text":"При подозрении на отхождение вод свяжитесь с роддомом сразу, даже без схваток. Кровотечение, сильная постоянная боль, выраженная головная боль, нарушения зрения или резкое ухудшение самочувствия также требуют срочной оценки. Доношенный срок не превращает эти симптомы в нормальные предвестники."}]},{"id":"pregnancy-110","number":110,"week":37,"title":"Слизистая пробка: что это такое и обязательно ли вы заметите её отхождение","image":null,"blocks":[{"type":"paragraph","text":"Во время беременности в канале шейки матки находится густая слизь. Она участвует в защите от восходящей инфекции. Когда шейка начинает изменяться, часть этой слизи может выходить наружу — это обычно называют отхождением пробки."},{"type":"paragraph","text":"Обязательно увидеть её целиком не получится и не требуется. Слизь может отходить небольшими порциями, оставаться незамеченной или появиться уже во время родов."},{"type":"heading","text":"Как она может выглядеть"},{"type":"paragraph","text":"Чаще это густое желеобразное отделяемое: прозрачное, беловатое, иногда розоватое или с небольшими прожилками крови. Цвет и объём различаются, поэтому по фотографии нельзя надёжно определить происхождение выделений."},{"type":"paragraph","text":"Свежая красная кровь, нарастающее кровотечение или выделения, похожие на менструацию, — не повод ждать дома, предполагая, что это пробка. Нужна срочная оценка."},{"type":"heading","text":"Означает ли это скорые роды"},{"type":"paragraph","text":"Нет точного интервала между отхождением слизи и рождением ребёнка. Роды могут начаться вскоре или спустя несколько дней. По этому признаку нельзя определить раскрытие и решить, что госпитализация уже обязательна либо, наоборот, ещё не нужна."},{"type":"paragraph","text":"При доношенной беременности, хорошем самочувствии и отсутствии других симптомов ориентируйтесь на согласованный с роддомом план. Если вы не уверены, что именно заметили, позвоните медицинскому специалисту."},{"type":"heading","text":"Как отличить от вод"},{"type":"paragraph","text":"Воды чаще ощущаются как жидкость, которая вытекает порцией или продолжает понемногу подтекать. Но надёжно различить воды, мочу и влагалищные выделения дома удаётся не всегда."},{"type":"paragraph","text":"При сомнении используйте чистую прокладку, отметьте время и свяжитесь с роддомом. Не используйте тампон и не пытайтесь обследовать влагалище пальцами. Самостоятельный домашний тест не должен откладывать обращение."},{"type":"heading","text":"Нужны ли особые действия"},{"type":"paragraph","text":"Не требуется вымывать слизь, проводить спринцевание или применять антисептики. Обычной наружной гигиены достаточно. Сам факт отхождения пробки не означает, что ребёнок полностью лишился защиты: при целых оболочках они продолжают выполнять свою функцию."},{"type":"paragraph","text":"Если подобные выделения появились до 37 недель, особенно вместе с сокращениями, болью в пояснице или давлением вниз, обратитесь за оценкой без ожидания. На любом сроке уменьшение шевелений требует отдельного срочного обращения."}]},{"id":"pregnancy-111","number":111,"week":37,"title":"Как понять, что роды действительно начинаются","image":null,"blocks":[{"type":"paragraph","text":"Чаще всего роды начинаются с сокращений матки, которые постепенно приобретают устойчивый ритм и приводят к изменениям шейки. Ощущения могут напоминать менструальную боль, стягивание живота или боль в пояснице."},{"type":"paragraph","text":"В самом начале отличить родовые схватки от других сокращений бывает непросто. Это не означает, что вы плохо подготовились."},{"type":"heading","text":"Что наблюдать во времени"},{"type":"paragraph","text":"При развивающихся родах схватки обычно становятся продолжительнее, интенсивнее и чаще. Во время сокращения живот напрягается, между схватками расслабляется. Однако начало не всегда выглядит как ровный график."},{"type":"paragraph","text":"Если ведёте записи, отмечайте длительность от начала до конца одной схватки и интервал от начала одной до начала следующей. Не нужно часами смотреть на секундомер: нескольких последовательных наблюдений достаточно, чтобы описать картину специалисту."},{"type":"heading","text":"Почему приложения недостаточно"},{"type":"paragraph","text":"Таймер не оценивает шейку матки, состояние ребёнка и медицинские риски. Его уведомление «пора ехать» не должно заменять персональную инструкцию роддома."},{"type":"paragraph","text":"При повторных или прежних быстрых родах, большой удалённости от стационара и особых обстоятельствах беременности выезжать могут рекомендовать раньше. Универсального безопасного правила для всех нет."},{"type":"heading","text":"Если отошли воды"},{"type":"paragraph","text":"Свяжитесь с роддомом сразу, даже если схваток нет. Отметьте время, цвет и запах жидкости, используйте прокладку. Не ждите, пока появится сильная боль. Дальнейшая тактика зависит в том числе от срока, результата анализа на стрептококк группы B и самочувствия."},{"type":"heading","text":"Когда не нужно наблюдать ритм дома"},{"type":"paragraph","text":"Срочная помощь нужна при кровотечении, уменьшении движений ребёнка, зелёной или коричневой жидкости, сильной постоянной боли, выраженном недомогании. При сильном позыве тужиться и ощущении, что ребёнок уже рождается, вызывайте скорую."},{"type":"heading","text":"Что спросить по телефону"},{"type":"paragraph","text":"Сообщите срок, первые ли это роды, частоту и длительность схваток, наличие вод или крови и характер шевелений. Добавьте значимые особенности: рубец на матке, тазовое предлежание, положительный анализ на стрептококк."},{"type":"paragraph","text":"Обращение из-за сомнения — нормальная часть помощи. Лучше получить ясный план, чем пытаться выдержать дома некую «правильную» продолжительность схваток."}]},{"id":"pregnancy-112","number":112,"week":38,"title":"Предвестники родов: что действительно может измениться за несколько дней до встречи с малышом","image":null,"blocks":[{"type":"paragraph","text":"Перед родами некоторые женщины замечают больше давления в тазу, изменение выделений, нерегулярные сокращения или непривычную усталость. Другие до начала схваток не ощущают почти ничего нового."},{"type":"paragraph","text":"Ни один набор предвестников не позволяет точно рассчитать день родов. Отсутствие признаков не означает, что организм «не готов»."},{"type":"heading","text":"Опущение живота"},{"type":"paragraph","text":"Когда головка располагается ниже, дыхание иногда становится свободнее, а мочеиспускание учащается. Это может произойти заранее или уже в процессе родов, особенно при повторной беременности."},{"type":"paragraph","text":"Внешнее положение живота не показывает раскрытие шейки. Самостоятельно проверять его руками или оценивать по фотографиям бессмысленно."},{"type":"heading","text":"Нерегулярные сокращения"},{"type":"paragraph","text":"Напряжения могут быть заметнее вечером или после активности. Если они не нарастают, исчезают и не сопровождаются тревожными симптомами, это не обязательно начало родов."},{"type":"paragraph","text":"Если появляется устойчивый ритм, схватки усиливаются или вам трудно с ними справляться, свяжитесь с роддомом. Самочувствие важнее попытки точно присвоить ощущениям название."},{"type":"heading","text":"Изменение выделений"},{"type":"paragraph","text":"Может отойти густая слизь, иногда с небольшими прожилками крови. Но жидкое подтекание нельзя автоматически считать пробкой, а свежую кровь — безобидным признаком раскрытия."},{"type":"paragraph","text":"При подозрении на воды или кровотечении нужна медицинская оценка, даже если срок уже доношенный."},{"type":"heading","text":"Прилив сил и изменения стула"},{"type":"paragraph","text":"Желание всё прибрать иногда называют «гнездованием», но это не медицинский прогноз. Можно закончить небольшую задачу, однако генеральная уборка через усталость не поможет подготовить шейку."},{"type":"paragraph","text":"Послабление стула тоже неспецифично. Частая диарея, температура, рвота или боль требуют внимания как возможные признаки заболевания, а не только близких родов."},{"type":"heading","text":"Что не относится к безопасным предвестникам"},{"type":"paragraph","text":"Уменьшение шевелений, сильная головная боль, нарушения зрения, постоянная боль в животе и резкое ухудшение самочувствия требуют срочного обращения."},{"type":"paragraph","text":"Пока тревожных признаков нет, сохраняйте привычный спокойный режим. Можно ограничить вопросы знакомых коротким сообщением: «Когда будут новости, мы расскажем». Ежедневное ожидание доказательств скорых родов отнимает силы, а надёжнее ориентироваться на конкретный план связи с медицинской командой."}]},{"id":"pregnancy-113","number":113,"week":38,"title":"Как могут начинаться роды: схватки, воды и другие варианты","image":null,"blocks":[{"type":"paragraph","text":"Начало родов не всегда похоже на кино, где воды отходят внезапно, а ребёнок рождается через несколько минут. Процесс может разворачиваться постепенно. Полезно знать несколько вариантов и действия при каждом из них."},{"type":"heading","text":"Вариант первый — начинаются схватки"},{"type":"paragraph","text":"Ощущения могут сначала быть умеренными и нерегулярными, затем приобретают более устойчивый ритм. Иногда болит преимущественно поясница, иногда — низ живота."},{"type":"paragraph","text":"Свяжитесь с роддомом по согласованному плану. Сообщите частоту, длительность и изменения ощущений. Если состояние позволяет оставаться дома, получите понятные критерии повторного звонка и выезда."},{"type":"heading","text":"Вариант второй — сначала отходят воды"},{"type":"paragraph","text":"Это может быть заметный поток или повторяющееся подтекание. Схватки не обязаны появиться сразу. Но отсутствие боли не означает, что можно самостоятельно ждать сутки."},{"type":"paragraph","text":"Отметьте время, используйте чистую прокладку и сразу позвоните в роддом. Врач определит срочность осмотра и дальнейшую тактику. Положительный результат на стрептококк группы B обязательно сообщите."},{"type":"paragraph","text":"Зелёные или коричневые воды, неприятный запах, кровь, температура и уменьшение шевелений требуют особенно быстрой оценки. После подозрения на разрыв оболочек не вводите ничего во влагалище и воздержитесь от секса."},{"type":"heading","text":"Вариант третий — сначала появляются слизь и тянущие ощущения"},{"type":"paragraph","text":"Изменение шейки иногда сопровождается отхождением густой слизи и слабой болью. Но такая картина может предшествовать активным родам на неопределённое время."},{"type":"paragraph","text":"Оценивайте развитие симптомов и при сомнении звоните специалисту. Сильная постоянная боль или свежая кровь не относятся к состояниям для домашнего ожидания."},{"type":"heading","text":"А если роды начинаются очень быстро"},{"type":"paragraph","text":"Выраженное давление вниз, непроизвольное натуживание и ощущение появления ребёнка — повод вызвать скорую. Не садитесь за руль и не пытайтесь любой ценой успеть в дальний выбранный роддом. Следуйте указаниям диспетчера."},{"type":"heading","text":"Что объединяет все варианты"},{"type":"paragraph","text":"Ребёнок должен продолжать двигаться. Его затихание не подтверждает начало родов и не отменяет срочного обращения. Для выбора действий важны не только схватки, но и воды, выделения, состояние женщины, движения малыша и особенности беременности."}]},{"id":"pregnancy-114","number":114,"week":38,"title":"Что делать дома в самом начале схваток","image":null,"blocks":[{"type":"paragraph","text":"Оставаться дома в начале схваток можно, если беременность доношенная, состояние благополучно и медицинская команда согласовала такой план. Если вы сомневаетесь, сначала позвоните в роддом. При отхождении вод, крови или изменении шевелений домашнее ожидание без оценки не подходит."},{"type":"paragraph","text":"Задача этого времени — сохранить силы и вовремя заметить изменения, а не ускорить раскрытие любой ценой."},{"type":"heading","text":"Обеспечьте спокойную обстановку"},{"type":"paragraph","text":"Сообщите сопровождающему, что начались ощущения. Убедитесь, что телефон заряжен, транспорт доступен, а документы лежат рядом. Не отправляйтесь на дальнюю прогулку и не оставайтесь без возможности быстро получить помощь."},{"type":"paragraph","text":"Можно приглушить свет, включить привычную музыку или продолжить спокойное занятие. Если хочется отдыхать между схватками, это полезнее, чем всё время ходить из чувства обязанности."},{"type":"heading","text":"Ешьте и пейте по согласованному плану"},{"type":"paragraph","text":"При отсутствии ограничений пейте по жажде и выбирайте небольшие порции привычной лёгкой еды. Не нужно заставлять себя есть или выпивать большие объёмы воды «для раскрытия»."},{"type":"paragraph","text":"Если есть диабет, планируется операция или врач дал специальные инструкции, следуйте им. Не принимайте самостоятельно успокоительные, спазмолитики или средства для ускорения родов."},{"type":"heading","text":"Попробуйте простую поддержку"},{"type":"paragraph","text":"Меняйте положение, опирайтесь на устойчивую поверхность, расслабляйте плечи и спокойно выдыхайте. Партнёр может массировать поясницу, если прикосновения приятны."},{"type":"paragraph","text":"Тёплый душ иногда облегчает ощущения. Избегайте перегрева и скользкого пола; попросите человека оставаться поблизости. При слабости или головокружении выйдите с помощью и сядьте."},{"type":"heading","text":"Наблюдайте без постоянного секундомера"},{"type":"paragraph","text":"Периодически отмечайте ритм схваток и их усиление. Отслеживайте привычную активность ребёнка. Не проверяйте раскрытие самостоятельно и не пытайтесь вызвать отхождение вод."},{"type":"heading","text":"Когда план нужно изменить"},{"type":"paragraph","text":"Снова свяжитесь с роддомом, если схватки усилились, вы истощены, не справляетесь с болью или хотите обезболивание. Срочная оценка нужна при водах, крови, уменьшении движений, температуре или постоянной сильной боли. При позыве тужиться вызывайте скорую."},{"type":"paragraph","text":"Не нужно заслуживать поступление определённым числом часов дома. Потребность в помощи — достаточная причина обратиться."}]},{"id":"pregnancy-115","number":115,"week":39,"title":"Первый период родов: что происходит от первых схваток до полного раскрытия","image":null,"blocks":[{"type":"paragraph","text":"Первый период родов — время, за которое шейка матки укорачивается, сглаживается и раскрывается настолько, чтобы ребёнок мог пройти дальше. Полным обычно называют раскрытие примерно 10 см."},{"type":"paragraph","text":"Это не движение по линейке с одинаковой скоростью каждый час. Начало и темп различаются, поэтому по одной схватке или единственному осмотру нельзя точно рассчитать время рождения."},{"type":"heading","text":"Латентная фаза"},{"type":"paragraph","text":"В начале шейка постепенно изменяется. Схватки могут быть нерегулярными, затихать и снова усиливаться; ощущения иногда уже довольно болезненны. Этот этап бывает длительным."},{"type":"paragraph","text":"При благополучном состоянии команда может рекомендовать отдых и наблюдение дома либо в стационаре по ситуации. Важны возможность пить, отдыхать и получать поддержку. Выраженное истощение или плохо переносимая боль — повод снова обратиться за помощью, даже если активная фаза ещё не наступила."},{"type":"heading","text":"Активная фаза"},{"type":"paragraph","text":"Схватки обычно становятся регулярнее и сильнее, раскрытие продвигается быстрее. В российских рекомендациях по нормальным родам активную фазу описывают начиная примерно с 5 см."},{"type":"paragraph","text":"Эта граница — медицинский ориентир, а не домашний критерий для выезда. Определять раскрытие должен специалист; приложение и интенсивность боли его не измеряют."},{"type":"heading","text":"Что контролирует команда"},{"type":"paragraph","text":"Оценивают самочувствие женщины, давление, пульс, температуру, сокращения матки и сердцебиение ребёнка. По показаниям проводят влагалищные исследования и КТГ. Перед осмотром должны объяснить его цель и получить согласие."},{"type":"paragraph","text":"Если прогресс медленнее ожидаемого, учитывают всю картину: фазу родов, динамику шейки, положение ребёнка, силу сокращений и состояние обоих. Одна цифра скорости раскрытия не должна быть единственным основанием для вмешательства."},{"type":"heading","text":"Что можете делать вы"},{"type":"paragraph","text":"Выбирайте удобное положение, меняйте его с помощью персонала, отдыхайте между схватками. Просите воду, помощь с туалетом и обезболивание, когда они нужны. После эпидуральной анальгезии вставать можно только после оценки безопасности."},{"type":"heading","text":"Когда появляется желание тужиться"},{"type":"paragraph","text":"Давление вниз и непроизвольный позыв сразу сообщите акушерке. Полное раскрытие, положение ребёнка и дальнейшие действия оценивают вместе. Не нужно заранее начинать сильное натуживание ради ускорения процесса. Первый период заканчивается полным раскрытием, после чего начинается этап рождения ребёнка."}]},{"id":"pregnancy-116","number":116,"week":39,"title":"Как облегчать схватки: дыхание, движение, массаж, вода и поддержка партнёра","image":null,"blocks":[{"type":"paragraph","text":"Немедикаментозные способы могут уменьшать дискомфорт и помогать чувствовать больше контроля. Они не обязаны полностью убирать боль. Можно сочетать несколько подходов и в любой момент обсудить лекарственное обезболивание."},{"type":"paragraph","text":"Лучше выбирать по ощущениям сейчас, а не пытаться выполнить все техники, изученные во время беременности."},{"type":"heading","text":"Дыхание без сложных правил"},{"type":"paragraph","text":"Попробуйте спокойный вдох и свободный выдох. На схватке обратите внимание на плечи, челюсть и кисти: их не обязательно держать напряжёнными."},{"type":"paragraph","text":"Не нужно набирать максимум воздуха или соблюдать счёт через нехватку дыхания. Если появляется головокружение, вернитесь к обычному ритму и сообщите персоналу. Звуки и спокойный выдох допустимы, если вам так легче."},{"type":"heading","text":"Движение и опора"},{"type":"paragraph","text":"Можно ходить, стоять с опорой, наклоняться вперёд, вставать на четвереньки или лежать на боку. Выбирайте устойчивые положения и меняйте их по потребности."},{"type":"paragraph","text":"КТГ и капельница не всегда исключают движение: спросите, какие варианты доступны. При слабости, снижении чувствительности ног или после обезболивания нужна помощь. Не вставайте самостоятельно, если персонал ещё не оценил безопасность."},{"type":"heading","text":"Массаж"},{"type":"paragraph","text":"Мягкое растирание поясницы или комфортное давление на область крестца иногда облегчает ощущения. Партнёр должен каждый раз уточнять силу и место прикосновения."},{"type":"paragraph","text":"Не давите на живот и не пытайтесь механически «помочь ребёнку выйти». Если прикосновения раздражают, их прекращают сразу. Поддержкой может быть просто спокойное присутствие."},{"type":"heading","text":"Вода и тепло"},{"type":"paragraph","text":"Тёплый душ или пребывание в воде в подходящих условиях могут помогать расслабиться. Возможность зависит от состояния, мониторинга и оснащения роддома. Вода должна быть комфортной, без перегрева; нужна защита от падения."},{"type":"paragraph","text":"Погружение в воду во время схваток и рождение ребёнка в воде — разные решения, которые обсуждают отдельно."},{"type":"heading","text":"Маленькие бытовые действия"},{"type":"paragraph","text":"Подать воду, поправить подушку, помочь дойти до туалета, уменьшить шум — часто полезнее постоянных советов. Между схватками оставляйте время для отдыха."},{"type":"paragraph","text":"Если выбранные способы не помогают или вы истощены, скажите об этом. Дополнительное обезболивание не отменяет вашей подготовки. При новой постоянной боли, кровотечении или резком изменении самочувствия сначала нужна оценка команды, а не очередная техника расслабления."}]},{"id":"pregnancy-117","number":117,"week":39,"title":"Обезболивание в родах: какие варианты можно обсудить заранее","image":null,"blocks":[{"type":"paragraph","text":"Переносимость схваток индивидуальна и может меняться по ходу родов. Можно заранее узнать доступные методы и оставить решение гибким. Желание получить обезболивание не означает слабость, а отказ от него сейчас не обязывает терпеть позже."},{"type":"paragraph","text":"Выбор зависит от вашего состояния, этапа родов, противопоказаний и возможностей учреждения."},{"type":"heading","text":"Немедикаментозная помощь"},{"type":"paragraph","text":"Движение, вода, массаж, дыхание и постоянная поддержка могут облегчать ощущения. Их используют самостоятельно или вместе с медицинскими методами. Обещать, что правильное дыхание обязательно заменит анальгезию, нельзя."},{"type":"heading","text":"Эпидуральная анальгезия"},{"type":"paragraph","text":"Анестезиолог устанавливает тонкий катетер в эпидуральное пространство в области поясницы. Через него вводят препараты, уменьшающие боль. Женщина обычно остаётся в сознании и может чувствовать давление и прикосновения."},{"type":"paragraph","text":"Это один из наиболее эффективных методов обезболивания схваток. При этом возможны снижение давления, зуд, неполное или неравномерное обезболивание; иногда требуется коррекция катетера. Реже возникает сильная головная боль, серьёзные осложнения редки."},{"type":"paragraph","text":"Нужны наблюдение за женщиной и ребёнком и помощь при смене положения. Метод не гарантирует полной свободы передвижения. Обсудить его можно заранее; не следует ждать некой обязательной цифры раскрытия, прежде чем впервые попросить консультацию."},{"type":"heading","text":"Системные препараты"},{"type":"paragraph","text":"Некоторые обезболивающие вводят внутривенно или внутримышечно. Они могут уменьшать боль и напряжение, но нередко вызывают сонливость и тошноту. Препараты способны влиять и на ребёнка, поэтому время применения и наблюдение имеют значение."},{"type":"heading","text":"Ингаляционное обезболивание"},{"type":"paragraph","text":"В некоторых учреждениях доступна смесь закиси азота с кислородом через маску. Она может делать ощущения более переносимыми, но обычно не устраняет их полностью. Возможны головокружение и тошнота. Уточняйте доступность заранее."},{"type":"heading","text":"Что рассказать анестезиологу"},{"type":"paragraph","text":"Сообщите об аллергии, заболеваниях крови, операциях на позвоночнике, прежних реакциях на анестезию и всех лекарствах. Особенно важны препараты, влияющие на свёртывание, и время последней дозы. Не меняйте схему самостоятельно."},{"type":"paragraph","text":"Спросите, какой метод подходит вам, как оценивают его действие и что можно предложить, если он недоступен или недостаточен. Во время родов сообщайте о сохраняющейся боли: команда сможет пересмотреть помощь."}]},{"id":"pregnancy-118","number":118,"week":40,"title":"ПДР наступила, а малыш пока не торопится: почему это нормально","image":null,"blocks":[{"type":"paragraph","text":"Предполагаемая дата родов соответствует расчётным 40 неделям. Это ориентир, а не день, когда организм обязан включить схватки. При благополучной беременности отсутствие родов именно сегодня само по себе не означает осложнение."},{"type":"paragraph","text":"Однако дальнейшее ожидание должно сопровождаться понятным медицинским планом. Фраза «ПДР приблизительная» не означает, что после неё можно перестать учитывать срок."},{"type":"heading","text":"Почему роды начинаются в разные дни"},{"type":"paragraph","text":"На расчёт влияет точность исходных данных, а длительность беременности имеет естественную вариабельность. Даже хорошо установленный срок не позволяет определить точный момент самостоятельного начала родов."},{"type":"paragraph","text":"Густая слизь, опущение живота или отсутствие тренировочных схваток тоже не дают точного прогноза."},{"type":"heading","text":"Что уточнить на ближайшем контакте"},{"type":"paragraph","text":"Проверьте дату следующего осмотра, необходимость КТГ и других исследований. Отдельно спросите, на какой день запланировано обсуждение или проведение индукции, если роды не начнутся."},{"type":"paragraph","text":"ВОЗ рекомендует индукцию при достоверно достигнутом сроке 41 неделя. В российских рекомендациях по родовозбуждению также предусмотрено предложение индукции в 41 неделю при отсутствии иных показаний. При осложнениях родоразрешение может понадобиться раньше."},{"type":"heading","text":"Как провести эти дни"},{"type":"paragraph","text":"Сохраняйте обычное питание, отдых и комфортную активность. Не требуется ежедневно устраивать длинные прогулки, уборку или подъёмы по лестнице ради схваток. Истощение не делает роды безопаснее."},{"type":"paragraph","text":"Можно заранее ограничить звонки знакомых: «Дата приблизительная, наблюдение продолжается, о рождении сообщим сами». Не нужно каждый день объяснять, почему вы ещё беременны."},{"type":"heading","text":"Какие сигналы нельзя ждать до приёма"},{"type":"paragraph","text":"Ребёнок должен продолжать двигаться в привычном режиме. При уменьшении или заметном изменении активности свяжитесь с роддомом сразу. То же относится к водам, кровотечению, сильной постоянной боли, выраженной головной боли и нарушениям зрения."},{"type":"paragraph","text":"Нормальная КТГ вчера не отменяет оценки новых симптомов сегодня."},{"type":"paragraph","text":"Если ожидание сильно тревожит, обсудите это с врачом. Можно просить объяснить пользу, риски и сроки разных вариантов. Самое полезное сейчас — знать не только предполагаемую дату родов, но и конкретную дату следующего медицинского решения."}]},{"id":"pregnancy-119","number":119,"week":40,"title":"ПДР — не срок годности: как вообще рассчитывают дату родов","image":null,"blocks":[{"type":"paragraph","text":"Акушерский срок считают от первого дня последней менструации, а не от предполагаемого зачатия. При стандартном расчёте к этой дате прибавляют 280 дней — 40 недель."},{"type":"paragraph","text":"Такой подход удобен для общей системы наблюдения, но предполагает достаточно регулярный цикл. При поздней овуляции, нерегулярных менструациях или неуверенности в дате исходный расчёт может быть неточным."},{"type":"heading","text":"Зачем используют раннее УЗИ"},{"type":"paragraph","text":"В первом триместре срок уточняют по измерениям эмбриона или плода. Раннее исследование обычно точнее позднего подходит для датировки: ближе к концу беременности индивидуальные различия размеров становятся больше."},{"type":"paragraph","text":"Если даты по менструации и раннему УЗИ расходятся, врач применяет принятые критерии и фиксирует рабочую ПДР. Не нужно самостоятельно выбирать более позднюю дату, чтобы продлить ожидание."},{"type":"heading","text":"Что происходит после ЭКО"},{"type":"paragraph","text":"При переносе эмбриона учитывают дату переноса и его возраст. Это позволяет установить срок по данным лечения. Расчёт по предполагаемой последней менструации в такой ситуации не должен подменять документированную информацию."},{"type":"heading","text":"Почему позднее УЗИ не переносит дату автоматически"},{"type":"paragraph","text":"Если на 36-й неделе размеры соответствуют средним значениям для 35-й, это не обязательно означает ошибку в сроке. Ребёнок может быть индивидуально меньше; иногда требуется исключить нарушение роста."},{"type":"paragraph","text":"Постоянно менять ПДР вслед за размерами опасно тем, что можно пропустить значимую динамику. Врач сопоставляет ранние данные, текущие измерения и клиническую картину."},{"type":"heading","text":"Как читать запись срока"},{"type":"paragraph","text":"«40+3» означает 40 полных недель и 3 дня. Разговорное «идёт 41-я неделя» может обозначать то же самое. Для решений об обследовании и родоразрешении лучше использовать точную запись в неделях и днях."},{"type":"heading","text":"Что значит дата на практике"},{"type":"paragraph","text":"ПДР не гарантирует роды в конкретный день, но помогает определить сроки обследований и момент, когда риски дальнейшего ожидания меняются. После 41 недели обсуждают активную тактику; с 42+0 беременность относят к переношенной по сроку."},{"type":"paragraph","text":"Уточните, какая ПДР зафиксирована в карте и на основании каких данных. Если исходная датировка сомнительна, врач составляет индивидуальный план — просто ждать до самой поздней из возможных дат не следует."}]},{"id":"pregnancy-120","number":120,"week":40,"title":"Можно ли приблизить начало родов естественными способами: разбираем популярные советы","image":null,"blocks":[{"type":"paragraph","text":"Когда ПДР наступила, советы «помочь организму» звучат особенно настойчиво. Но домашний способ не становится безопасным только потому, что его называют естественным. Важны доказательства, состояние женщины и ребёнка и возможность контролировать результат."},{"type":"paragraph","text":"При необходимости родоразрешения народные методы не заменяют медицинский план."},{"type":"heading","text":"Прогулки и лестницы"},{"type":"paragraph","text":"Комфортная ходьба полезна для самочувствия, но надёжно вызвать ею роды нельзя. Долгие подъёмы, приседания через боль и перенос тяжестей могут привести к усталости или падению. Двигайтесь для комфорта, а не ради рекорда."},{"type":"heading","text":"Секс"},{"type":"paragraph","text":"При неосложнённой беременности и отсутствии ограничений близость может быть допустима. Однако убедительно доказанного эффекта как метода индукции нет."},{"type":"paragraph","text":"При подозрении на отхождение вод, кровотечении или назначенном ограничении проникновения секс не используют. Если после контакта появились регулярная боль или кровь, нужна оценка."},{"type":"heading","text":"Острая еда, ананас и специальные продукты"},{"type":"paragraph","text":"Нет надёжного меню, которое предсказуемо запускает безопасные роды. Большие порции необычной еды скорее вызовут изжогу или расстройство кишечника. При диабете особенно не стоит устраивать сладкие «курсы подготовки»."},{"type":"heading","text":"Касторовое масло и травы"},{"type":"paragraph","text":"Касторовое масло может вызывать выраженную диарею, тошноту и обезвоживание. Для растительных сборов и масел не всегда известны состав, дозировка и безопасность. Самостоятельно применять их для родовозбуждения не следует."},{"type":"heading","text":"Стимуляция сосков"},{"type":"paragraph","text":"Она может повышать выделение окситоцина и вызывать сокращения. Именно поэтому её не стоит считать безобидным универсальным советом. Надёжная схема, подходящая каждой беременной без наблюдения, отсутствует. Обсуждать такую практику нужно с командой, особенно при факторах риска."},{"type":"heading","text":"А отделение плодных оболочек"},{"type":"paragraph","text":"Это медицинская процедура: во время влагалищного исследования специалист пальцем отделяет нижний участок оболочек от стенки матки, если состояние шейки позволяет. Она может повысить вероятность самостоятельного начала родов, но требует согласия и оценки противопоказаний. Самостоятельно её не выполняют."},{"type":"paragraph","text":"Спросите врача, когда нужна индукция и какие варианты доступны. Подготовленная шейка, хорошее самочувствие или желание избежать лекарств не отменяют необходимости учитывать срок и состояние ребёнка."}]},{"id":"pregnancy-121","number":121,"week":41,"title":"41 неделя: что происходит на приёме, если роды пока не начались","image":null,"blocks":[{"type":"paragraph","text":"Если наступила 41 полная неделя, а схваток нет, ближайший приём нужен для конкретного решения: когда и каким способом планировать рождение ребёнка. Это не означает, что с малышом обязательно что-то не так. Но по мере увеличения срока меняется соотношение пользы и риска дальнейшего ожидания."},{"type":"heading","text":"Сначала уточняют срок"},{"type":"paragraph","text":"Врач сверяет предполагаемую дату родов с ранними обследованиями. Особенно важно УЗИ первого триместра. Размеры ребёнка на позднем УЗИ не используют, чтобы просто «перенести ПДР» и начать отсчёт заново."},{"type":"paragraph","text":"Уточните запись в карте: 41 неделя и 0 дней — это 41+0, а разговорное «идёт сорок первая неделя» может означать другой срок."},{"type":"heading","text":"Оценивают состояние женщины и малыша"},{"type":"paragraph","text":"Врач спросит о шевелениях, выделениях, возможном подтекании вод, боли и самочувствии. Проверит давление и другие необходимые показатели. В зависимости от ситуации назначит КТГ, УЗИ и дополнительные исследования."},{"type":"paragraph","text":"Важно рассказать об уменьшении движений сразу, даже если вчера ребёнок двигался активно или недавно было хорошее КТГ."},{"type":"heading","text":"Обсуждают индукцию"},{"type":"paragraph","text":"ВОЗ рекомендует индукцию при достоверно установленном сроке 41+0. Российские рекомендации также предусматривают предложение родовозбуждения с 41 недели при отсутствии других показаний к более раннему родоразрешению."},{"type":"paragraph","text":"Врач объяснит причину предложения, возможные методы, альтернативы и риски ожидания. Если требуется оценить готовность шейки матки, влагалищное исследование проводят с вашего согласия. Состояние шейки помогает выбрать способ подготовки, но не показывает точный час начала родов."},{"type":"heading","text":"С каким планом уходить"},{"type":"paragraph","text":"У вас должны быть понятные ответы:"},{"type":"list-item","text":"когда и куда приехать для госпитализации;"},{"type":"list-item","text":"какие обследования нужны до неё;"},{"type":"list-item","text":"как поступить, если раньше начнутся схватки или отойдут воды;"},{"type":"list-item","text":"куда обращаться при изменении шевелений и других симптомах."},{"type":"paragraph","text":"Если после обсуждения вы выбираете продолжить ожидание, согласуйте сроки повторной оценки и дальнейших решений. Одного хорошего обследования недостаточно, чтобы считать любое последующее ожидание безопасным."}]},{"id":"pregnancy-122","number":122,"week":41,"title":"Как врачи наблюдают маму и малыша после ПДР","image":null,"blocks":[{"type":"paragraph","text":"После предполагаемой даты родов наблюдение помогает оценивать состояние женщины и ребёнка и выбирать время родоразрешения. Его объём зависит от точного срока, особенностей беременности и уже согласованного плана."},{"type":"paragraph","text":"Нельзя составить универсальное расписание обследований, которое одинаково подойдёт всем. При повышенном давлении, диабете, нарушениях роста ребёнка или других осложнениях тактика может отличаться."},{"type":"heading","text":"Что рассказывать на каждом контакте"},{"type":"paragraph","text":"Сообщайте, как двигается малыш, не появились ли водянистые или кровянистые выделения, головная боль, нарушения зрения и новая боль в животе. Врач оценивает давление и при необходимости назначает анализы."},{"type":"paragraph","text":"Шевеления должны сохраняться до родов. Уменьшение активности нельзя объяснять тем, что ребёнок уже большой или «копит силы»."},{"type":"heading","text":"Что показывает КТГ"},{"type":"paragraph","text":"Кардиотокография записывает сердцебиение ребёнка и маточную активность. По записи врач оценивает особенности сердечного ритма, его изменения при движениях и сокращениях."},{"type":"paragraph","text":"КТГ интерпретируют вместе с другими данными. Если запись требует уточнения, обследование могут продлить, повторить или дополнить. Самостоятельно оценивать распечатку по одному числу неправильно."},{"type":"heading","text":"Зачем может понадобиться УЗИ"},{"type":"paragraph","text":"Исследование помогает оценить количество околоплодных вод, рост и другие параметры. Допплеровское исследование кровотока используют по клинической ситуации."},{"type":"paragraph","text":"Ни количество вод, ни описание плаценты по отдельности не определяют весь план. Решение принимают с учётом срока и совокупности результатов."},{"type":"heading","text":"Чего наблюдение не гарантирует"},{"type":"paragraph","text":"Нормальное обследование отражает состояние на момент проверки. Оно не позволяет обещать, что до следующего визита ничего не изменится, и не устраняет все риски увеличения срока беременности."},{"type":"paragraph","text":"Поэтому более частые КТГ не являются равноценной заменой обсуждению рекомендованной индукции с 41 недели. Если вы пока её откладываете, нужен согласованный план повторных контактов и пересмотра решения."},{"type":"heading","text":"Когда не ждать назначенной даты"},{"type":"paragraph","text":"При уменьшении или прекращении шевелений обращайтесь сразу. Подтекание вод, кровотечение, сильная боль, выраженная головная боль и нарушения зрения также требуют срочной оценки."},{"type":"paragraph","text":"Домашний допплер не подходит для проверки благополучия малыша. Даже если вы слышите сердцебиение, при изменении движений необходимо медицинское обследование."}]},{"id":"pregnancy-123","number":123,"week":41,"title":"Индукция родов простыми словами: зачем её могут предложить и как всё происходит","image":null,"blocks":[{"type":"paragraph","text":"Индукция — медицинское начало родов до появления самостоятельной родовой деятельности. Её предлагают, когда дальнейшее продолжение беременности может быть менее безопасным, чем рождение ребёнка."},{"type":"paragraph","text":"Причиной бывает срок 41 неделя, отхождение вод без начала родов или определённые осложнения. Конкретные показания и срочность врач объясняет применительно к вашей ситуации."},{"type":"heading","text":"Сначала выбирают подходящий путь"},{"type":"paragraph","text":"Перед началом оценивают состояние женщины и ребёнка, положение малыша, расположение плаценты, сведения о предыдущих операциях и готовность шейки матки."},{"type":"paragraph","text":"Не во всех ситуациях допустимы роды через естественные родовые пути. Если они противопоказаны, обсуждают кесарево сечение. Но само предложение индукции не означает, что операция неизбежна."},{"type":"heading","text":"Если шейка ещё не готова"},{"type":"paragraph","text":"Может понадобиться её предварительное созревание. Для этого используют лекарственные средства или механические методы, например специальный баллонный катетер. Выбор зависит от показаний и противопоказаний."},{"type":"paragraph","text":"При рубце на матке некоторые препараты и схемы не подходят. Поэтому важно сообщить обо всех операциях и предоставить выписки. Самостоятельно принимать средства для «раскрытия» нельзя."},{"type":"heading","text":"Как вызывают сокращения"},{"type":"paragraph","text":"При подходящих условиях врач может предложить вскрытие плодного пузыря — амниотомию — и/или введение окситоцина через инфузию. Не каждой женщине нужны все перечисленные этапы."},{"type":"paragraph","text":"Во время подготовки и родов контролируют состояние ребёнка и сокращения матки. Слишком частые сокращения или изменения сердцебиения требуют пересмотра лечения: команда может уменьшить или прекратить введение препарата и предпринять другие действия."},{"type":"heading","text":"Сколько это занимает"},{"type":"paragraph","text":"Процесс иногда продолжается больше суток, особенно если сначала нужно подготовить шейку. Медленное начало ещё не означает неудачу. Врач оценивает динамику и объясняет, когда продолжать выбранный метод, менять его или обсуждать операцию."},{"type":"paragraph","text":"Попросите заранее рассказать, когда ожидается следующая оценка: конкретный ближайший шаг обычно понятнее обещаний точного времени родов."},{"type":"heading","text":"Можно ли обезболивание и поддержку"},{"type":"paragraph","text":"Да. Обсудите доступные способы облегчения боли, присутствие партнёра, возможность двигаться, есть и отдыхать. Условия зависят от метода и состояния здоровья."},{"type":"paragraph","text":"Вы вправе задавать вопросы на каждом этапе. Индукция меняет способ начала родов, но не отменяет объяснений, согласия и внимания к вашему комфорту."}]},{"id":"pregnancy-124","number":124,"week":42,"title":"42 неделя: каким будет план действий вместе с врачом","image":null,"blocks":[{"type":"paragraph","text":"При достижении 42 недель и 0 дней беременность относят к переношенной. Это не означает, что осложнение уже произошло, но вероятность неблагоприятных исходов возрастает, поэтому вопрос родоразрешения требует конкретного решения."},{"type":"paragraph","text":"Если у вас действительно 42+0 или больше и согласованного плана нет, свяжитесь с роддомом или наблюдающим врачом сегодня. Не откладывайте обращение до следующей недели из-за хорошего самочувствия."},{"type":"heading","text":"Уточните, о каком сроке идёт речь"},{"type":"paragraph","text":"Разговорное «началась 42-я неделя» нередко означает 41+0. В медицинской записи указывают полные недели и дни. Покажите документы с датировкой по раннему УЗИ: это поможет избежать путаницы."},{"type":"paragraph","text":"Индукцию обычно обсуждают раньше: ВОЗ рекомендует её с достоверно установленного срока 41+0. Наступление 42 недель не должно становиться первым поводом составить план."},{"type":"heading","text":"Что оценивают в роддоме"},{"type":"paragraph","text":"Врач уточнит шевеления и жалобы, проверит давление, изучит результаты обследований. По ситуации проведут КТГ, УЗИ и другие исследования. Оценят положение ребёнка, готовность шейки матки и обстоятельства, влияющие на способ родоразрешения."},{"type":"paragraph","text":"Возьмите обменную карту и выписки, особенно после операций на матке. Но при тревожных симптомах не задерживайтесь ради сбора документов."},{"type":"heading","text":"Как выбирают способ родов"},{"type":"paragraph","text":"При отсутствии противопоказаний могут предложить подготовку шейки и индукцию. Кесарево сечение выполняют по показаниям: срок сам по себе не делает операцию обязательной для каждой женщины."},{"type":"paragraph","text":"Попросите объяснить, какой метод предлагают первым, как будут контролировать ребёнка и при каких изменениях тактика станет другой."},{"type":"heading","text":"Если хочется ещё подождать"},{"type":"paragraph","text":"Обсудите это непосредственно с командой. Дополнительное наблюдение не способно устранить все риски, а нормальное КТГ не гарантирует благополучие на следующие несколько дней."},{"type":"paragraph","text":"Не пытайтесь заменить медицинский план касторовым маслом, травами, интенсивной нагрузкой или самостоятельной стимуляцией сосков."},{"type":"paragraph","text":"При уменьшении шевелений, кровотечении, подтекании вод, сильной боли или резком ухудшении самочувствия обращайтесь немедленно. На этом сроке особенно важно не объяснять новые симптомы просто затянувшимся ожиданием."}]},{"id":"pregnancy-125","number":125,"week":42,"title":"Подготовка к индукции: что взять с собой и чего ожидать в роддоме","image":null,"blocks":[{"type":"paragraph","text":"Если назначена госпитализация для индукции, собирайтесь с учётом того, что между поступлением и рождением ребёнка может пройти время. Иногда сначала требуется подготовка шейки матки, а активные схватки начинаются позже."},{"type":"paragraph","text":"Точная продолжительность заранее неизвестна. Полезнее подготовиться к нескольким этапам, чем рассчитывать обязательно родить в день поступления."},{"type":"heading","text":"Уточните организационные детали"},{"type":"paragraph","text":"Позвоните в роддом или сверьтесь с выданной памяткой: когда приехать, через какое отделение поступать и нужен ли сопровождающий. Спросите, может ли партнёр присутствовать во время подготовки или только после перевода в родильное отделение."},{"type":"paragraph","text":"Заранее обсудите еду и питьё перед поступлением. Не начинайте голодать по собственной инициативе: ограничения зависят от конкретной ситуации и указаний команды."},{"type":"heading","text":"Что положить в папку"},{"type":"paragraph","text":"Возьмите документы по списку роддома, обменную карту, направление, результаты обследований, анализ на стрептококк группы B, сведения об аллергиях и операциях."},{"type":"paragraph","text":"Отдельно запишите названия и дозы лекарств, время последнего приёма. Особенно важно заранее согласовать действия при использовании препаратов, влияющих на свёртывание крови, и лечении диабета. Не отменяйте их самостоятельно."},{"type":"heading","text":"Что пригодится для ожидания"},{"type":"paragraph","text":"Подойдут удобная одежда, моющиеся тапочки, средства гигиены, телефон с зарядкой и наушники. Можно взять книгу или другое спокойное занятие. Воду и перекус — с учётом правил отделения и разрешённого режима питания."},{"type":"paragraph","text":"Вещи для родов и послеродового периода удобно разделить: так не придётся искать нужное среди всех пакетов. Для малыша используйте список конкретного учреждения."},{"type":"heading","text":"Что происходит после поступления"},{"type":"paragraph","text":"Команда оценит состояние женщины и ребёнка, проверит показания и обсудит выбранный метод. План может измениться, если начались самостоятельные схватки, отошли воды или появились новые результаты обследования."},{"type":"paragraph","text":"Попросите объяснить ближайший этап, ожидаемые ощущения и способ позвать персонал. Сообщайте о сильной боли, кровотечении, подтекании жидкости, уменьшении движений и ухудшении самочувствия."},{"type":"heading","text":"Как сохранить силы"},{"type":"paragraph","text":"По возможности отдыхайте между процедурами. Уточняйте, можно ли сейчас ходить, принять душ, поесть и поспать. Обезболивание обсуждают по потребности и медицинской ситуации — индукция не обязывает терпеть боль без помощи."}]},{"id":"pregnancy-126","number":126,"week":42,"title":"Совсем скоро встреча: как настроиться на роды, если ожидание затянулось","image":null,"blocks":[{"type":"paragraph","text":"Когда предполагаемая дата родов давно прошла, ожидание может утомлять сильнее самой подготовки. Сообщения «Ну когда уже?», повторные обследования и неопределённость иногда вызывают раздражение, тревогу или слёзы."},{"type":"paragraph","text":"Эти чувства не означают, что вы плохо готовы к материнству. Вам не нужно постоянно оставаться спокойной и радостной. При этом на сроке 42+0 эмоциональная поддержка должна сопровождать согласованный медицинский план родоразрешения."},{"type":"heading","text":"Замените неопределённость ближайшим шагом"},{"type":"paragraph","text":"Вместо попыток угадать день рождения уточните конкретное: когда следующий осмотр, куда приехать, какой этап предлагают и когда оценят результат."},{"type":"paragraph","text":"Можно записать три вопроса для команды: «Что мы делаем сейчас?», «На что обращаем внимание?», «Когда будем принимать следующее решение?» Понимание ближайших действий помогает ориентироваться даже тогда, когда весь сценарий заранее неизвестен."},{"type":"heading","text":"Ограничьте поток вопросов"},{"type":"paragraph","text":"Вы вправе отключить уведомления и попросить близкого человека сообщать новости остальным. Подойдёт короткая фраза: «Когда будут новости, мы сами напишем. Сейчас мне полезнее спокойствие и помощь с обычными делами»."},{"type":"paragraph","text":"Необязательно читать истории чужих родов или обсуждать каждый результат обследования со всеми родственниками."},{"type":"heading","text":"Сохраняйте силы"},{"type":"paragraph","text":"Если команда разрешает обычный режим, ешьте, пейте и отдыхайте. Выбирайте приятные спокойные занятия. Не превращайте последний день ожидания в генеральную уборку или многочасовую ходьбу ради начала схваток."},{"type":"paragraph","text":"Короткое расслабление может помочь: устройтесь с опорой, отпустите напряжение плеч и сделайте несколько обычных спокойных вдохов и выдохов. Цель — немного облегчить ваше состояние, а не «запустить» роды."},{"type":"heading","text":"Не обвиняйте себя"},{"type":"paragraph","text":"Нет оснований считать, что ребёнок не рождается из-за недостаточно позитивного настроя. Индукция, обезболивание или кесарево сечение по показаниям не являются оценкой ваших усилий."},{"type":"paragraph","text":"Попросите партнёра о конкретной поддержке: побыть рядом, привезти вещи, записать объяснения врача, помочь связаться с близкими."},{"type":"heading","text":"Когда нужна дополнительная помощь"},{"type":"paragraph","text":"Расскажите специалисту, если тревога не позволяет спать, есть и воспринимать информацию, возникают панические приступы или чувство безысходности. Поддержку можно получить уже сейчас."},{"type":"paragraph","text":"При уменьшении шевелений или других тревожных симптомах обращайтесь за медицинской оценкой сразу. Успокоительные практики полезны для самочувствия, но не заменяют обследование."}]}];
window.pregnancyArticleList.forEach(article => {
  article.type = `${article.week} неделя`;
  article.minutes = Math.max(1, Math.ceil(article.blocks.map(block => block.text).join(' ').split(/\s+/).length / 180));
  article.supplied = true;
  article.pregnancy = true;
  if (window.articleLibrary) window.articleLibrary[article.id] = article;
});
if (window.articleLibrary) window.articleLibrary.dating = window.pregnancyArticleList[0];
window.renderPregnancyWeekArticles = (list, week) => {
  const cards = window.pregnancyArticleList.filter(article => article.week === week).map(article => {
    const card = document.createElement('article');
    card.className = 'journey-content-card';
    card.innerHTML = '<a class="content-open"><h3></h3></a><div class="content-footer"><span class="content-type"><svg aria-hidden="true"><use href="#j-document"/></svg>Статья</span><input class="read-checkbox" type="checkbox"></div>';
    card.querySelector('a').href = `article.html?id=${article.id}&from=journey`;
    card.querySelector('h3').textContent = article.title;
    const checkbox = card.querySelector('input');
    window.articleReadState.bindCheckbox(checkbox, article.id);
    checkbox.setAttribute('aria-label', `Отметить статью ${article.title} прочитанной`);
    return card;
  });
  list.replaceChildren(...cards);
  list.scrollLeft = 0;
};
window.renderPregnancyRecommendations = (list, week, from) => {
  list.replaceChildren(...window.pregnancyArticleList.filter(article => article.week === week).map(article => {
    const card = document.createElement('a');
    card.className = 'article-card school-article';
    card.href = `article.html?id=${article.id}&from=${from}`;
    card.innerHTML = '<span class="article-meta"><span class="tag">СТАТЬЯ</span><span>·</span><span class="school-reading-time"></span></span><span class="article-title"></span><span class="article-arrow">›</span>';
    card.querySelector('.school-reading-time').textContent = `≈ ${article.minutes} мин`;
    card.querySelector('.article-title').textContent = article.title;
    return card;
  }));
};
const todayArticles = document.querySelector('.today-page .article-grid, #today .article-grid');
if (todayArticles) window.renderPregnancyRecommendations(todayArticles, 27, 'index');
